(() => {
  'use strict';

  const VERSION = '0.2.0';
  const STATUS_ID = 'tfru-status';
  const DB = {"warrior":{"build":"1.60.1.70009","className":"Warrior","pairs":[["Warrior","Воин"],["Arms","Оружие"],["Improved Heroic Strike","Улучшенный удар героя"],["Reduces the cost of your Heroic Strike ability by 1 Rage.","Снижает затраты ярости на \"Удар героя\" на 1 ед."],["Reduces the cost of your Heroic Strike ability by 2 Rage.","Снижает затраты ярости на \"Удар героя\" на 2 ед."],["Reduces the cost of your Heroic Strike ability by 3 Rage.","Снижает затраты ярости на \"Удар героя\" на 3 ед."],["Deflection","Отражение"],["Increases your Parry chance by 1%.","Увеличивает вероятность парирования атак на 1%."],["Increases your Parry chance by 2%.","Увеличивает вероятность парирования атак на 2%."],["Increases your Parry chance by 3%.","Увеличивает вероятность парирования атак на 3%."],["Increases your Parry chance by 4%.","Увеличивает вероятность парирования атак на 4%."],["Increases your Parry chance by 5%.","Увеличивает вероятность парирования атак на 5%."],["Improved Rend","Улучшенное кровопускание"],["Increases the Bleed damage done by your Rend ability by 12%.","\"Кровопускание\" наносит на 12% больше урона от кровотечения."],["Increases the Bleed damage done by your Rend ability by 23%.","\"Кровопускание\" наносит на 23% больше урона от кровотечения."],["Increases the Bleed damage done by your Rend ability by 35%.","\"Кровопускание\" наносит на 35% больше урона от кровотечения."],["Improved Charge","Улучшенный рывок"],["Increases the Rage generated by your Charge ability by 3.","\"Рывок\" дает на 3 ед. ярости больше."],["Increases the Rage generated by your Charge ability by 6.","\"Рывок\" дает на 6 ед. ярости больше."],["Improved Tactical Mastery","Улучшенное тактическое превосходство"],["Tactical Mastery lets you retain up to an additional 3 Rage when you change stances.","\"Тактическое превосходство\" позволяет сохранять еще до 3 ед. ярости при смене боевой стойки."],["Tactical Mastery lets you retain up to an additional 6 Rage when you change stances.","\"Тактическое превосходство\" позволяет сохранять еще до 6 ед. ярости при смене боевой стойки."],["Tactical Mastery lets you retain up to an additional 9 Rage when you change stances.","\"Тактическое превосходство\" позволяет сохранять еще до 9 ед. ярости при смене боевой стойки."],["Tactical Mastery lets you retain up to an additional 12 Rage when you change stances.","\"Тактическое превосходство\" позволяет сохранять еще до 12 ед. ярости при смене боевой стойки."],["Tactical Mastery lets you retain up to an additional 15 Rage when you change stances.","\"Тактическое превосходство\" позволяет сохранять еще до 15 ед. ярости при смене боевой стойки."],["Improved Overpower","Улучшенное превосходство"],["Increases the critical strike chance of your Overpower ability by 25%.","Повышает вероятность критического удара при применении \"Превосходства\" на 25%."],["Increases the critical strike chance of your Overpower ability by 50%.","Повышает вероятность критического удара при применении \"Превосходства\" на 50%."],["Anger Management","Управление злостью"],["Generates 1 Rage every 3 sec while in combat, and reduces Rage loss while out of combat by 30%.","Дает 1 ед. ярости раз в 3 сек. при нахождении в бою и снижает потерю ярости вне боя на 30%."],["Deep Wounds","Глубокие раны"],["Your critical strikes cause your opponent to Bleed, dealing 20% of your melee weapon's average damage over 12 sec.","Критические удары вызывают у противника кровотечение, наносящее 20% среднего урона вашего оружия ближнего боя за 12 сек."],["Your critical strikes cause your opponent to Bleed, dealing 40% of your melee weapon's average damage over 12 sec.","Критические удары вызывают у противника кровотечение, наносящее 40% среднего урона вашего оружия ближнего боя за 12 сек."],["Your critical strikes cause your opponent to Bleed, dealing 60% of your melee weapon's average damage over 12 sec.","Критические удары вызывают у противника кровотечение, наносящее 60% среднего урона вашего оружия ближнего боя за 12 сек."],["Spearing Strike","Пробивающий удар"],["A brutal attack that deals 40% weapon damage. Deals an additional 80% weapon damage against Giants, Dragonkin, and mounted targets. Mounted targets are dismounted.","Совершает жестокий удар, наносящий 40% урона от оружия. Наносит еще 80% урона от оружия против великанов, драконов и целей на транспорте. Также спешивает противников."],["Two-Handed Weapon Specialization","Специализация на двуручном оружии"],["Increases the damage you deal with two-handed melee weapons by 1%.","Увеличение урона от вашего двуручного оружия ближнего боя на 1%."],["Increases the damage you deal with two-handed melee weapons by 2%.","Увеличение урона от вашего двуручного оружия ближнего боя на 2%."],["Increases the damage you deal with two-handed melee weapons by 3%.","Увеличение урона от вашего двуручного оружия ближнего боя на 3%."],["Impale","Прокалывание"],["Increases the critical strike damage bonus of your abilities by 10%.","Увеличивает дополнительный урон от критических ударов, нанесенных способностями, на 10%."],["Increases the critical strike damage bonus of your abilities by 20%.","Увеличивает дополнительный урон от критических ударов, нанесенных способностями, на 20%."],["Bloodthrill","Кровавый восторг"],["Your Main Hand melee attacks against enemies afflicted by your Rend have a 4% chance to allow the use of your Overpower ability on the target. Lasts 6 sec.","Your Main Hand melee attacks against enemies afflicted by your Rend have a 4% chance to allow the use of your Overpower ability on the target. Lasts 6 сек."],["Your Main Hand melee attacks against enemies afflicted by your Rend have a 8% chance to allow the use of your Overpower ability on the target. Lasts 6 sec.","Your Main Hand melee attacks against enemies afflicted by your Rend have a 8% chance to allow the use of your Overpower ability on the target. Lasts 6 сек."],["Your Main Hand melee attacks against enemies afflicted by your Rend have a 12% chance to allow the use of your Overpower ability on the target. Lasts 6 sec.","Your Main Hand melee attacks against enemies afflicted by your Rend have a 12% chance to allow the use of your Overpower ability on the target. Lasts 6 сек."],["Your Main Hand melee attacks against enemies afflicted by your Rend have a 16% chance to allow the use of your Overpower ability on the target. Lasts 6 sec.","Your Main Hand melee attacks against enemies afflicted by your Rend have a 16% chance to allow the use of your Overpower ability on the target. Lasts 6 сек."],["Your Main Hand melee attacks against enemies afflicted by your Rend have a 20% chance to allow the use of your Overpower ability on the target. Lasts 6 sec.","Your Main Hand melee attacks against enemies afflicted by your Rend have a 20% chance to allow the use of your Overpower ability on the target. Lasts 6 сек."],["Sweeping Strikes","Размашистые удары"],["Your next 5 melee attacks strike an additional nearby opponent.","5 ваших следующих атаки ближнего боя попадают еще по одному находящемуся рядом врагу."],["Weaponmaster","Мастер боя"],["Gives your melee weapon attacks a benefit depending on the weapon. |CFFFFFFFFAxe/Polearm: Increases your critical strike chance by 1%. |CFFFFFFFFMace/Staff: Your attacks ignore 3% of your target's armor. |CFFFFFFFFSword: Your successful melee attacks have a 1% chance to trigger an extra attack on the target.","Усиливает атаки оружием ближнего боя в зависимости от типа оружия. |CFFFFFFFFТопор/древковое: повышает вероятность критического удара на 1%. |CFFFFFFFFДробящее/посох: атаки игнорируют 3% брони цели. |CFFFFFFFFМеч: успешные атаки ближнего боя с вероятностью 1% позволяют совершить дополнительную атаку против цели."],["Gives your melee weapon attacks a benefit depending on the weapon. |CFFFFFFFFAxe/Polearm: Increases your critical strike chance by 2%. |CFFFFFFFFMace/Staff: Your attacks ignore 6% of your target's armor. |CFFFFFFFFSword: Your successful melee attacks have a 2% chance to trigger an extra attack on the target.","Усиливает атаки оружием ближнего боя в зависимости от типа оружия. |CFFFFFFFFТопор/древковое: повышает вероятность критического удара на 2%. |CFFFFFFFFДробящее/посох: атаки игнорируют 6% брони цели. |CFFFFFFFFМеч: успешные атаки ближнего боя с вероятностью 2% позволяют совершить дополнительную атаку против цели."],["Gives your melee weapon attacks a benefit depending on the weapon. |CFFFFFFFFAxe/Polearm: Increases your critical strike chance by 3%. |CFFFFFFFFMace/Staff: Your attacks ignore 9% of your target's armor. |CFFFFFFFFSword: Your successful melee attacks have a 3% chance to trigger an extra attack on the target.","Усиливает атаки оружием ближнего боя в зависимости от типа оружия. |CFFFFFFFFТопор/древковое: повышает вероятность критического удара на 3%. |CFFFFFFFFДробящее/посох: атаки игнорируют 9% брони цели. |CFFFFFFFFМеч: успешные атаки ближнего боя с вероятностью 3% позволяют совершить дополнительную атаку против цели."],["Gives your melee weapon attacks a benefit depending on the weapon. |CFFFFFFFFAxe/Polearm: Increases your critical strike chance by 4%. |CFFFFFFFFMace/Staff: Your attacks ignore 12% of your target's armor. |CFFFFFFFFSword: Your successful melee attacks have a 4% chance to trigger an extra attack on the target.","Усиливает атаки оружием ближнего боя в зависимости от типа оружия. |CFFFFFFFFТопор/древковое: повышает вероятность критического удара на 4%. |CFFFFFFFFДробящее/посох: атаки игнорируют 12% брони цели. |CFFFFFFFFМеч: успешные атаки ближнего боя с вероятностью 4% позволяют совершить дополнительную атаку против цели."],["Gives your melee weapon attacks a benefit depending on the weapon. |CFFFFFFFFAxe/Polearm: Increases your critical strike chance by 5%. |CFFFFFFFFMace/Staff: Your attacks ignore 15% of your target's armor. |CFFFFFFFFSword: Your successful melee attacks have a 5% chance to trigger an extra attack on the target.","Усиливает атаки оружием ближнего боя в зависимости от типа оружия. |CFFFFFFFFТопор/древковое: повышает вероятность критического удара на 5%. |CFFFFFFFFДробящее/посох: атаки игнорируют 15% брони цели. |CFFFFFFFFМеч: успешные атаки ближнего боя с вероятностью 5% позволяют совершить дополнительную атаку против цели."],["Improved Slam","Улучшенное сокрушение"],["Improved Hamstring","Улучшенный порез сухожилия"],["Gives your Hamstring ability a 5% chance to immobilize the target for 5 sec.","Способность \"Подрезать сухожилия\" с вероятностью 5% обездвиживает цель на 5 сек."],["Gives your Hamstring ability a 10% chance to immobilize the target for 5 sec.","Способность \"Подрезать сухожилия\" с вероятностью 10% обездвиживает цель на 5 сек."],["Gives your Hamstring ability a 15% chance to immobilize the target for 5 sec.","Способность \"Подрезать сухожилия\" с вероятностью 15% обездвиживает цель на 5 сек."],["Mortal Strike","Смертельный удар"],["A vicious strike that deals weapon damage plus 85 and wounds the target, reducing the effectiveness of any healing by 50% for 10 sec.","Жестокий удар, наносящий урон от оружия и еще 85 ед., а также оставляющий серьезную рану, снижающую эффективность исцеления на 50% в течение 10 сек."],["Fury","Неистовство"],["Booming Voice","Луженая глотка"],["Increases the radius of your Battle Shout and Demoralizing Shout abilities by 10%.","Увеличивает область действия \"Боевого крика\" и \"Деморализующего крика\" на 10%."],["Increases the radius of your Battle Shout and Demoralizing Shout abilities by 20%.","Увеличивает область действия \"Боевого крика\" и \"Деморализующего крика\" на 20%."],["Increases the radius of your Battle Shout and Demoralizing Shout abilities by 30%.","Увеличивает область действия \"Боевого крика\" и \"Деморализующего крика\" на 30%."],["Increases the radius of your Battle Shout and Demoralizing Shout abilities by 40%.","Увеличивает область действия \"Боевого крика\" и \"Деморализующего крика\" на 40%."],["Increases the radius of your Battle Shout and Demoralizing Shout abilities by 50%.","Увеличивает область действия \"Боевого крика\" и \"Деморализующего крика\" на 50%."],["Cruelty","Безжалостность"],["Improves your chance to get a critical strike with melee attacks by 1%.","Повышает вероятность критического удара атак в ближнем бою на 1%."],["Improves your chance to get a critical strike with melee attacks by 2%.","Повышает вероятность критического удара атак в ближнем бою на 2%."],["Improves your chance to get a critical strike with melee attacks by 3%.","Повышает вероятность критического удара атак в ближнем бою на 3%."],["Improves your chance to get a critical strike with melee attacks by 4%.","Повышает вероятность критического удара атак в ближнем бою на 4%."],["Improves your chance to get a critical strike with melee attacks by 5%.","Повышает вероятность критического удара атак в ближнем бою на 5%."],["Iron Will","Железная воля"],["Reduces the duration of Stun and Fear effects inflicted on you by 3%.","Сокращает время действия применяемых к вам эффектов оглушения и страха на 3%."],["Reduces the duration of Stun and Fear effects inflicted on you by 6%.","Сокращает время действия применяемых к вам эффектов оглушения и страха на 6%."],["Reduces the duration of Stun and Fear effects inflicted on you by 9%.","Сокращает время действия применяемых к вам эффектов оглушения и страха на 9%."],["Reduces the duration of Stun and Fear effects inflicted on you by 12%.","Сокращает время действия применяемых к вам эффектов оглушения и страха на 12%."],["Reduces the duration of Stun and Fear effects inflicted on you by 15%.","Сокращает время действия применяемых к вам эффектов оглушения и страха на 15%."],["Unbridled Wrath","Необузданный гнев"],["Gives you a 12% chance to generate 1 additional Rage when you deal melee damage with a weapon. This effect is increased to 2 Rage for two-handed weapons.","С вероятностью 12% вы получаете еще 1 ед. ярости при нанесении урона оружием в ближнем бою. Усиливается до 2 ед. ярости при использовании двуручного оружия."],["Gives you a 24% chance to generate 1 additional Rage when you deal melee damage with a weapon. This effect is increased to 2 Rage for two-handed weapons.","С вероятностью 24% вы получаете еще 1 ед. ярости при нанесении урона оружием в ближнем бою. Усиливается до 2 ед. ярости при использовании двуручного оружия."],["Gives you a 36% chance to generate 1 additional Rage when you deal melee damage with a weapon. This effect is increased to 2 Rage for two-handed weapons.","С вероятностью 36% вы получаете еще 1 ед. ярости при нанесении урона оружием в ближнем бою. Усиливается до 2 ед. ярости при использовании двуручного оружия."],["Gives you a 48% chance to generate 1 additional Rage when you deal melee damage with a weapon. This effect is increased to 2 Rage for two-handed weapons.","С вероятностью 48% вы получаете еще 1 ед. ярости при нанесении урона оружием в ближнем бою. Усиливается до 2 ед. ярости при использовании двуручного оружия."],["Gives you a 60% chance to generate 1 additional Rage when you deal melee damage with a weapon. This effect is increased to 2 Rage for two-handed weapons.","С вероятностью 60% вы получаете еще 1 ед. ярости при нанесении урона оружием в ближнем бою. Усиливается до 2 ед. ярости при использовании двуручного оружия."],["Improved Cleave","Улучшенный рассекающий удар"],["Reduces the Rage cost of your Cleave ability by 1.","Снижает затраты ярости на применение \"Рассекающего удара\" на 1 ед."],["Reduces the Rage cost of your Cleave ability by 2.","Снижает затраты ярости на применение \"Рассекающего удара\" на 2 ед."],["Reduces the Rage cost of your Cleave ability by 3.","Снижает затраты ярости на применение \"Рассекающего удара\" на 3 ед."],["Piercing Howl","Пронзительный вой"],["Causes all nearby enemies to be Dazed, reducing movement speed by 50% for 6 sec.","Вызывает у ближайших противников головокружение, снижающее скорость передвижения на 50% на 6 сек."],["Blood Craze","Мания крови"],["Regenerates 1% of your total Health over 6 sec after being the victim of a critical strike, dealing damage with Bloodthirst, or suffering more than 20% of your maximum Health from a single attack.","Восполняет 1% запаса здоровья за 6 сек. после получения критического удара, нанесения урона \"Кровожадностью\" или когда вы теряете более 20% максимального запаса здоровья от одной атаки."],["Regenerates 2% of your total Health over 6 sec after being the victim of a critical strike, dealing damage with Bloodthirst, or suffering more than 20% of your maximum Health from a single attack.","Восполняет 2% запаса здоровья за 6 сек. после получения критического удара, нанесения урона \"Кровожадностью\" или когда вы теряете более 20% максимального запаса здоровья от одной атаки."],["Regenerates 3% of your total Health over 6 sec after being the victim of a critical strike, dealing damage with Bloodthirst, or suffering more than 20% of your maximum Health from a single attack.","Восполняет 3% запаса здоровья за 6 сек. после получения критического удара, нанесения урона \"Кровожадностью\" или когда вы теряете более 20% максимального запаса здоровья от одной атаки."],["Boundless Rage","Безграничная ярость"],["Increases your maximum Rage by 10.","Увеличивает максимальное количество ярости на 10."],["Increases your maximum Rage by 20.","Увеличивает максимальное количество ярости на 20."],["Increases your maximum Rage by 30.","Увеличивает максимальное количество ярости на 30."],["Dual Wield Specialization","Специализация на бое двумя оружиями"],["Increases your off-hand weapon damage by 5%, off-hand Rage generation by 20%, and chance to hit with off-hand attacks by 2%.","Атаки оружием в левой руке наносят на 5% больше урона и дают на 20% больше ярости, а вероятность попадания этих атак повышается на 2%."],["Increases your off-hand weapon damage by 10%, off-hand Rage generation by 40%, and chance to hit with off-hand attacks by 4%.","Атаки оружием в левой руке наносят на 10% больше урона и дают на 40% больше ярости, а вероятность попадания этих атак повышается на 4%."],["Increases your off-hand weapon damage by 15%, off-hand Rage generation by 60%, and chance to hit with off-hand attacks by 6%.","Атаки оружием в левой руке наносят на 15% больше урона и дают на 60% больше ярости, а вероятность попадания этих атак повышается на 6%."],["Increases your off-hand weapon damage by 20%, off-hand Rage generation by 80%, and chance to hit with off-hand attacks by 8%.","Атаки оружием в левой руке наносят на 20% больше урона и дают на 80% больше ярости, а вероятность попадания этих атак повышается на 8%."],["Increases your off-hand weapon damage by 25%, off-hand Rage generation by 100%, and chance to hit with off-hand attacks by 10%.","Атаки оружием в левой руке наносят на 25% больше урона и дают на 100% больше ярости, а вероятность попадания этих атак повышается на 10%."],["Raging Blows","Яростные выпады"],["Causes your Whirlwind to also strike with your off-hand weapon, and reduces the Rage cost of your Cleave ability by 2.","При применении \"Вихря\" вы также атакуете оружием в левой руке. Затраты ярости на применение \"Рассекающего удара\" снижаются на 2 ед."],["Enrage","Исступление"],["Gives you a 30% chance to deal 2% increased Physical damage for 12 sec after being the victim of any damaging attack.","После получения урона в бою наносимый вами физический урон с вероятностью 30% увеличивается на 2% на 12 сек."],["Gives you a 30% chance to deal 4% increased Physical damage for 12 sec after being the victim of any damaging attack.","После получения урона в бою наносимый вами физический урон с вероятностью 30% увеличивается на 4% на 12 сек."],["Gives you a 30% chance to deal 6% increased Physical damage for 12 sec after being the victim of any damaging attack.","После получения урона в бою наносимый вами физический урон с вероятностью 30% увеличивается на 6% на 12 сек."],["Gives you a 30% chance to deal 8% increased Physical damage for 12 sec after being the victim of any damaging attack.","После получения урона в бою наносимый вами физический урон с вероятностью 30% увеличивается на 8% на 12 сек."],["Gives you a 30% chance to deal 10% increased Physical damage for 12 sec after being the victim of any damaging attack.","После получения урона в бою наносимый вами физический урон с вероятностью 30% увеличивается на 10% на 12 сек."],["Improved Execute","Улучшенная казнь"],["Reduces the Rage cost of your Execute ability by 3.","Уменьшает расход ярости на способность \"Казнь\" на 3."],["Reduces the Rage cost of your Execute ability by 5.","Уменьшает расход ярости на способность \"Казнь\" на 5."],["Precision","Точность"],["Improves your chance to hit by 1%.","Повышает вероятность попадания на 1%."],["Improves your chance to hit by 2%.","Повышает вероятность попадания на 2%."],["Improves your chance to hit by 3%.","Повышает вероятность попадания на 3%."],["Death Wish","Инстинкт смерти"],["When activated, increases your Physical damage done by 20% and makes you immune to Fear effects, but increases all damage you take by 5%. Lasts 30 sec.","При использовании увеличивает наносимый физический урон на 20% и дает невосприимчивость к эффекту страха, но также увеличивает получаемый урон на 5%. Время действия – 30 сек."],["Improved Intercept","Улучшенный перехват"],["Reduces the cooldown of your Intercept ability by 5 sec.","Сокращение времени восстановления вашей способности \"Перехват\" на 5 сек."],["Reduces the cooldown of your Intercept ability by 10 sec.","Сокращение времени восстановления вашей способности \"Перехват\" на 10 сек."],["Improved Berserker Rage","Улучшенная ярость берсерка"],["Your Berserker Rage ability will instantly generate 5 Rage and has a 50% chance to remove all movement impairing effects when activated.","При активации \"Ярость берсерка\" мгновенно дает 5 ед. ярости и с вероятностью 50% снимает все затрудняющие передвижение эффекты."],["Your Berserker Rage ability will instantly generate 10 Rage and has a 100% chance to remove all movement impairing effects when activated.","При активации \"Ярость берсерка\" мгновенно дает 10 ед. ярости и с вероятностью 100% снимает все затрудняющие передвижение эффекты."],["Flurry","Шквал"],["Increases your melee attack speed by 5% for your next 3 swings after dealing a melee critical strike.","После того как вы наносите критический удар в ближнем бою, скорость атаки в ближнем бою повышается на 5%. Действует, пока вы не нанесете 3 удара."],["Increases your melee attack speed by 10% for your next 3 swings after dealing a melee critical strike.","После того как вы наносите критический удар в ближнем бою, скорость атаки в ближнем бою повышается на 10%. Действует, пока вы не нанесете 3 удара."],["Increases your melee attack speed by 15% for your next 3 swings after dealing a melee critical strike.","После того как вы наносите критический удар в ближнем бою, скорость атаки в ближнем бою повышается на 15%. Действует, пока вы не нанесете 3 удара."],["Increases your melee attack speed by 20% for your next 3 swings after dealing a melee critical strike.","После того как вы наносите критический удар в ближнем бою, скорость атаки в ближнем бою повышается на 20%. Действует, пока вы не нанесете 3 удара."],["Increases your melee attack speed by 25% for your next 3 swings after dealing a melee critical strike.","После того как вы наносите критический удар в ближнем бою, скорость атаки в ближнем бою повышается на 25%. Действует, пока вы не нанесете 3 удара."],["Bloodthirst","Кровожадность"],["Instantly attack the target causing damage equal to 35% of your Attack Power plus 30 and increasing your movement speed by 10% for 10 sec.","Мгновенная атака, наносящая урон в размере 35% силы атаки и еще 30 ед., а также повышающая скорость передвижения на 10% на 10 сек."],["Protection","Защита"],["Shield Specialization","Специализация на щитах"],["Increases your chance to Block attacks with your shield by 1% and grants you a 20% chance to generate 5 Rage when you Block.","Повышает вероятность блокирования щитом на 1%. При успешном блокировании вы с вероятностью 20% накапливаете 5 ед. ярости."],["Increases your chance to Block attacks with your shield by 2% and grants you a 40% chance to generate 5 Rage when you Block.","Повышает вероятность блокирования щитом на 2%. При успешном блокировании вы с вероятностью 40% накапливаете 5 ед. ярости."],["Increases your chance to Block attacks with your shield by 3% and grants you a 60% chance to generate 5 Rage when you Block.","Повышает вероятность блокирования щитом на 3%. При успешном блокировании вы с вероятностью 60% накапливаете 5 ед. ярости."],["Increases your chance to Block attacks with your shield by 4% and grants you a 80% chance to generate 5 Rage when you Block.","Повышает вероятность блокирования щитом на 4%. При успешном блокировании вы с вероятностью 80% накапливаете 5 ед. ярости."],["Increases your chance to Block attacks with your shield by 5% and grants you a 100% chance to generate 5 Rage when you Block.","Повышает вероятность блокирования щитом на 5%. При успешном блокировании вы с вероятностью 100% накапливаете 5 ед. ярости."],["Anticipation","Предчувствие"],["Increases your Defense Skill by 4.","Повышает навык защиты на 4."],["Increases your Defense Skill by 8.","Повышает навык защиты на 8."],["Increases your Defense Skill by 12.","Повышает навык защиты на 12."],["Increases your Defense Skill by 16.","Повышает навык защиты на 16."],["Increases your Defense Skill by 20.","Повышает навык защиты на 20."],["Improved Bloodrage","Улучшенная кровавая ярость"],["Increases all the Rage generated by your Bloodrage ability by 25%.","\"Кровавая ярость\" дает на 25% больше ярости."],["Increases all the Rage generated by your Bloodrage ability by 50%.","\"Кровавая ярость\" дает на 50% больше ярости."],["Toughness","Крепость"],["Increases your Armor value from items by 2%.","Увеличивает бонус к броне от предметов на 2%."],["Increases your Armor value from items by 4%.","Увеличивает бонус к броне от предметов на 4%."],["Increases your Armor value from items by 6%.","Увеличивает бонус к броне от предметов на 6%."],["Increases your Armor value from items by 8%.","Увеличивает бонус к броне от предметов на 8%."],["Increases your Armor value from items by 10%.","Увеличивает бонус к броне от предметов на 10%."],["Improved Thunder Clap","Улучшенный удар грома"],["Reduces the Rage cost of your Thunder Clap ability by 2.","Снижает затраты ярости на \"Удар грома\" на 2 ед."],["Reduces the Rage cost of your Thunder Clap ability by 4.","Снижает затраты ярости на \"Удар грома\" на 4 ед."],["Reduces the Rage cost of your Thunder Clap ability by 6.","Снижает затраты ярости на \"Удар грома\" на 6 ед."],["Last Stand","Ни шагу назад"],["When activated, this ability temporarily grants you 30% of your maximum health for 20 sec. After the effect expires, the health is lost.","При использовании временно увеличивает максимальный запас здоровья на 30% на 20 сек. По завершении действия лишнее здоровье теряется."],["Master of Defense","Мастер обороны"],["Grants you a 50% chance to generate 5 Rage when you Dodge or Parry while a shield is equipped.","Когда вы уклоняетесь от атаки или парируете ее, держа в руке щит, вы с вероятностью 50% накапливаете 5 ед. ярости."],["Grants you a 100% chance to generate 5 Rage when you Dodge or Parry while a shield is equipped.","Когда вы уклоняетесь от атаки или парируете ее, держа в руке щит, вы с вероятностью 100% накапливаете 5 ед. ярости."],["Improved Revenge","Улучшенный реванш"],["Increases damage dealt by your Revenge ability by 20%.","Увеличивает наносимый \"Реваншем\" урон на 20%."],["Increases damage dealt by your Revenge ability by 40%.","Увеличивает наносимый \"Реваншем\" урон на 40%."],["Increases damage dealt by your Revenge ability by 60%.","Увеличивает наносимый \"Реваншем\" урон на 60%."],["Defiance","Неукротимость"],["Increases all threat generated in Defensive stance by an additional 5% while a shield is equipped.","Уровень угрозы в защитной стойке увеличивается еще на 5%, когда вы держите в руке щит."],["Increases all threat generated in Defensive stance by an additional 10% while a shield is equipped.","Уровень угрозы в защитной стойке увеличивается еще на 10%, когда вы держите в руке щит."],["Increases all threat generated in Defensive stance by an additional 15% while a shield is equipped.","Уровень угрозы в защитной стойке увеличивается еще на 15%, когда вы держите в руке щит."],["Improved Sunder Armor","Улучшенный раскол брони"],["Reduces the Rage cost of your Sunder Armor ability by 1.","Снижает затраты ярости на применение \"Раскола брони\" на 1 ед."],["Reduces the Rage cost of your Sunder Armor ability by 2.","Снижает затраты ярости на применение \"Раскола брони\" на 2 ед."],["Reduces the Rage cost of your Sunder Armor ability by 3.","Снижает затраты ярости на применение \"Раскола брони\" на 3 ед."],["Improved Disarm","Улучшенное разоружение"],["Reduces the cooldown of your Disarm ability by 7 secs.","Сокращает время восстановления \"Обезоруживания\" на 7 сек."],["Reduces the cooldown of your Disarm ability by 13 secs.","Сокращает время восстановления \"Обезоруживания\" на 13 сек."],["Reduces the cooldown of your Disarm ability by 20 secs.","Сокращает время восстановления \"Обезоруживания\" на 20 сек."],["Vanguard","Авангард"],["Your Charge ability is now usable while in Defensive Stance.","\"Рывок\" теперь можно применять в оборонительной стойке."],["Improved Shield Wall","Улучшенная глухая оборона"],["Reduces the cooldown of your Shield Wall ability by 5.5 min.","Сокращает время восстановления \"Глухой обороны\" на 5.5 мин."],["Reduces the cooldown of your Shield Wall ability by 11.0 min.","Сокращает время восстановления \"Глухой обороны\" на 11.0 мин."],["Concussion Blow","Оглушающий удар"],["Stuns the target for 5 sec.","Оглушает цель на 5 сек."],["Improved Shield Bash","Улучшенный удар щитом"],["Gives your Shield Bash ability a 50% chance to Silence the target for 3 sec.","\"Удар щитом\" с вероятностью 50% поражает цель немотой на 3 сек."],["Gives your Shield Bash ability a 100% chance to Silence the target for 3 sec.","\"Удар щитом\" с вероятностью 100% поражает цель немотой на 3 сек."],["Bastion","Бастион"],["Increases all damage you deal by 2% while a shield is equipped.","Если вы держите в руке щит, наносимый урон увеличивается на 2%."],["Increases all damage you deal by 4% while a shield is equipped.","Если вы держите в руке щит, наносимый урон увеличивается на 4%."],["Increases all damage you deal by 6% while a shield is equipped.","Если вы держите в руке щит, наносимый урон увеличивается на 6%."],["Increases all damage you deal by 8% while a shield is equipped.","Если вы держите в руке щит, наносимый урон увеличивается на 8%."],["Increases all damage you deal by 10% while a shield is equipped.","Если вы держите в руке щит, наносимый урон увеличивается на 10%."],["Focused Rage","Сосредоточенная ярость"],["Reduces the Rage cost of your offensive abilities by 1.","Снижает затраты ярости на атакующие способности на 1 ед."],["Reduces the Rage cost of your offensive abilities by 2.","Снижает затраты ярости на атакующие способности на 2 ед."],["Reduces the Rage cost of your offensive abilities by 3.","Снижает затраты ярости на атакующие способности на 3 ед."],["Shield Slam","Сокрушение щитом"],["Slam the target with your shield, causing 430 damage, increased by your Block Value, and has a 50% chance of dispelling 1 magic effect on the target. Causes a very high amount of threat.","Вы бьете цель щитом, нанося 430 ед. урона, увеличивающегося за счет показателя блока щита, и с вероятностью 50% снимаете с цели 1 магический эффект. Создает очень высокий уровень угрозы."]]},"paladin":{"build":"1.60.1.70009","className":"Paladin","pairs":[["Paladin","Паладин"],["Holy","Свет"],["Divine Strength","Божественная сила"],["Increases your Strength by 2%.","Повышает силу на 2%."],["Increases your Strength by 4%.","Повышает силу на 4%."],["Increases your Strength by 6%.","Повышает силу на 6%."],["Increases your Strength by 8%.","Повышает силу на 8%."],["Increases your Strength by 10%.","Повышает силу на 10%."],["Divine Intellect","Божественный интеллект"],["Increases your total Intellect by 2%.","Увеличение интеллекта на 2%."],["Increases your total Intellect by 4%.","Увеличение интеллекта на 4%."],["Increases your total Intellect by 6%.","Увеличение интеллекта на 6%."],["Increases your total Intellect by 8%.","Увеличение интеллекта на 8%."],["Increases your total Intellect by 10%.","Увеличение интеллекта на 10%."],["Healing Light","Исцеляющий Свет"],["Increases the amount healed by your Holy Light, Flash of Light, and Holy Shock spells by 4%.","\"Свет небес\", \"Вспышка Света\" и \"Шок небес\" восстанавливают на 4% больше здоровья."],["Increases the amount healed by your Holy Light, Flash of Light, and Holy Shock spells by 8%.","\"Свет небес\", \"Вспышка Света\" и \"Шок небес\" восстанавливают на 8% больше здоровья."],["Increases the amount healed by your Holy Light, Flash of Light, and Holy Shock spells by 12%.","\"Свет небес\", \"Вспышка Света\" и \"Шок небес\" восстанавливают на 12% больше здоровья."],["Spiritual Focus","Духовное концентрация"],["Gives your Flash of Light, Holy Light, and Light's Vigil spells a 35% chance to not lose casting time when you take damage.","Позволяет с вероятностью 35% избежать задержки при применении \"Вспышки Света\", \"Света небес\" и \"Дозора Света\", когда вы получаете урон."],["Gives your Flash of Light, Holy Light, and Light's Vigil spells a 70% chance to not lose casting time when you take damage.","Позволяет с вероятностью 70% избежать задержки при применении \"Вспышки Света\", \"Света небес\" и \"Дозора Света\", когда вы получаете урон."],["Improved Seals","Улучшенные печати"],["Increases the damage done by your Seals and Judgements by 5%.","Увеличивает урон от всех печатей и заклинаний категории \"Правосудие\" на 5%."],["Increases the damage done by your Seals and Judgements by 10%.","Увеличивает урон от всех печатей и заклинаний категории \"Правосудие\" на 10%."],["Increases the damage done by your Seals and Judgements by 15%.","Увеличивает урон от всех печатей и заклинаний категории \"Правосудие\" на 15%."],["Unyielding Faith","Непоколебимая вера"],["Reduces the duration of Fear and Disorient effects on you by 15%.","Сокращает время действия на вас эффектов страха и дезориентации на 15%."],["Reduces the duration of Fear and Disorient effects on you by 30%.","Сокращает время действия на вас эффектов страха и дезориентации на 30%."],["Voice of Truth","Глас истины"],["Grants you immunity to Silence and Interrupt effects. Lasts 6 sec.","Дает невосприимчивость к эффектам немоты и прерывания на 6 сек."],["Reverence","Благоговение"],["Allows 10% of your Mana regeneration to continue while casting.","Во время применения заклинаний мана продолжает восполняться со скоростью 10%."],["Allows 20% of your Mana regeneration to continue while casting.","Во время применения заклинаний мана продолжает восполняться со скоростью 20%."],["Allows 30% of your Mana regeneration to continue while casting.","Во время применения заклинаний мана продолжает восполняться со скоростью 30%."],["Purifying Power","Очищающая сила"],["Reduces the mana cost of your Cleanse and Purify spells by 10% and reduces the cooldown of your Exorcism and Holy Wrath spells by 17%.","Снижает затраты маны на \"Очищение\" и \"Омовение\" на 10%, а также сокращает время восстановления \"Экзорцизма\" и \"Гнева небес\" на 17%."],["Reduces the mana cost of your Cleanse and Purify spells by 20% and reduces the cooldown of your Exorcism and Holy Wrath spells by 33%.","Снижает затраты маны на \"Очищение\" и \"Омовение\" на 20%, а также сокращает время восстановления \"Экзорцизма\" и \"Гнева небес\" на 33%."],["Infusion of Light","Прилив Света"],["Your Holy Shock and Flash of Light critical hits reduce the cast time of your next Holy Light cast within 15 sec by 0.5 sec.","Критические удары \"Шока небес\" и \"Вспышки Света\" сокращают время применения следующего \"Света небес\" на 0.5 сек. Время действия – 15 сек."],["Your Holy Shock and Flash of Light critical hits reduce the cast time of your next Holy Light cast within 15 sec by 1.0 sec.","Критические удары \"Шока небес\" и \"Вспышки Света\" сокращают время применения следующего \"Света небес\" на 1.0 сек. Время действия – 15 сек."],["Illumination","Свечение"],["After getting a critical effect from your Flash of Light, Holy Light, Light's Vigil, or Holy Shock heal spell you have a 20% chance to gain Mana equal to 50% of the base cost of the spell.","При критическом эффекте заклинаний \"Вспышка Света\", \"Свет небес\", \"Дозор Света\" и критическом исцеляющем эффекте \"Шока небес\" вы с вероятностью 20% восполняете 50% базовой стоимости заклинания."],["After getting a critical effect from your Flash of Light, Holy Light, Light's Vigil, or Holy Shock heal spell you have a 40% chance to gain Mana equal to 50% of the base cost of the spell.","При критическом эффекте заклинаний \"Вспышка Света\", \"Свет небес\", \"Дозор Света\" и критическом исцеляющем эффекте \"Шока небес\" вы с вероятностью 40% восполняете 50% базовой стоимости заклинания."],["After getting a critical effect from your Flash of Light, Holy Light, Light's Vigil, or Holy Shock heal spell you have a 60% chance to gain Mana equal to 50% of the base cost of the spell.","При критическом эффекте заклинаний \"Вспышка Света\", \"Свет небес\", \"Дозор Света\" и критическом исцеляющем эффекте \"Шока небес\" вы с вероятностью 60% восполняете 50% базовой стоимости заклинания."],["After getting a critical effect from your Flash of Light, Holy Light, Light's Vigil, or Holy Shock heal spell you have a 80% chance to gain Mana equal to 50% of the base cost of the spell.","При критическом эффекте заклинаний \"Вспышка Света\", \"Свет небес\", \"Дозор Света\" и критическом исцеляющем эффекте \"Шока небес\" вы с вероятностью 80% восполняете 50% базовой стоимости заклинания."],["After getting a critical effect from your Flash of Light, Holy Light, Light's Vigil, or Holy Shock heal spell you have a 100% chance to gain Mana equal to 50% of the base cost of the spell.","При критическом эффекте заклинаний \"Вспышка Света\", \"Свет небес\", \"Дозор Света\" и критическом исцеляющем эффекте \"Шока небес\" вы с вероятностью 100% восполняете 50% базовой стоимости заклинания."],["Divine Favor","Божественное одобрение"],["When activated, gives your next Flash of Light, Holy Light, or Holy Shock spell a 100% critical effect chance.","При приведении в действие это заклинание дает вашим следующим заклинаниям \"Свет небес\", \"Вспышка Света\" или \"Шок небес\" 100% шанса на критическое воздействие."],["Divine Precision","Божественная точность"],["Improves your chance to hit with Holy spells by 6%.","Повышает вероятность попадания заклинаниями светлой магии на 6%."],["Improves your chance to hit with Holy spells by 12%.","Повышает вероятность попадания заклинаниями светлой магии на 12%."],["Improves your chance to hit with Holy spells by 18%.","Повышает вероятность попадания заклинаниями светлой магии на 18%."],["Holy Shock","Шок небес"],["Blasts the target with Holy energy, causing 129-139 Holy damage to an enemy, or 110-118 healing to an ally.","Переполняет цель мощью светлой магии, нанося 129-139 ед. урона противнику или восстанавливая 110-118 ед. здоровья союзнику."],["Consecrated Ground","Освященная земля"],["Gives your Holy spells 5% increased damage against the first 4 enemies that enter your Consecration.","Ваши заклинания светлой магии наносят на 5% больше урона 4 первым противникам, попавшим в область \"Освящения\"."],["Gives your Holy spells 10% increased damage against the first 4 enemies that enter your Consecration.","Ваши заклинания светлой магии наносят на 10% больше урона 4 первым противникам, попавшим в область \"Освящения\"."],["Holy Power","Священная сила"],["Light's Vigil","Дозор Света"],["Applies Light's Vigil to the target for 30 sec. Your next Holy Shock cast on them triggers no cooldown and causes enemy targets to suffer 175-189 Holy damage and refund 75% of Light's Vigil's Mana cost, or allied targets to heal their party for 315-333. The Paladin may only have one Light's Vigil active per party.","Applies Light's Vigil to the target for 30 сек. Your next Holy Shock cast on them triggers no cooldown and causes enemy targets to suffer 175-189 Holy damage and refund 75% of Light's Vigil's Mana cost, or allied targets to heal their party for 315-333. The Paladin may only have one Light's Vigil active per party."],["Protection","Защита"],["Toughness","Крепость"],["Increases your armor value from items by 2%.","Увеличение на 2% эффективности усиления брони за счет носимой экипировки."],["Increases your armor value from items by 4%.","Увеличение на 4% эффективности усиления брони за счет носимой экипировки."],["Increases your armor value from items by 6%.","Увеличение на 6% эффективности усиления брони за счет носимой экипировки."],["Increases your armor value from items by 8%.","Увеличение на 8% эффективности усиления брони за счет носимой экипировки."],["Increases your armor value from items by 10%.","Увеличение на 10% эффективности усиления брони за счет носимой экипировки."],["Redoubt","Оплот"],["Damaging melee attacks against you have a 10% chance to increase your chance to block by 6%. Lasts 10 sec or 5 blocks.","С вероятностью 10% после получения урона в ближнем бою вероятность блокировать удар повышается на 6%. Эффект действует 10 сек. или пока вы не заблокируете 5 ударов."],["Damaging melee attacks against you have a 10% chance to increase your chance to block by 12%. Lasts 10 sec or 5 blocks.","С вероятностью 10% после получения урона в ближнем бою вероятность блокировать удар повышается на 12%. Эффект действует 10 сек. или пока вы не заблокируете 5 ударов."],["Damaging melee attacks against you have a 10% chance to increase your chance to block by 18%. Lasts 10 sec or 5 blocks.","С вероятностью 10% после получения урона в ближнем бою вероятность блокировать удар повышается на 18%. Эффект действует 10 сек. или пока вы не заблокируете 5 ударов."],["Damaging melee attacks against you have a 10% chance to increase your chance to block by 24%. Lasts 10 sec or 5 blocks.","С вероятностью 10% после получения урона в ближнем бою вероятность блокировать удар повышается на 24%. Эффект действует 10 сек. или пока вы не заблокируете 5 ударов."],["Damaging melee attacks against you have a 10% chance to increase your chance to block by 30%. Lasts 10 sec or 5 blocks.","С вероятностью 10% после получения урона в ближнем бою вероятность блокировать удар повышается на 30%. Эффект действует 10 сек. или пока вы не заблокируете 5 ударов."],["Precision","Точность"],["Improves your chance to hit by 1%.","Повышает вероятность попадания на 1%."],["Improves your chance to hit by 2%.","Повышает вероятность попадания на 2%."],["Improves your chance to hit by 3%.","Повышает вероятность попадания на 3%."],["Guardian's Favor","Помощь стража"],["Reduces the cooldown of your Blessing of Protection by 1 min and increases the duration of your Blessing of Freedom by 3 sec.","Сокращает время восстановления \"Благословения защиты\" на 1 мин. Продлевает время действия \"Благословения свободы\" на 3 сек."],["Reduces the cooldown of your Blessing of Protection by 2 min and increases the duration of your Blessing of Freedom by 6 sec.","Сокращает время восстановления \"Благословения защиты\" на 2 мин. Продлевает время действия \"Благословения свободы\" на 6 сек."],["Anticipation","Предчувствие"],["Increases your Defense Skill by 4.","Повышает навык защиты на 4."],["Increases your Defense Skill by 8.","Повышает навык защиты на 8."],["Increases your Defense Skill by 12.","Повышает навык защиты на 12."],["Increases your Defense Skill by 16.","Повышает навык защиты на 16."],["Increases your Defense Skill by 20.","Повышает навык защиты на 20."],["Improved Seal of Fury","Улучшенная печать ярости"],["When Seal of Fury's shield is fully absorbed, restore 0 Mana, increased by 15% per level the attacker is above you, up to 45%.","Когда щит \"Печати ярости\" поглощает максимальное количество урона, вы восполняете 0 ед. маны. Если уровень атакующего противника выше вашего, вы восполняете на 15% больше маны за каждую единицу разницы в уровнях. Максимальный бонус – 45%."],["Improved Righteous Fury","Улучшенное праведное неистовство"],["While Righteous Fury is active, all damage taken is reduced by 2%.","\"Праведное неистовство\" уменьшает получаемый урон на 2%."],["While Righteous Fury is active, all damage taken is reduced by 4%.","\"Праведное неистовство\" уменьшает получаемый урон на 4%."],["While Righteous Fury is active, all damage taken is reduced by 6%.","\"Праведное неистовство\" уменьшает получаемый урон на 6%."],["Shield Specialization","Специализация на щитах"],["Increases the amount of damage absorbed by your shield by 10%, and gives your blocks a 33% chance to restore 6% of your maximum Mana. May only occur once every 3 sec.","Увеличивает количество урона, поглощаемого вашим щитом, на 10%. Блокирование атак с вероятностью 33% восполняет 6% максимального запаса маны. Срабатывает не чаще раза в 3 сек."],["Increases the amount of damage absorbed by your shield by 20%, and gives your blocks a 66% chance to restore 6% of your maximum Mana. May only occur once every 3 sec.","Увеличивает количество урона, поглощаемого вашим щитом, на 20%. Блокирование атак с вероятностью 66% восполняет 6% максимального запаса маны. Срабатывает не чаще раза в 3 сек."],["Increases the amount of damage absorbed by your shield by 30%, and gives your blocks a 100% chance to restore 6% of your maximum Mana. May only occur once every 3 sec.","Увеличивает количество урона, поглощаемого вашим щитом, на 30%. Блокирование атак с вероятностью 100% восполняет 6% максимального запаса маны. Срабатывает не чаще раза в 3 сек."],["Sacred Duty","Священный долг"],["Increases your total Stamina by 2% and reduces the cooldown of your Divine Shield, Divine Protection, and Templar's Bulwark spells by 30 sec.","Повышает выносливость на 2% и сокращает время восстановления \"Божественного щита\", \"Божественной защиты\" и \"Щита храмовника\" на 30 сек."],["Increases your total Stamina by 4% and reduces the cooldown of your Divine Shield, Divine Protection, and Templar's Bulwark spells by 60 sec.","Повышает выносливость на 4% и сокращает время восстановления \"Божественного щита\", \"Божественной защиты\" и \"Щита храмовника\" на 60 сек."],["Swift Judgement","Стремительное правосудие"],["Finishes the remaining cooldown on your Judgement ability and reduces the Mana cost of your next Judgement by 100%.","Сбрасывает оставшееся время восстановления \"Правосудия\" и снижает затраты маны на следующее применение \"Правосудия\" на 100%."],["One-Handed Weapon Specialization","Специализация на одноручном оружии"],["Increases the damage you deal with one-handed melee weapons by 3%.","Увеличение на 3% урона, наносимого используемым одноручным оружием ближнего боя."],["Increases the damage you deal with one-handed melee weapons by 7%.","Увеличение на 7% урона, наносимого используемым одноручным оружием ближнего боя."],["Increases the damage you deal with one-handed melee weapons by 10%.","Увеличение на 10% урона, наносимого используемым одноручным оружием ближнего боя."],["Improved Hammer of Justice","Улучшенный молот правосудия"],["Decreases the cooldown of your Hammer of Justice spell by 5 sec.","Сокращение времени восстановления заклинания \"Молот правосудия\" на 5 сек."],["Decreases the cooldown of your Hammer of Justice spell by 10 sec.","Сокращение времени восстановления заклинания \"Молот правосудия\" на 10 сек."],["Decreases the cooldown of your Hammer of Justice spell by 15 sec.","Сокращение времени восстановления заклинания \"Молот правосудия\" на 15 сек."],["Templar's Bulwark","Щит храмовника"],["When activated, this ability grants you an absorb shield equal to 100% of your maximum health for 8 sec. Applies Forbearance for 1 min. Cannot be cast while Forbearance is active.","При активации эта способность дает щит в размере 100% максимального запаса здоровья. Время действия – 8 сек. Применяет \"Воздержанность\" на 1 мин. Нельзя применять во время действия \"Воздержанности\"."],["Reckoning","Расплата"],["Gives you a 8% chance to gain an extra attack after Blocking a melee attack and a 20% chance to gain an extra attack after being the victim of a non-periodic critical strike.","После того как вы блокируете атаку ближнего боя, ваша следующая атака с вероятностью 8% срабатывает дважды. После того как вы получаете непериодический критический урон, ваша следующая атака с вероятностью 20% срабатывает дважды."],["Gives you a 16% chance to gain an extra attack after Blocking a melee attack and a 40% chance to gain an extra attack after being the victim of a non-periodic critical strike.","После того как вы блокируете атаку ближнего боя, ваша следующая атака с вероятностью 16% срабатывает дважды. После того как вы получаете непериодический критический урон, ваша следующая атака с вероятностью 40% срабатывает дважды."],["Gives you a 24% chance to gain an extra attack after Blocking a melee attack and a 60% chance to gain an extra attack after being the victim of a non-periodic critical strike.","После того как вы блокируете атаку ближнего боя, ваша следующая атака с вероятностью 24% срабатывает дважды. После того как вы получаете непериодический критический урон, ваша следующая атака с вероятностью 60% срабатывает дважды."],["Gives you a 32% chance to gain an extra attack after Blocking a melee attack and a 80% chance to gain an extra attack after being the victim of a non-periodic critical strike.","После того как вы блокируете атаку ближнего боя, ваша следующая атака с вероятностью 32% срабатывает дважды. После того как вы получаете непериодический критический урон, ваша следующая атака с вероятностью 80% срабатывает дважды."],["Gives you a 40% chance to gain an extra attack after Blocking a melee attack and a 100% chance to gain an extra attack after being the victim of a non-periodic critical strike.","После того как вы блокируете атаку ближнего боя, ваша следующая атака с вероятностью 40% срабатывает дважды. После того как вы получаете непериодический критический урон, ваша следующая атака с вероятностью 100% срабатывает дважды."],["Iron Creed","Железная вера"],["Increases the threat generated by your Holy Strike ability 5%. While Righteous Fury is active, Holy Strike also reduces your damage taken by 2% for 6 sec.","Увеличивает уровень угрозы от \"Священного удара\" на 5%. Пока действует \"Праведное неистовство\", \"Священный удар\" также уменьшает получаемый урон на 2% на 6 сек."],["Increases the threat generated by your Holy Strike ability 10%. While Righteous Fury is active, Holy Strike also reduces your damage taken by 4% for 6 sec.","Увеличивает уровень угрозы от \"Священного удара\" на 10%. Пока действует \"Праведное неистовство\", \"Священный удар\" также уменьшает получаемый урон на 4% на 6 сек."],["Increases the threat generated by your Holy Strike ability 15%. While Righteous Fury is active, Holy Strike also reduces your damage taken by 6% for 6 sec.","Увеличивает уровень угрозы от \"Священного удара\" на 15%. Пока действует \"Праведное неистовство\", \"Священный удар\" также уменьшает получаемый урон на 6% на 6 сек."],["Increases the threat generated by your Holy Strike ability 20%. While Righteous Fury is active, Holy Strike also reduces your damage taken by 8% for 6 sec.","Увеличивает уровень угрозы от \"Священного удара\" на 20%. Пока действует \"Праведное неистовство\", \"Священный удар\" также уменьшает получаемый урон на 8% на 6 сек."],["Increases the threat generated by your Holy Strike ability 25%. While Righteous Fury is active, Holy Strike also reduces your damage taken by 10% for 6 sec.","Увеличивает уровень угрозы от \"Священного удара\" на 25%. Пока действует \"Праведное неистовство\", \"Священный удар\" также уменьшает получаемый урон на 10% на 6 сек."],["Holy Shield","Щит небес"],["Increases chance to block by 20% for 10 sec, and deals 110 Holy damage for each attack blocked while active. Damage caused by Holy Shield causes 20% additional threat. Each block expends a charge. 4 charges.","Повышает вероятность блокировать удар на 20% на 10 сек. Пока эффект действует, при успешном блокировании вы наносите противнику 110 ед. урона от светлой магии. Урон от \"Щита небес\" создает на 20% больше угрозы. При каждом блоке расходуется 1 заряд. 4 заряда."],["Retribution","Воздаяние"],["Deflection","Отражение"],["Increases your Parry chance by 1%.","Увеличивает вероятность парирования атак на 1%."],["Increases your Parry chance by 2%.","Увеличивает вероятность парирования атак на 2%."],["Increases your Parry chance by 3%.","Увеличивает вероятность парирования атак на 3%."],["Increases your Parry chance by 4%.","Увеличивает вероятность парирования атак на 4%."],["Increases your Parry chance by 5%.","Увеличивает вероятность парирования атак на 5%."],["Benediction","Благодарение"],["Reduces the Mana cost of all instant cast spells and abilities by 2%.","Снижает затраты маны на применение мгновенных заклинаний и способностей на 2%."],["Reduces the Mana cost of all instant cast spells and abilities by 4%.","Снижает затраты маны на применение мгновенных заклинаний и способностей на 4%."],["Reduces the Mana cost of all instant cast spells and abilities by 6%.","Снижает затраты маны на применение мгновенных заклинаний и способностей на 6%."],["Reduces the Mana cost of all instant cast spells and abilities by 8%.","Снижает затраты маны на применение мгновенных заклинаний и способностей на 8%."],["Reduces the Mana cost of all instant cast spells and abilities by 10%.","Снижает затраты маны на применение мгновенных заклинаний и способностей на 10%."],["Improved Judgement","Улучшенное провосудие"],["Decreases the cooldown of your Judgement ability by 1 sec.","Сокращает время восстановления \"Правосудия\" на 1 сек."],["Decreases the cooldown of your Judgement ability by 2 sec.","Сокращает время восстановления \"Правосудия\" на 2 сек."],["Holy Conduit","Священный проводник"],["Reduces the mana cost of your Consecration, Holy Wrath, Exorcism, and Hammer of Wrath spells by 20%.","Снижает затраты маны на \"Освящение\", \"Гнев небес\", \"Экзорцизм\" и \"Молот гнева\" на 20%."],["Reduces the mana cost of your Consecration, Holy Wrath, Exorcism, and Hammer of Wrath spells by 40%.","Снижает затраты маны на \"Освящение\", \"Гнев небес\", \"Экзорцизм\" и \"Молот гнева\" на 40%."],["Conviction","Приговор"],["Improves your chance to get a critical strike with melee attacks by 1%.","Повышает вероятность критического удара атак в ближнем бою на 1%."],["Improves your chance to get a critical strike with melee attacks by 2%.","Повышает вероятность критического удара атак в ближнем бою на 2%."],["Improves your chance to get a critical strike with melee attacks by 3%.","Повышает вероятность критического удара атак в ближнем бою на 3%."],["Improves your chance to get a critical strike with melee attacks by 4%.","Повышает вероятность критического удара атак в ближнем бою на 4%."],["Improves your chance to get a critical strike with melee attacks by 5%.","Повышает вероятность критического удара атак в ближнем бою на 5%."],["Vindication","Подтверждение"],["Gives your damaging melee attacks a chance to reduce the target's Attack Power by 2, and increase your Attack Power by 1% for 30 sec.","Атакующие способности ближнего боя могут уменьшить силу атаки на цели на 2 ед. и увеличить вашу силу атаки на 1% на 30 сек."],["Gives your damaging melee attacks a chance to reduce the target's Attack Power by 4, and increase your Attack Power by 2% for 30 sec.","Атакующие способности ближнего боя могут уменьшить силу атаки на цели на 4 ед. и увеличить вашу силу атаки на 2% на 30 сек."],["Gives your damaging melee attacks a chance to reduce the target's Attack Power by 6, and increase your Attack Power by 3% for 30 sec.","Атакующие способности ближнего боя могут уменьшить силу атаки на цели на 6 ед. и увеличить вашу силу атаки на 3% на 30 сек."],["Sanctified Judgement","Священное правосудие"],["Gives your Judgement ability a 33% chance to return 20% of the Mana cost of the judged seal.","\"Правосудие\" с вероятностью 33% восполняет ману в объеме 20% затрат на применение соответствующей печати."],["Gives your Judgement ability a 66% chance to return 40% of the Mana cost of the judged seal.","\"Правосудие\" с вероятностью 66% восполняет ману в объеме 40% затрат на применение соответствующей печати."],["Gives your Judgement ability a 100% chance to return 60% of the Mana cost of the judged seal.","\"Правосудие\" с вероятностью 100% восполняет ману в объеме 60% затрат на применение соответствующей печати."],["Seal of Command","Печать повиновения"],["Gives the Paladin a chance to deal additional Holy damage equal to 70% of normal weapon damage. Only one Seal can be active on the Paladin at any one time. Lasts 30 sec. Unleashing this Seal's energy will judge an enemy, instantly causing $/2;20467s1 Holy damage, 93-101 if the target is stunned or incapacitated.","Ваши атаки с некоторой вероятностью наносят дополнительный урон от светлой магии в объеме 70% обычного урона от оружия. Одновременно на вас может действовать только одно заклинание категории \"Печать\". Время действия – 30 сек. Высвобождение энергии печати мгновенно наносит противнику $/2;20467s1 ед. урона от светлой магии. Если цель оглушена или парализована, вместо этого наносит 93-101 ед. урона."],["Pursuit of Justice","Погоня за справедливостью"],["Increases movement speed and mounted movement speed by 8%. This does not stack with other movement speed increasing effects.","Повышает скорость передвижения пешком и на транспорте на 8%. Не суммируется с другими эффектами, повышающими скорость передвижения."],["Increases movement speed and mounted movement speed by 15%. This does not stack with other movement speed increasing effects.","Повышает скорость передвижения пешком и на транспорте на 15%. Не суммируется с другими эффектами, повышающими скорость передвижения."],["Eye for an Eye","Око за око"],["All critical strikes against you cause 5% of the damage taken to the attacker as well. The damage caused by Eye for an Eye will not exceed 50% of the Paladin's total health.","Когда вы получаете критические удары, атакующий противник также получает 5% урона. Урон, наносимый способностью \"Око за око\", не может превышать 50% вашего максимального запаса здоровья."],["All critical strikes against you cause 10% of the damage taken to the attacker as well. The damage caused by Eye for an Eye will not exceed 50% of the Paladin's total health.","Когда вы получаете критические удары, атакующий противник также получает 10% урона. Урон, наносимый способностью \"Око за око\", не может превышать 50% вашего максимального запаса здоровья."],["Sacred Arbiter","Священный вершитель"],["Increases the damage of your Holy Strike ability by 20% and causes it to refresh all Judgement effects on the target.","Увеличивает наносимый \"Священным ударом\" урон на 20% и обновляет время действия всех эффектов \"Правосудия\" на цели."],["Two-Handed Weapon Specialization","Специализация на двуручном оружии"],["Increases the damage you deal with two-handed melee weapons by 2%.","Увеличение урона от вашего двуручного оружия ближнего боя на 2%."],["Increases the damage you deal with two-handed melee weapons by 4%.","Увеличение урона от вашего двуручного оружия ближнего боя на 4%."],["Increases the damage you deal with two-handed melee weapons by 6%.","Увеличение урона от вашего двуручного оружия ближнего боя на 6%."],["Vengeance","Отмщение"],["Increases your Physical and Holy damage dealt by 1% for 30 sec after landing a non-periodic critical strike. Stacks up to 3 times.","Increases your Physical and Holy damage dealt by 1% for 30 сек after landing a non-periodic critical strike. Stacks up to 3 times."],["Increases your Physical and Holy damage dealt by 2% for 30 sec after landing a non-periodic critical strike. Stacks up to 3 times.","Increases your Physical and Holy damage dealt by 2% for 30 сек after landing a non-periodic critical strike. Stacks up to 3 times."],["Increases your Physical and Holy damage dealt by 3% for 30 sec after landing a non-periodic critical strike. Stacks up to 3 times.","Increases your Physical and Holy damage dealt by 3% for 30 сек after landing a non-periodic critical strike. Stacks up to 3 times."],["Repentance","Покаяние"],["Puts the enemy target in a state of meditation, incapacitating them for up to 6 sec. Any damage caused will awaken the target. Only works against Humanoids.","Вводит противника в состояние глубокой задумчивости, лишающее возможности действовать на 6 сек. Любой нанесенный урон выводит цель из этого состояния. Действует только против гуманоидов."],["Champion of the Light","Воитель Света"],["Increases your spell damage and healing by up to 33% of your Intellect.","Увеличивает урон от заклинаний и эффективность исцеления максимум на 33% вашего интеллекта."],["Increases your spell damage and healing by up to 66% of your Intellect.","Увеличивает урон от заклинаний и эффективность исцеления максимум на 66% вашего интеллекта."],["Increases your spell damage and healing by up to 100% of your Intellect.","Увеличивает урон от заклинаний и эффективность исцеления максимум на 100% вашего интеллекта."],["Instrument of Law","Орудие закона"],["Reduces the cast time of your Hammer of Wrath by 0.5 sec, and reduces all threat you generate by 10% while Righteous Fury is not active.","Сокращает время применения \"Молота гнева\" на 0.5 сек. и снижает уровень создаваемой вами угрозы на 10%, пока не действует \"Праведное неистовство\"."],["Reduces the cast time of your Hammer of Wrath by 1.0 sec, and reduces all threat you generate by 20% while Righteous Fury is not active.","Сокращает время применения \"Молота гнева\" на 1.0 сек. и снижает уровень создаваемой вами угрозы на 20%, пока не действует \"Праведное неистовство\"."],["Twist of Light","Искаженный свет"]]},"hunter":{"build":"1.60.1.70009","className":"Hunter","pairs":[["Hunter","Охотник"],["Beast Mastery","Повелитель зверей"],["Deadly Aspects","Смертоносные духи"],["While Aspect of the Hawk is active, Auto Shot has a 2% chance of increasing ranged attack speed by 30% for 12 sec. While Aspect of the Beast is active, all melee auto attacks have a 2% chance of increasing melee attack speed by 30% for 12 sec.","Во время действия \"Духа ястреба\" автоматическая стрельба с вероятностью 2% повышает скорость атаки в дальнем бою на 30% на 12 сек. Во время действия \"Духа зверя\" автоатаки в ближнем бою с вероятностью 2% повышают скорость атаки в ближнем бою на 30% на 12 сек."],["While Aspect of the Hawk is active, Auto Shot has a 4% chance of increasing ranged attack speed by 30% for 12 sec. While Aspect of the Beast is active, all melee auto attacks have a 4% chance of increasing melee attack speed by 30% for 12 sec.","Во время действия \"Духа ястреба\" автоматическая стрельба с вероятностью 4% повышает скорость атаки в дальнем бою на 30% на 12 сек. Во время действия \"Духа зверя\" автоатаки в ближнем бою с вероятностью 4% повышают скорость атаки в ближнем бою на 30% на 12 сек."],["While Aspect of the Hawk is active, Auto Shot has a 6% chance of increasing ranged attack speed by 30% for 12 sec. While Aspect of the Beast is active, all melee auto attacks have a 6% chance of increasing melee attack speed by 30% for 12 sec.","Во время действия \"Духа ястреба\" автоматическая стрельба с вероятностью 6% повышает скорость атаки в дальнем бою на 30% на 12 сек. Во время действия \"Духа зверя\" автоатаки в ближнем бою с вероятностью 6% повышают скорость атаки в ближнем бою на 30% на 12 сек."],["While Aspect of the Hawk is active, Auto Shot has a 8% chance of increasing ranged attack speed by 30% for 12 sec. While Aspect of the Beast is active, all melee auto attacks have a 8% chance of increasing melee attack speed by 30% for 12 sec.","Во время действия \"Духа ястреба\" автоматическая стрельба с вероятностью 8% повышает скорость атаки в дальнем бою на 30% на 12 сек. Во время действия \"Духа зверя\" автоатаки в ближнем бою с вероятностью 8% повышают скорость атаки в ближнем бою на 30% на 12 сек."],["While Aspect of the Hawk is active, Auto Shot has a 10% chance of increasing ranged attack speed by 30% for 12 sec. While Aspect of the Beast is active, all melee auto attacks have a 10% chance of increasing melee attack speed by 30% for 12 sec.","Во время действия \"Духа ястреба\" автоматическая стрельба с вероятностью 10% повышает скорость атаки в дальнем бою на 30% на 12 сек. Во время действия \"Духа зверя\" автоатаки в ближнем бою с вероятностью 10% повышают скорость атаки в ближнем бою на 30% на 12 сек."],["Endurance Training","Тренировка стойкости"],["Increases the Health and Armor of your pets by 3%.","Увеличивает запас здоровья и усиливает броню ваших питомцев на 3%."],["Increases the Health and Armor of your pets by 6%.","Увеличивает запас здоровья и усиливает броню ваших питомцев на 6%."],["Increases the Health and Armor of your pets by 9%.","Увеличивает запас здоровья и усиливает броню ваших питомцев на 9%."],["Increases the Health and Armor of your pets by 12%.","Увеличивает запас здоровья и усиливает броню ваших питомцев на 12%."],["Increases the Health and Armor of your pets by 15%.","Увеличивает запас здоровья и усиливает броню ваших питомцев на 15%."],["Focused Fire","Направленный огонь"],["Increases all damage you and your pet deal by 1% while your pet is active.","Пока ваш питомец активен, вы и ваш питомец наносите на 1% больше урона."],["Increases all damage you and your pet deal by 2% while your pet is active.","Пока ваш питомец активен, вы и ваш питомец наносите на 2% больше урона."],["Improved Aspect of the Monkey","Улучшенный дух обезьяны"],["Increases the Dodge bonus of your Aspect of the Monkey by 2%. Additionally, your pet gains 50% of the effect of your Aspect of the Monkey ability.","Бонус к вероятности уклонения от \"Духа обезьяны\" увеличивается на 2%. Кроме того, ваш питомец получает 50% эффекта \"Духа обезьяны\"."],["Increases the Dodge bonus of your Aspect of the Monkey by 4%. Additionally, your pet gains 50% of the effect of your Aspect of the Monkey ability.","Бонус к вероятности уклонения от \"Духа обезьяны\" увеличивается на 4%. Кроме того, ваш питомец получает 50% эффекта \"Духа обезьяны\"."],["Increases the Dodge bonus of your Aspect of the Monkey by 6%. Additionally, your pet gains 50% of the effect of your Aspect of the Monkey ability.","Бонус к вероятности уклонения от \"Духа обезьяны\" увеличивается на 6%. Кроме того, ваш питомец получает 50% эффекта \"Духа обезьяны\"."],["Pathfinding","Знание троп"],["Increases the speed bonus of your Aspect of the Cheetah and Aspect of the Pack by 3%.","Увеличение приращения скорости при обращении к духу гепарда и духу стаи на 3%."],["Increases the speed bonus of your Aspect of the Cheetah and Aspect of the Pack by 6%.","Увеличение приращения скорости при обращении к духу гепарда и духу стаи на 6%."],["Improved Revive Pet","Улучшенное воскрешение питомца"],["Revive Pet's casting time is reduced by 3 sec, mana cost is reduced by 20%, and increases the health your pet returns with by an additional 15%.","Время наложения заклинания \"Воскрешение питомца\" уменьшается на 3 сек., расход маны уменьшается на 20%, здоровье, которым наделен ваш питомец по возвращении, увеличивается дополнительно на 15%."],["Revive Pet's casting time is reduced by 6 sec, mana cost is reduced by 40%, and increases the health your pet returns with by an additional 30%.","Время наложения заклинания \"Воскрешение питомца\" уменьшается на 6 сек., расход маны уменьшается на 40%, здоровье, которым наделен ваш питомец по возвращении, увеличивается дополнительно на 30%."],["Bestial Swiftness","Звериная стремительность"],["Increases the movement speed of your pets by 30%.","Повышает скорость передвижения ваших питомцев на 30%."],["Unleashed Fury","Неудержимое неистовство"],["Increases the damage done by your pets and hawks by 3%.","Увеличивает урон, наносимый вашими питомцами и ястребами, на 3%."],["Increases the damage done by your pets and hawks by 6%.","Увеличивает урон, наносимый вашими питомцами и ястребами, на 6%."],["Increases the damage done by your pets and hawks by 9%.","Увеличивает урон, наносимый вашими питомцами и ястребами, на 9%."],["Increases the damage done by your pets and hawks by 12%.","Увеличивает урон, наносимый вашими питомцами и ястребами, на 12%."],["Increases the damage done by your pets and hawks by 15%.","Увеличивает урон, наносимый вашими питомцами и ястребами, на 15%."],["Improved Mend Pet","Улучшенное лечение питомца"],["Gives your Mend Pet spell a 15% chance of cleansing 1 Curse, Disease, Magic, or Poison effect from your pet each time it heals and reduces the Mana cost by 10%.","\"Лечение питомца\" с вероятностью 15% снимает 1 эффект проклятия, болезни, магии или яда с каждым тактом, а также расходует на 10% меньше маны."],["Gives your Mend Pet spell a 50% chance of cleansing 1 Curse, Disease, Magic, or Poison effect from your pet each time it heals and reduces the Mana cost by 20%.","\"Лечение питомца\" с вероятностью 50% снимает 1 эффект проклятия, болезни, магии или яда с каждым тактом, а также расходует на 20% меньше маны."],["Ferocity","Свирепость"],["Increases the critical strike chance of your pets and hawks by 2%.","Повышает вероятность критического удара ваших питомцев и ястребов на 2%."],["Increases the critical strike chance of your pets and hawks by 4%.","Повышает вероятность критического удара ваших питомцев и ястребов на 4%."],["Increases the critical strike chance of your pets and hawks by 6%.","Повышает вероятность критического удара ваших питомцев и ястребов на 6%."],["Increases the critical strike chance of your pets and hawks by 8%.","Повышает вероятность критического удара ваших питомцев и ястребов на 8%."],["Increases the critical strike chance of your pets and hawks by 10%.","Повышает вероятность критического удара ваших питомцев и ястребов на 10%."],["Summon Hawk","Призыв ястреба"],["Command a hawk to dive-bomb your targeted enemy, dealing 32 + 5% of ranged attack power Physical damage and continuing its assault for 18 sec. Only 2 hawks can be active at once. Summon Hawk shares its cooldown with Arcane Shot.","Вы приказываете ястребу спикировать на цель, нанося 32 + 5% от силы атаки дальнего боя ед. физического урона, и атаковать ее в течение 18 сек. Одновременно вы можете призвать не более 2 ястребов. \"Призыв ястреба\" имеет общее время восстановления с \"Чародейским выстрелом\"."],["Spirit Bond","Узы духа"],["While your pet is active, you and your pet will regenerate 1% of total health every 10 sec.","Пока ваш питомец активен, вы и ваш питомец восстанавливаете 1% общего запаса здоровья раз в 10 сек."],["While your pet is active, you and your pet will regenerate 1% of total health every 5 sec.","Пока ваш питомец активен, вы и ваш питомец восстанавливаете 1% общего запаса здоровья раз в 5 сек."],["Intimidation","Устрашение"],["Command your pet to Stun the target for 3 sec on its next successful attack, which also gains 100% increased critical strike chance. Generates high threat.","Следующая успешная атака вашего питомца оглушает цель на 3 сек., при этом вероятность критического удара этой атаки повышается на 100%. Создает высокий уровень угрозы."],["Bestial Discipline","Беспрекословное послушание"],["Increases the Focus regeneration of your pets by 10% and allows 25% of your Mana regeneration to continue while casting.","Повышает скорость восстановления концентрации ваших питомцев на 10%. Во время применения способностей ваша мана продолжает восполняться со скоростью 25%."],["Increases the Focus regeneration of your pets by 20% and allows 50% of your Mana regeneration to continue while casting.","Повышает скорость восстановления концентрации ваших питомцев на 20%. Во время применения способностей ваша мана продолжает восполняться со скоростью 50%."],["Frenzy","Бешенство"],["Gives your pet a 20% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike.","Дает вашему питомцу 20% шанс увеличить скорость атаки на 30% в течение 8 сек после нанесения критического удара."],["Gives your pet a 40% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike.","Дает вашему питомцу 40% шанс увеличить скорость атаки на 30% в течение 8 сек после нанесения критического удара."],["Gives your pet a 60% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike.","Дает вашему питомцу 60% шанс увеличить скорость атаки на 30% в течение 8 сек после нанесения критического удара."],["Gives your pet a 80% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike.","Дает вашему питомцу 80% шанс увеличить скорость атаки на 30% в течение 8 сек после нанесения критического удара."],["Gives your pet a 100% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike.","Дает вашему питомцу 100% шанс увеличить скорость атаки на 30% в течение 8 сек после нанесения критического удара."],["Bestial Wrath","Звериный гнев"],["Send your pet into a rage causing 50% additional damage for 18 sec. While enraged, the beast does not feel pity or remorse or fear and it cannot be stopped unless killed.","Приводит питомца в ярость, увеличивая наносимый им урон на 50% на 18 сек. В состоянии ярости питомец не знает ни страха, ни жалости, и только смерть может остановить его."],["Marksmanship","Стрельба"],["Hawk Eye","Глаз ястреба"],["Increases the range of your ranged weapons by 2 yards.","Увеличение дальности применения оружия дальнего боя на 2 метра."],["Increases the range of your ranged weapons by 4 yards.","Увеличение дальности применения оружия дальнего боя на 4 метра."],["Increases the range of your ranged weapons by 6 yards.","Увеличение дальности применения оружия дальнего боя на 6 метров."],["Improved Concussive Shot","Улучшенный контузящий выстрел"],["Gives your Concussive Shot a 4% chance to stun the target for 3 sec.","Повышение до 4% вероятности оглушения противника на 3 сек при использовании способности \"Шокирующий выстрел\"."],["Gives your Concussive Shot a 8% chance to stun the target for 3 sec.","Повышение до 8% вероятности оглушения противника на 3 сек при использовании способности \"Шокирующий выстрел\"."],["Gives your Concussive Shot a 12% chance to stun the target for 3 sec.","Повышение до 12% вероятности оглушения противника на 3 сек при использовании способности \"Шокирующий выстрел\"."],["Gives your Concussive Shot a 16% chance to stun the target for 3 sec.","Повышение до 16% вероятности оглушения противника на 3 сек при использовании способности \"Шокирующий выстрел\"."],["Gives your Concussive Shot a 20% chance to stun the target for 3 sec.","Повышение до 20% вероятности оглушения противника на 3 сек при использовании способности \"Шокирующий выстрел\"."],["Lethal Attacks","Смертоносные атаки"],["Increases your critical strike chance with all attacks by 1%.","Повышает вероятность критического удара всех атак на 1%."],["Increases your critical strike chance with all attacks by 2%.","Повышает вероятность критического удара всех атак на 2%."],["Increases your critical strike chance with all attacks by 3%.","Повышает вероятность критического удара всех атак на 3%."],["Increases your critical strike chance with all attacks by 4%.","Повышает вероятность критического удара всех атак на 4%."],["Increases your critical strike chance with all attacks by 5%.","Повышает вероятность критического удара всех атак на 5%."],["Improved Stings","Смертельные укусы"],["Increased the damage of your Serpent Sting ability by 6%, reduces the cooldown of your Viper Sting ability by 2 sec, and increases the duration of your Scorpid Sting ability by 15 sec.","\"Укус змеи\" наносит на 6% больше урона, время восстановления \"Укуса гадюки\" сокращается на 2 сек., а время действия \"Укуса скорпида\" продлевается на 15 сек."],["Increased the damage of your Serpent Sting ability by 13%, reduces the cooldown of your Viper Sting ability by 4 sec, and increases the duration of your Scorpid Sting ability by 30 sec.","\"Укус змеи\" наносит на 13% больше урона, время восстановления \"Укуса гадюки\" сокращается на 4 сек., а время действия \"Укуса скорпида\" продлевается на 30 сек."],["Increased the damage of your Serpent Sting ability by 20%, reduces the cooldown of your Viper Sting ability by 6 sec, and increases the duration of your Scorpid Sting ability by 45 sec.","\"Укус змеи\" наносит на 20% больше урона, время восстановления \"Укуса гадюки\" сокращается на 6 сек., а время действия \"Укуса скорпида\" продлевается на 45 сек."],["Efficiency","Эффективность"],["Reduces the Mana cost of your Shots, Stings, and melee abilities by 3%.","Снижает затраты маны на ваши способности категории \"Выстрел\" и \"Укус\", а также способности ближнего боя на 3%."],["Reduces the Mana cost of your Shots, Stings, and melee abilities by 6%.","Снижает затраты маны на ваши способности категории \"Выстрел\" и \"Укус\", а также способности ближнего боя на 6%."],["Reduces the Mana cost of your Shots, Stings, and melee abilities by 9%.","Снижает затраты маны на ваши способности категории \"Выстрел\" и \"Укус\", а также способности ближнего боя на 9%."],["Reduces the Mana cost of your Shots, Stings, and melee abilities by 12%.","Снижает затраты маны на ваши способности категории \"Выстрел\" и \"Укус\", а также способности ближнего боя на 12%."],["Reduces the Mana cost of your Shots, Stings, and melee abilities by 15%.","Снижает затраты маны на ваши способности категории \"Выстрел\" и \"Укус\", а также способности ближнего боя на 15%."],["Careful Aim","Верная цель"],["Increases your Attack Power by 20% of your Intellect.","Повышает силу атаки на 20% интеллекта."],["Increases your Attack Power by 40% of your Intellect.","Повышает силу атаки на 40% интеллекта."],["Increases your Attack Power by 60% of your Intellect.","Повышает силу атаки на 60% интеллекта."],["Increases your Attack Power by 80% of your Intellect.","Повышает силу атаки на 80% интеллекта."],["Increases your Attack Power by 100% of your Intellect.","Повышает силу атаки на 100% интеллекта."],["Rapid Killing","Быстрые убийства"],["Reduces the cooldown on your Rapid Fire ability by 1 min. In addition, when you kill a non-trivial enemy or it dies while afflicted by your Serpent Sting, you gain Rapid Killing, increasing the damage of your next Shot ability within 20 sec by 10%.","Сокращает время восстановления \"Быстрой стрельбы\" на 1 мин. Кроме того, когда вы убиваете представляющего угрозу противника или такой противник погибает под действием вашего \"Укуса змеи\", вы получаете эффект \"Быстрые убийства\", увеличивающий урон от следующей способности категории \"Выстрел\" на 10%. Время действия – 20 сек."],["Reduces the cooldown on your Rapid Fire ability by 2 min. In addition, when you kill a non-trivial enemy or it dies while afflicted by your Serpent Sting, you gain Rapid Killing, increasing the damage of your next Shot ability within 20 sec by 20%.","Сокращает время восстановления \"Быстрой стрельбы\" на 2 мин. Кроме того, когда вы убиваете представляющего угрозу противника или такой противник погибает под действием вашего \"Укуса змеи\", вы получаете эффект \"Быстрые убийства\", увеличивающий урон от следующей способности категории \"Выстрел\" на 20%. Время действия – 20 сек."],["Improved Arcane Shot","Улучшенный чародейский выстрел"],["Reduces the cooldown of your Arcane Shot by 0.3 sec. Does not affect the cooldown of abilities which share a cooldown with Arcane Shot.","Сокращает время восстановления \"Чародейского выстрела\" на 0.3 сек. Не влияет на способности, имеющие общее время восстановления с \"Чародейским выстрелом\"."],["Reduces the cooldown of your Arcane Shot by 0.6 sec. Does not affect the cooldown of abilities which share a cooldown with Arcane Shot.","Сокращает время восстановления \"Чародейского выстрела\" на 0.6 сек. Не влияет на способности, имеющие общее время восстановления с \"Чародейским выстрелом\"."],["Reduces the cooldown of your Arcane Shot by 0.9 sec. Does not affect the cooldown of abilities which share a cooldown with Arcane Shot.","Сокращает время восстановления \"Чародейского выстрела\" на 0.9 сек. Не влияет на способности, имеющие общее время восстановления с \"Чародейским выстрелом\"."],["Reduces the cooldown of your Arcane Shot by 1.2 sec. Does not affect the cooldown of abilities which share a cooldown with Arcane Shot.","Сокращает время восстановления \"Чародейского выстрела\" на 1.2 сек. Не влияет на способности, имеющие общее время восстановления с \"Чародейским выстрелом\"."],["Reduces the cooldown of your Arcane Shot by 1.5 sec. Does not affect the cooldown of abilities which share a cooldown with Arcane Shot.","Сокращает время восстановления \"Чародейского выстрела\" на 1.5 сек. Не влияет на способности, имеющие общее время восстановления с \"Чародейским выстрелом\"."],["Lone Wolf","Одинокий волк"],["You deal 20% increased damage with all attacks while you do not have an active pet.","Ваши атаки наносят на 20% больше урона, пока у вас нет активного питомца."],["Trueshot Aura","Аура меткого выстрела"],["Increases the Ranged Attack Power of party members within 45 yards by 30. Lasts 30 min.","Повышает силу атаки дальнего боя участников группы в радиусе 45 м на 30. Время действия – 30 мин."],["Mortal Shots","Смертоносные выстрелы"],["Increases the critical strike damage bonus on all ranged abilities by 6%.","Увеличивает бонус критическому урону способностей дальнего боя на 6%."],["Increases the critical strike damage bonus on all ranged abilities by 12%.","Увеличивает бонус критическому урону способностей дальнего боя на 12%."],["Increases the critical strike damage bonus on all ranged abilities by 18%.","Увеличивает бонус критическому урону способностей дальнего боя на 18%."],["Increases the critical strike damage bonus on all ranged abilities by 24%.","Увеличивает бонус критическому урону способностей дальнего боя на 24%."],["Increases the critical strike damage bonus on all ranged abilities by 30%.","Увеличивает бонус критическому урону способностей дальнего боя на 30%."],["Improved Serpent Sting","Смертельный укус змеи"],["Increases the damage done by your Serpent Sting by 2%.","Увеличение на 2% урона, наносимого \"Укусом змеи\"."],["Increases the damage done by your Serpent Sting by 4%.","Увеличение на 4% урона, наносимого \"Укусом змеи\"."],["Increases the damage done by your Serpent Sting by 6%.","Увеличение на 6% урона, наносимого \"Укусом змеи\"."],["Increases the damage done by your Serpent Sting by 8%.","Увеличение на 8% урона, наносимого \"Укусом змеи\"."],["Increases the damage done by your Serpent Sting by 10%.","Увеличение на 10% урона, наносимого \"Укусом змеи\"."],["Rapid Recuperation","Быстрая концентрация"],["Hitting a target with your Serpent Sting ability grants you 25% and consuming Rapid Killing grants you 50% of your Mana regeneration while casting for the next 15 sec.","Поразив цель \"Укусом змеи\", вы восполняете ману во время применения способностей со скоростью 25%, а после поглощения эффекта \"Быстрые убийства\" – со скоростью 50%. Время действия – 15 сек."],["Hitting a target with your Serpent Sting ability grants you 50% and consuming Rapid Killing grants you 100% of your Mana regeneration while casting for the next 15 sec.","Поразив цель \"Укусом змеи\", вы восполняете ману во время применения способностей со скоростью 50%, а после поглощения эффекта \"Быстрые убийства\" – со скоростью 100%. Время действия – 15 сек."],["Barrage","Заградительный огонь"],["Increases the damage done by your Multi-Shot, Aimed Shot, and Volley abilities by 3%.","Увеличивает урон от \"Залпа\", \"Града стрел\" и \"Прицельного выстрела\" на 3%."],["Increases the damage done by your Multi-Shot, Aimed Shot, and Volley abilities by 7%.","Увеличивает урон от \"Залпа\", \"Града стрел\" и \"Прицельного выстрела\" на 7%."],["Increases the damage done by your Multi-Shot, Aimed Shot, and Volley abilities by 10%.","Увеличивает урон от \"Залпа\", \"Града стрел\" и \"Прицельного выстрела\" на 10%."],["Scatter Shot","Дезориентирующий выстрел"],["A short-range shot that deals 50% weapon damage and disorients the target for 4 sec. Any damage caused will remove the effect. Turns off your attack when used.","Выстрел на короткой дистанции с нанесением цели 50% урона от оружия и лишением ее ощущения направления на 4 сек. Любой нанесенный урон отменяет действие эффекта."],["Ranged Weapon Specialization","Специализация на оружии дальнего боя"],["Increases the damage you deal with ranged weapons by 1%.","Повешение урона, наносимого оружием дальнего боя, на 1%."],["Increases the damage you deal with ranged weapons by 2%.","Повешение урона, наносимого оружием дальнего боя, на 2%."],["Increases the damage you deal with ranged weapons by 3%.","Повешение урона, наносимого оружием дальнего боя, на 3%."],["Increases the damage you deal with ranged weapons by 4%.","Повешение урона, наносимого оружием дальнего боя, на 4%."],["Increases the damage you deal with ranged weapons by 5%.","Повешение урона, наносимого оружием дальнего боя, на 5%."],["Sniper Shot","Снайперский выстрел"],["A steady snipe that increases ranged damage by 160.","Снайперский выстрел, наносящий 160 ед. дополнительного урона в дальнем бою."],["Survival","Выживание"],["Improved Tracking","Мастерское выслеживание"],["While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by 1%.","Когда вы выслеживаете зверей, демонов, драконов, элементалей, великанов, гуманоидов или нежить, вы наносите на 1% выбранным существам."],["While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by 2%.","Когда вы выслеживаете зверей, демонов, драконов, элементалей, великанов, гуманоидов или нежить, вы наносите на 2% выбранным существам."],["While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by 3%.","Когда вы выслеживаете зверей, демонов, драконов, элементалей, великанов, гуманоидов или нежить, вы наносите на 3% выбранным существам."],["While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by 4%.","Когда вы выслеживаете зверей, демонов, драконов, элементалей, великанов, гуманоидов или нежить, вы наносите на 4% выбранным существам."],["While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by 5%.","Когда вы выслеживаете зверей, демонов, драконов, элементалей, великанов, гуманоидов или нежить, вы наносите на 5% выбранным существам."],["Deflection","Отражение"],["Increases your Parry chance by 2%.","Увеличивает вероятность парирования атак на 2%."],["Increases your Parry chance by 4%.","Увеличивает вероятность парирования атак на 4%."],["Increases your Parry chance by 6%.","Увеличивает вероятность парирования атак на 6%."],["Increases your Parry chance by 8%.","Увеличивает вероятность парирования атак на 8%."],["Increases your Parry chance by 10%.","Увеличивает вероятность парирования атак на 10%."],["Entrapment","Удержание"],["When your traps are triggered, all affected targets are Entrapped, preventing them from moving for 1 sec.","Ваши ловушки также применяют к пораженным целям эффект \"В ловушке\", обездвиживающий их на 1 сек."],["When your traps are triggered, all affected targets are Entrapped, preventing them from moving for 2 sec.","Ваши ловушки также применяют к пораженным целям эффект \"В ловушке\", обездвиживающий их на 2 сек."],["When your traps are triggered, all affected targets are Entrapped, preventing them from moving for 3 sec.","Ваши ловушки также применяют к пораженным целям эффект \"В ловушке\", обездвиживающий их на 3 сек."],["When your traps are triggered, all affected targets are Entrapped, preventing them from moving for 4 sec.","Ваши ловушки также применяют к пораженным целям эффект \"В ловушке\", обездвиживающий их на 4 сек."],["When your traps are triggered, all affected targets are Entrapped, preventing them from moving for 5 sec.","Ваши ловушки также применяют к пораженным целям эффект \"В ловушке\", обездвиживающий их на 5 сек."],["Savage Strikes","Беспощадные удары"],["Increases the critical strike chance of all your melee abilities by 2%.","Повышает вероятность критического удара способностей ближнего боя на 2%."],["Increases the critical strike chance of all your melee abilities by 4%.","Повышает вероятность критического удара способностей ближнего боя на 4%."],["Survivalist","Остаться в живых"],["Increases your total Health by 2%.","Увеличивает общий запас здоровья на 2%."],["Increases your total Health by 4%.","Увеличивает общий запас здоровья на 4%."],["Increases your total Health by 6%.","Увеличивает общий запас здоровья на 6%."],["Increases your total Health by 8%.","Увеличивает общий запас здоровья на 8%."],["Increases your total Health by 10%.","Увеличивает общий запас здоровья на 10%."],["Improved Wing Clip","Улучшенная подрезка крыльев"],["Gives your Wing Clip ability a 7% chance to immobilize the target for 5 sec.","Способность \"Подрезать крылья\" с вероятностью 7% обездвиживает цель на 5 сек."],["Gives your Wing Clip ability a 13% chance to immobilize the target for 5 sec.","Способность \"Подрезать крылья\" с вероятностью 13% обездвиживает цель на 5 сек."],["Gives your Wing Clip ability a 20% chance to immobilize the target for 5 sec.","Способность \"Подрезать крылья\" с вероятностью 20% обездвиживает цель на 5 сек."],["Clever Traps","Хитрые ловушки"],["Increases the duration of Freezing and Frost trap effects by 15% and the damage of Immolation and Explosive trap effects by 15%.","Увеличение длительности эффектов \"Ледяной ловушки\" и \"Замораживающей ловушки\" на 15%, а урона от \"Огненной ловушки\" и \"Взрывной ловушки\" – на 15%."],["Increases the duration of Freezing and Frost trap effects by 30% and the damage of Immolation and Explosive trap effects by 30%.","Увеличение длительности эффектов \"Ледяной ловушки\" и \"Замораживающей ловушки\" на 30%, а урона от \"Огненной ловушки\" и \"Взрывной ловушки\" – на 30%."],["Surefooted","Верный шаг"],["Increases your hit chance by 1% and reduces the duration of movement impairing effects on you by 10%.","Повышает вероятность попадания на 1% и сокращает время действия на вас затрудняющих передвижение эффектов на 10%."],["Increases your hit chance by 2% and reduces the duration of movement impairing effects on you by 20%.","Повышает вероятность попадания на 2% и сокращает время действия на вас затрудняющих передвижение эффектов на 20%."],["Increases your hit chance by 3% and reduces the duration of movement impairing effects on you by 30%.","Повышает вероятность попадания на 3% и сокращает время действия на вас затрудняющих передвижение эффектов на 30%."],["Deterrence","Сдерживание"],["When activated, increases your Dodge and Parry chance by 25% for 10 sec.","Повышение вероятности уклонения и парирования удара на 25% на 10 сек."],["Survival Tactics","Тактика выживания"],["Increases your chance to hit with your Trap and Feign Death abilities by 5%.","Повышает вероятность попадания для ловушек и способности \"Притвориться мертвым\" на 5%."],["Increases your chance to hit with your Trap and Feign Death abilities by 10%.","Повышает вероятность попадания для ловушек и способности \"Притвориться мертвым\" на 10%."],["Predator's Edge","Лезвие хищника"],["Increases your melee critical strike damage by 6% and your offhand weapon damage by 10%.","Критический урон от атак ближнего боя увеличивается на 6%. Урон от оружия в левой руке увеличивается на 10%."],["Increases your melee critical strike damage by 12% and your offhand weapon damage by 20%.","Критический урон от атак ближнего боя увеличивается на 12%. Урон от оружия в левой руке увеличивается на 20%."],["Increases your melee critical strike damage by 18% and your offhand weapon damage by 30%.","Критический урон от атак ближнего боя увеличивается на 18%. Урон от оружия в левой руке увеличивается на 30%."],["Increases your melee critical strike damage by 24% and your offhand weapon damage by 40%.","Критический урон от атак ближнего боя увеличивается на 24%. Урон от оружия в левой руке увеличивается на 40%."],["Increases your melee critical strike damage by 30% and your offhand weapon damage by 50%.","Критический урон от атак ближнего боя увеличивается на 30%. Урон от оружия в левой руке увеличивается на 50%."],["Counterattack","Контратака"],["A strike that becomes active after parrying an opponent's attack. This attack deals 50% weapon damage plus 26 and immobilizes the target for 5 sec. Counterattack cannot be blocked, dodged, or parried.","Удар, наносящий противнику 50% урона от оружия и еще 26 ед., а также обездвиживающий его на 5 сек. Можно применить только после парирования атаки. Этот удар невозможно заблокировать или парировать, и от него нельзя уклониться."],["Resourcefulness","Находчивость"],["Reduces the mana cost of your Trap abilities and melee abilities by 30%. In addition, your critical strikes have a 50% chance to allow 50% of your Mana regeneration to continue while casting for 30 sec.","Снижает затраты маны на применение ловушек и способностей ближнего боя на 30%. Кроме того, после того как вы наносите критический удар, вы с вероятностью 50% восполняете ману во время применения способностей со скоростью 50% в течение 30 сек."],["Reduces the mana cost of your Trap abilities and melee abilities by 60%. In addition, your critical strikes have a 100% chance to allow 50% of your Mana regeneration to continue while casting for 30 sec.","Снижает затраты маны на применение ловушек и способностей ближнего боя на 60%. Кроме того, после того как вы наносите критический удар, вы с вероятностью 100% восполняете ману во время применения способностей со скоростью 50% в течение 30 сек."],["Expose Prey","Обнаружение добычи"],["Your attacks against targets with Hunter's Mark have a 5% chance to activate your Mongoose Bite for 5 sec.","Атаки против цели, на которую действует ваша \"Метка охотника\", с вероятностью 5% активируют \"Укус мангуста\" на 5 сек."],["Your attacks against targets with Hunter's Mark have a 10% chance to activate your Mongoose Bite for 5 sec.","Атаки против цели, на которую действует ваша \"Метка охотника\", с вероятностью 10% активируют \"Укус мангуста\" на 5 сек."],["Survivalist's Discipline","Дисциплина выживающего"],["Reduces the cooldown of your Trap and Deterrence abilities by 20%.","Сокращает время восстановления ловушек и \"Сдерживания\" на 20%."],["Reduces the cooldown of your Trap and Deterrence abilities by 40%.","Сокращает время восстановления ловушек и \"Сдерживания\" на 40%."],["Strider Kick","Удар долгонога"],["A powerful kick that deals 100% melee weapon damage and increases movement speed by 30% for 3 sec.","A powerful kick that deals 100% melee weapon damage and increases movement speed by 30% for 3 сек."],["Lightning Reflexes","Молниеносные рефлексы"],["Increases your Agility by 2%.","Повышение ловкости на 2%."],["Increases your Agility by 4%.","Повышение ловкости на 4%."],["Increases your Agility by 6%.","Повышение ловкости на 6%."],["Increases your Agility by 8%.","Повышение ловкости на 8%."],["Increases your Agility by 10%.","Повышение ловкости на 10%."],["Lacerating Strikes","Раздирающие удары"],["Your Mongoose Bite also causes the target to Bleed for damage over 21 sec equal to 40% of the damage done by Mongoose Bite.","\"Укус мангуста\" также вызывает у цели кровотечение, за 21 сек. наносящее урон в объеме 40% урона от \"Укуса мангуста\"."]]},"rogue":{"build":"1.60.1.70009","className":"Rogue","pairs":[["Rogue","Разбойник"],["Assassination","Ликвидация"],["Improved Gouge","Улучшенный парализующий удар"],["Increases the duration of your Gouge ability by 0.5 sec.","Продлевает время действия \"Парализующего удара\" на 0.5 сек."],["Increases the duration of your Gouge ability by 1 sec.","Продлевает время действия \"Парализующего удара\" на 1 сек."],["Increases the duration of your Gouge ability by 1.5 sec.","Продлевает время действия \"Парализующего удара\" на 1.5 сек."],["Remorseless Attacks","Беспощадные атаки"],["After killing a non-trivial enemy, gives you a 20% increased critical strike chance on your next Sinister Strike, Backstab, Ambush, Mutilate, or Ghostly Strike. Lasts 20 sec.","После убийства, которое дает опыт или честь, вероятность критического удара следующей способности \"Коварный удар\", \"Удар в спину\", \"Внезапный удар\", \"Расправа\" или \"Призрачный удар\" повышается на 20%. Время действия – 20 сек"],["After killing a non-trivial enemy, gives you a 40% increased critical strike chance on your next Sinister Strike, Backstab, Ambush, Mutilate, or Ghostly Strike. Lasts 20 sec.","После убийства, которое дает опыт или честь, вероятность критического удара следующей способности \"Коварный удар\", \"Удар в спину\", \"Внезапный удар\", \"Расправа\" или \"Призрачный удар\" повышается на 40%. Время действия – 20 сек"],["Malice","Злоба"],["Increases your critical strike chance with all attacks and Poisons by 1%.","Повышает вероятность нанесения критического урона атаками и ядами на 1%."],["Increases your critical strike chance with all attacks and Poisons by 2%.","Повышает вероятность нанесения критического урона атаками и ядами на 2%."],["Increases your critical strike chance with all attacks and Poisons by 3%.","Повышает вероятность нанесения критического урона атаками и ядами на 3%."],["Increases your critical strike chance with all attacks and Poisons by 4%.","Повышает вероятность нанесения критического урона атаками и ядами на 4%."],["Increases your critical strike chance with all attacks and Poisons by 5%.","Повышает вероятность нанесения критического урона атаками и ядами на 5%."],["Ruthlessness","Жестокость"],["Gives your finishing moves a 20% chance to add a Combo Point to your target.","С вероятностью 20% ваш завершающий прием начнет новую серию приемов."],["Gives your finishing moves a 40% chance to add a Combo Point to your target.","С вероятностью 40% ваш завершающий прием начнет новую серию приемов."],["Gives your finishing moves a 60% chance to add a Combo Point to your target.","С вероятностью 60% ваш завершающий прием начнет новую серию приемов."],["Murder","Убийство"],["Increases all damage dealt by 2% against Humanoid and Giant targets.","Увеличивает урон, наносимый гуманоидам и великанам, на 2%."],["Increases all damage dealt by 4% against Humanoid and Giant targets.","Увеличивает урон, наносимый гуманоидам и великанам, на 4%."],["Improved Slice and Dice","Улучшенная мясорубка"],["Increases the duration of your Slice and Dice ability by 15%.","Увеличение длительности \"Мясорубки\" на 15%."],["Increases the duration of your Slice and Dice ability by 30%.","Увеличение длительности \"Мясорубки\" на 30%."],["Increases the duration of your Slice and Dice ability by 45%.","Увеличение длительности \"Мясорубки\" на 45%."],["Relentless Strikes","Неослабевающие удары"],["Your finishing moves have a 20% chance per Combo Point to restore 25 Energy.","С вероятностью 20% за каждый прием в серии ваш завершающий прием восстанавливает 25 ед. энергии."],["Improved Expose Armor","Улучшенное ослабление доспеха"],["Reduces the Energy cost of your Expose Armor ability by 5, and refunds 1 Combo Point when cast with 5 Combo Points.","Когда вы применяете \"Ослабление доспеха\" при 5 приемах в серии, затраты энергии снижаются на 5 ед. и вы восполняете 1 прием."],["Reduces the Energy cost of your Expose Armor ability by 10, and refunds 2 Combo Points when cast with 5 Combo Points.","Когда вы применяете \"Ослабление доспеха\" при 5 приемах в серии, затраты энергии снижаются на 10 ед. и вы восполняете 2 приема."],["Lethality","Смертоносность"],["Increases the critical strike damage bonus of your Sinister Strike, Gouge, Backstab, Mutilate, Ghostly Strike, and Hemorrhage abilities by 4%.","Увеличивает критический урон от \"Коварного удара\", \"Парализующего удара\", \"Удара в спину\", \"Расправы\", \"Призрачного удара\" и \"Кровоизлияния\" на 4%."],["Increases the critical strike damage bonus of your Sinister Strike, Gouge, Backstab, Mutilate, Ghostly Strike, and Hemorrhage abilities by 8%.","Увеличивает критический урон от \"Коварного удара\", \"Парализующего удара\", \"Удара в спину\", \"Расправы\", \"Призрачного удара\" и \"Кровоизлияния\" на 8%."],["Increases the critical strike damage bonus of your Sinister Strike, Gouge, Backstab, Mutilate, Ghostly Strike, and Hemorrhage abilities by 12%.","Увеличивает критический урон от \"Коварного удара\", \"Парализующего удара\", \"Удара в спину\", \"Расправы\", \"Призрачного удара\" и \"Кровоизлияния\" на 12%."],["Increases the critical strike damage bonus of your Sinister Strike, Gouge, Backstab, Mutilate, Ghostly Strike, and Hemorrhage abilities by 16%.","Увеличивает критический урон от \"Коварного удара\", \"Парализующего удара\", \"Удара в спину\", \"Расправы\", \"Призрачного удара\" и \"Кровоизлияния\" на 16%."],["Increases the critical strike damage bonus of your Sinister Strike, Gouge, Backstab, Mutilate, Ghostly Strike, and Hemorrhage abilities by 20%.","Увеличивает критический урон от \"Коварного удара\", \"Парализующего удара\", \"Удара в спину\", \"Расправы\", \"Призрачного удара\" и \"Кровоизлияния\" на 20%."],["Vile Poisons","Тлетворные яды"],["Increases the damage dealt by your poisons by 4% and gives your poisons an additional 8% chance to resist dispel effects.","Увеличивает урон, наносимый вашими ядами, на 4%. Заклинания и эффекты противников с вероятностью 8% не снимают ваши яды."],["Increases the damage dealt by your poisons by 8% and gives your poisons an additional 16% chance to resist dispel effects.","Увеличивает урон, наносимый вашими ядами, на 8%. Заклинания и эффекты противников с вероятностью 16% не снимают ваши яды."],["Increases the damage dealt by your poisons by 12% and gives your poisons an additional 24% chance to resist dispel effects.","Увеличивает урон, наносимый вашими ядами, на 12%. Заклинания и эффекты противников с вероятностью 24% не снимают ваши яды."],["Increases the damage dealt by your poisons by 16% and gives your poisons an additional 32% chance to resist dispel effects.","Увеличивает урон, наносимый вашими ядами, на 16%. Заклинания и эффекты противников с вероятностью 32% не снимают ваши яды."],["Increases the damage dealt by your poisons by 20% and gives your poisons an additional 40% chance to resist dispel effects.","Увеличивает урон, наносимый вашими ядами, на 20%. Заклинания и эффекты противников с вероятностью 40% не снимают ваши яды."],["Cold Blood","Хладнокровие"],["When activated, increases the critical strike chance of your next Sinister Strike, Backstab, Ambush, Eviscerate, or Mutilate by 100%.","При использовании повышает вероятность критического эффекта следующей способности \"Коварный удар\", \"Удар в спину\", \"Внезапный удар\", \"Потрошение\" или \"Расправа\" на 100%."],["Improved Poisons","Улучшенные яды"],["Increases the chance to apply Poisons to your target by 2%, and gives Poison applications a 10% chance to not consume a charge.","Повышает вероятность применить к цели яд на 2%. С вероятностью 10% вы не расходуете заряд яда при срабатывании."],["Increases the chance to apply Poisons to your target by 4%, and gives Poison applications a 20% chance to not consume a charge.","Повышает вероятность применить к цели яд на 4%. С вероятностью 20% вы не расходуете заряд яда при срабатывании."],["Increases the chance to apply Poisons to your target by 6%, and gives Poison applications a 30% chance to not consume a charge.","Повышает вероятность применить к цели яд на 6%. С вероятностью 30% вы не расходуете заряд яда при срабатывании."],["Increases the chance to apply Poisons to your target by 8%, and gives Poison applications a 40% chance to not consume a charge.","Повышает вероятность применить к цели яд на 8%. С вероятностью 40% вы не расходуете заряд яда при срабатывании."],["Increases the chance to apply Poisons to your target by 10%, and gives Poison applications a 50% chance to not consume a charge.","Повышает вероятность применить к цели яд на 10%. С вероятностью 50% вы не расходуете заряд яда при срабатывании."],["Vigor","Неутомимость"],["Increases your maximum Energy by 5.","Увеличивает максимальный запас энергии на 5 ед."],["Increases your maximum Energy by 10.","Увеличивает максимальный запас энергии на 10 ед."],["Mutilate","Расправа"],["Instantly attacks with both weapons for 75% weapon damage plus an additional 17.25 with each weapon. Damage increased by 20% against Poisoned targets. Awards 2 Combo Points.","Мгновенно атакует оружием в обеих руках, нанося 75% урона от оружия и еще 17.25 ед. урона каждым оружием. Урон увеличивается на 20%, если цель отравлена. Продлевает серию приемов на 2."],["Improved Kidney Shot","Улучшенный удар по почкам"],["Enemies Stunned by your Kidney Shot ability take 5% increased damage from your poisons and attacks.","Оглушенные \"Ударом по почкам\" противники получают на 5% больше урона от ваших ядов и атак."],["Enemies Stunned by your Kidney Shot ability take 10% increased damage from your poisons and attacks.","Оглушенные \"Ударом по почкам\" противники получают на 10% больше урона от ваших ядов и атак."],["Seal Fate","Печать судьбы"],["Your critical strikes from abilities that add Combo Points have a 20% chance to add an additional Combo Point.","С вероятностью 20% критические эффекты способностей, которые продлевают серию приемов, дают еще один прием."],["Your critical strikes from abilities that add Combo Points have a 40% chance to add an additional Combo Point.","С вероятностью 40% критические эффекты способностей, которые продлевают серию приемов, дают еще один прием."],["Your critical strikes from abilities that add Combo Points have a 60% chance to add an additional Combo Point.","С вероятностью 60% критические эффекты способностей, которые продлевают серию приемов, дают еще один прием."],["Your critical strikes from abilities that add Combo Points have a 80% chance to add an additional Combo Point.","С вероятностью 80% критические эффекты способностей, которые продлевают серию приемов, дают еще один прием."],["Your critical strikes from abilities that add Combo Points have a 100% chance to add an additional Combo Point.","С вероятностью 100% критические эффекты способностей, которые продлевают серию приемов, дают еще один прием."],["Venom","Яд"],["Finishing move that increases the damage of your Poisons by 30% and your chance to apply Poisons by 10%. Lasts longer per combo point: 1 point : 9 seconds 2 points: 12 seconds 3 points: 15 seconds 4 points: 18 seconds 5 points: 21 seconds","Завершающий прием, увеличивающий урон от ядов на 30%, а вероятность отравить цель – на 10%. Время действия зависит от длины серии: 1 прием : 9 сек. 2 приема: 12 сек. 3 приема: 15 сек. 4 приема: 18 сек. 5 приемов: 21 сек."],["Combat","Бой"],["Improved Eviscerate","Улучшенное потрошение"],["Increases the damage done by your Eviscerate ability by 7%.","\"Потрошение\" наносит на 7% больше урона."],["Increases the damage done by your Eviscerate ability by 13%.","\"Потрошение\" наносит на 13% больше урона."],["Increases the damage done by your Eviscerate ability by 20%.","\"Потрошение\" наносит на 20% больше урона."],["Improved Sinister Strike","Улучшенный коварный удар"],["Reduces the Energy cost of your Sinister Strike ability by 3.","Снижение на 3 ед. расхода энергии на совершение \"Коварного удара\"."],["Reduces the Energy cost of your Sinister Strike ability by 5.","Снижение на 5 ед. расхода энергии на совершение \"Коварного удара\"."],["Lightning Reflexes","Молниеносные рефлексы"],["Increases your Dodge chance by 1%.","Повышает вероятность уклонения на 1%."],["Increases your Dodge chance by 2%.","Повышает вероятность уклонения на 2%."],["Increases your Dodge chance by 3%.","Повышает вероятность уклонения на 3%."],["Increases your Dodge chance by 4%.","Повышает вероятность уклонения на 4%."],["Increases your Dodge chance by 5%.","Повышает вероятность уклонения на 5%."],["Puncturing Wounds","Колотые раны"],["Increases the critical strike chance of your Backstab by 10% and your Mutilate by 5%, and gives Backstab a 15% chance to add an additional Combo Point.","Повышает вероятность критического эффекта \"Удара в спину\" на 10%, а \"Расправы\" – на 5%. \"Удар в спину\" с вероятностью 15% продлевает серию приемов еще на 1."],["Increases the critical strike chance of your Backstab by 20% and your Mutilate by 10%, and gives Backstab a 30% chance to add an additional Combo Point.","Повышает вероятность критического эффекта \"Удара в спину\" на 20%, а \"Расправы\" – на 10%. \"Удар в спину\" с вероятностью 30% продлевает серию приемов еще на 1."],["Increases the critical strike chance of your Backstab by 30% and your Mutilate by 15%, and gives Backstab a 45% chance to add an additional Combo Point.","Повышает вероятность критического эффекта \"Удара в спину\" на 30%, а \"Расправы\" – на 15%. \"Удар в спину\" с вероятностью 45% продлевает серию приемов еще на 1."],["Deflection","Отражение"],["Increases your Parry chance by 2%.","Увеличивает вероятность парирования атак на 2%."],["Increases your Parry chance by 4%.","Увеличивает вероятность парирования атак на 4%."],["Increases your Parry chance by 6%.","Увеличивает вероятность парирования атак на 6%."],["Precision","Точность"],["Improves your chance to hit by 1%.","Повышает вероятность попадания на 1%."],["Improves your chance to hit by 2%.","Повышает вероятность попадания на 2%."],["Improves your chance to hit by 3%.","Повышает вероятность попадания на 3%."],["Endurance","Закалка"],["Reduces the cooldown of your Sprint and Evasion abilities by 30%.","Сокращает время восстановления \"Спринта\" и \"Ускользания\" на 30%."],["Reduces the cooldown of your Sprint and Evasion abilities by 60%.","Сокращает время восстановления \"Спринта\" и \"Ускользания\" на 60%."],["Riposte","Ответный удар"],["A strike that becomes active after parrying an opponent's attack. This attack deals 150% weapon damage and disarms the target for 6 sec.","Удар, который можно нанести только после успешного парирования атаки противника. Эта атака наносит 150% урона от оружия и обезоруживает цель на 6 сек."],["Improved Sprint","Улучшенный спринт"],["Gives a 50% chance to remove all movement impairing effects when you activate your Sprint ability.","При использовании \"Спринта\" с вероятностью 50% с вас снимаются все затрудняющие передвижение эффекты."],["Gives a 100% chance to remove all movement impairing effects when you activate your Sprint ability.","При использовании \"Спринта\" с вероятностью 100% с вас снимаются все затрудняющие передвижение эффекты."],["Improved Kick","Улучшенный пинок"],["Gives your Kick ability a 50% chance to Silence the target for 2 sec.","\"Пинок\" с вероятностью 50% поражает цель немотой на 2 сек."],["Gives your Kick ability a 100% chance to Silence the target for 2 sec.","\"Пинок\" с вероятностью 100% поражает цель немотой на 2 сек."],["Flawless Execution","Безупречная расправа"],["Reduces the Energy cost of your Eviscerate ability by 10.","Снижает расход энергии на способность \"Потрошение\" на 10 ед."],["Dual Wield Specialization","Специализация на бое двумя оружиями"],["Increases the damage done by your off-hand weapon by 5%.","Увеличивает урон от оружия в левой руке на 5%."],["Increases the damage done by your off-hand weapon by 10%.","Увеличивает урон от оружия в левой руке на 10%."],["Increases the damage done by your off-hand weapon by 15%.","Увеличивает урон от оружия в левой руке на 15%."],["Increases the damage done by your off-hand weapon by 20%.","Увеличивает урон от оружия в левой руке на 20%."],["Increases the damage done by your off-hand weapon by 25%.","Увеличивает урон от оружия в левой руке на 25%."],["Blade Flurry","Шквал клинков"],["Increases your melee attack speed by 20% and your melee attacks strike an additional nearby opponent. Lasts 15 sec.","Повышает скорость атаки в ближнем бою на 20%. Ваши атаки ближнего боя также поражают еще одного ближайшего противника. Время действия – 15 сек."],["Hack and Slash","Руби, кромсай!"],["Gives your melee weapon attacks a benefit depending on the weapon. |CFFFFFFFFAxe/Sword: Your successful melee attacks have a 1% chance to trigger an extra attack on the target. |CFFFFFFFFDagger/Fist: Increases your critical strike chance by 1%. |CFFFFFFFFMace: Your attacks ignore 3% of your target's armor.","Усиливает атаки ближнего боя в зависимости от типа оружия. |CFFFFFFFFТопор/меч: атаки ближнего боя с вероятностью 1% срабатывают повторно. |CFFFFFFFFКинжал/кулачное: повышает вероятность критического удара на 1%. |CFFFFFFFFДробящее: атаки игнорируют 3% брони цели."],["Gives your melee weapon attacks a benefit depending on the weapon. |CFFFFFFFFAxe/Sword: Your successful melee attacks have a 2% chance to trigger an extra attack on the target. |CFFFFFFFFDagger/Fist: Increases your critical strike chance by 2%. |CFFFFFFFFMace: Your attacks ignore 6% of your target's armor.","Усиливает атаки ближнего боя в зависимости от типа оружия. |CFFFFFFFFТопор/меч: атаки ближнего боя с вероятностью 2% срабатывают повторно. |CFFFFFFFFКинжал/кулачное: повышает вероятность критического удара на 2%. |CFFFFFFFFДробящее: атаки игнорируют 6% брони цели."],["Gives your melee weapon attacks a benefit depending on the weapon. |CFFFFFFFFAxe/Sword: Your successful melee attacks have a 3% chance to trigger an extra attack on the target. |CFFFFFFFFDagger/Fist: Increases your critical strike chance by 3%. |CFFFFFFFFMace: Your attacks ignore 9% of your target's armor.","Усиливает атаки ближнего боя в зависимости от типа оружия. |CFFFFFFFFТопор/меч: атаки ближнего боя с вероятностью 3% срабатывают повторно. |CFFFFFFFFКинжал/кулачное: повышает вероятность критического удара на 3%. |CFFFFFFFFДробящее: атаки игнорируют 9% брони цели."],["Gives your melee weapon attacks a benefit depending on the weapon. |CFFFFFFFFAxe/Sword: Your successful melee attacks have a 4% chance to trigger an extra attack on the target. |CFFFFFFFFDagger/Fist: Increases your critical strike chance by 4%. |CFFFFFFFFMace: Your attacks ignore 12% of your target's armor.","Усиливает атаки ближнего боя в зависимости от типа оружия. |CFFFFFFFFТопор/меч: атаки ближнего боя с вероятностью 4% срабатывают повторно. |CFFFFFFFFКинжал/кулачное: повышает вероятность критического удара на 4%. |CFFFFFFFFДробящее: атаки игнорируют 12% брони цели."],["Gives your melee weapon attacks a benefit depending on the weapon. |CFFFFFFFFAxe/Sword: Your successful melee attacks have a 5% chance to trigger an extra attack on the target. |CFFFFFFFFDagger/Fist: Increases your critical strike chance by 5%. |CFFFFFFFFMace: Your attacks ignore 15% of your target's armor.","Усиливает атаки ближнего боя в зависимости от типа оружия. |CFFFFFFFFТопор/меч: атаки ближнего боя с вероятностью 5% срабатывают повторно. |CFFFFFFFFКинжал/кулачное: повышает вероятность критического удара на 5%. |CFFFFFFFFДробящее: атаки игнорируют 15% брони цели."],["Weapon Expertise","Оружейное мастерство"],["Reduces the chance for your attacks to be Dodged or Parried by 1%.","Снижает вероятность того, что цель парирует ваши атаки или уклонится от них, на 1%."],["Reduces the chance for your attacks to be Dodged or Parried by 2%.","Снижает вероятность того, что цель парирует ваши атаки или уклонится от них, на 2%."],["Aggression","Агрессивность"],["Increases the damage of your Sinister Strike, Backstab, and Eviscerate abilities by 2%.","Увеличивает урон от \"Коварного удара\", \"Удара в спину\" и \"Потрошения\" на 2%."],["Increases the damage of your Sinister Strike, Backstab, and Eviscerate abilities by 4%.","Увеличивает урон от \"Коварного удара\", \"Удара в спину\" и \"Потрошения\" на 4%."],["Increases the damage of your Sinister Strike, Backstab, and Eviscerate abilities by 6%.","Увеличивает урон от \"Коварного удара\", \"Удара в спину\" и \"Потрошения\" на 6%."],["Adrenaline Rush","Выброс адреналина"],["Increases your Energy regeneration rate by 100% for 15 sec.","Увеличивает скорость восполнения энергии на 100% в течение 15 сек."],["Subtlety","Скрытность"],["Camouflage","Камуфляж"],["Reduces your speed penalty from your Stealth ability by 3% and reduces its cooldown by 2 sec.","Уменьшает штраф к скорости передвижения в состоянии незаметности на 3% и сокращает время восстановления \"Незаметности\" на 2 сек."],["Reduces your speed penalty from your Stealth ability by 6% and reduces its cooldown by 3 sec.","Уменьшает штраф к скорости передвижения в состоянии незаметности на 6% и сокращает время восстановления \"Незаметности\" на 3 сек."],["Reduces your speed penalty from your Stealth ability by 9% and reduces its cooldown by 4 sec.","Уменьшает штраф к скорости передвижения в состоянии незаметности на 9% и сокращает время восстановления \"Незаметности\" на 4 сек."],["Reduces your speed penalty from your Stealth ability by 12% and reduces its cooldown by 5 sec.","Уменьшает штраф к скорости передвижения в состоянии незаметности на 12% и сокращает время восстановления \"Незаметности\" на 5 сек."],["Reduces your speed penalty from your Stealth ability by 15% and reduces its cooldown by 6 sec.","Уменьшает штраф к скорости передвижения в состоянии незаметности на 15% и сокращает время восстановления \"Незаметности\" на 6 сек."],["Master of Deception","Мастер маскировки"],["Reduces the chance enemies have to detect you while in Stealth mode as if you were 1 level higher.","Снижает вероятность того, что противники обнаружат вас в состоянии незаметности, как если бы ваш уровень был на 1 выше."],["Reduces the chance enemies have to detect you while in Stealth mode as if you were 2 levels higher.","Снижает вероятность того, что противники обнаружат вас в состоянии незаметности, как если бы ваш уровень был на 2 выше."],["Reduces the chance enemies have to detect you while in Stealth mode as if you were 3 levels higher.","Снижает вероятность того, что противники обнаружат вас в состоянии незаметности, как если бы ваш уровень был на 3 выше."],["Opportunity","Правильный момент"],["Increases the damage dealt by your Backstab, Garrote, Ambush, and Mutilate abilities by 5%.","Увеличивает урон от \"Удара в спину\", \"Гарроты\", \"Внезапного удара\" и \"Расправы\", на 5%."],["Increases the damage dealt by your Backstab, Garrote, Ambush, and Mutilate abilities by 10%.","Увеличивает урон от \"Удара в спину\", \"Гарроты\", \"Внезапного удара\" и \"Расправы\", на 10%."],["Setup","Выучка"],["Gives you a 33% chance to add a Combo Point to your target after Dodging an attack or fully resisting a spell.","Когда вы уклоняетесь от атаки или полностью сопротивляетесь заклинанию, с вероятностью 33% длина серии приемов против цели увеличивается на 1."],["Gives you a 67% chance to add a Combo Point to your target after Dodging an attack or fully resisting a spell.","Когда вы уклоняетесь от атаки или полностью сопротивляетесь заклинанию, с вероятностью 67% длина серии приемов против цели увеличивается на 1."],["Gives you a 100% chance to add a Combo Point to your target after Dodging an attack or fully resisting a spell.","Когда вы уклоняетесь от атаки или полностью сопротивляетесь заклинанию, с вероятностью 100% длина серии приемов против цели увеличивается на 1."],["Elusiveness","Неуловимость"],["Reduces the cooldown of your Vanish and Blind abilities by 45 sec.","Уменьшает время восстановления способностей \"Исчезновение\" и \"Ослепление\" на 45 сек."],["Reduces the cooldown of your Vanish and Blind abilities by 90 sec.","Уменьшает время восстановления способностей \"Исчезновение\" и \"Ослепление\" на 90 сек."],["Dirty Tricks","Грязные приемы"],["Reduces the Energy cost of your Sap and Blind abilities by 25%.","Снижает затраты энергии на \"Ошеломление\" и \"Ослепление\" на 25%."],["Reduces the Energy cost of your Sap and Blind abilities by 50%.","Снижает затраты энергии на \"Ошеломление\" и \"Ослепление\" на 50%."],["Improved Ambush","Улучшенный внезапный удар"],["Increases the critical strike chance of your Ambush ability by 15%.","Повышает вероятность критического эффекта \"Внезапного удара\" на 15%."],["Increases the critical strike chance of your Ambush ability by 30%.","Повышает вероятность критического эффекта \"Внезапного удара\" на 30%."],["Increases the critical strike chance of your Ambush ability by 45%.","Повышает вероятность критического эффекта \"Внезапного удара\" на 45%."],["Initiative","Инициатива"],["Gives you a 33% chance to add an additional combo point to your target when using your Ambush, Garrote, or Cheap Shot ability.","С вероятностью 33% в результате проведения приемов \"Внезапный удар\", \"Гаррота\" и \"Подлый трюк\" длина серии приемов, проводимой против цели, увеличится дополнительно на 1 прием."],["Gives you a 67% chance to add an additional combo point to your target when using your Ambush, Garrote, or Cheap Shot ability.","С вероятностью 67% в результате проведения приемов \"Внезапный удар\", \"Гаррота\" и \"Подлый трюк\" длина серии приемов, проводимой против цели, увеличится дополнительно на 1 прием."],["Gives you a 100% chance to add an additional combo point to your target when using your Ambush, Garrote, or Cheap Shot ability.","С вероятностью 100% в результате проведения приемов \"Внезапный удар\", \"Гаррота\" и \"Подлый трюк\" длина серии приемов, проводимой против цели, увеличится дополнительно на 1 прием."],["Ghostly Strike","Призрачный удар"],["A strike that deals 125% (180% if a Dagger is equipped in your Main Hand) weapon damage and increases your chance to dodge by 15% for 7 sec. Awards 1 combo point.","Удар, наносящий 125% урона от оружия (180%, если в правой руке вы держите кинжал), и увеличивающий вероятность уклонения от атак на 15% на 7 сек. Длина серии приемов увеличивается на 1."],["Improved Distract","Улучшенное отвлечение"],["Increases the radius of your Distract ability by 3 yds, and further reduces the Stealth detection of distracted enemies as though they were an additional 1 level lower.","Увеличивает радиус действия способности \"Отвлечение\" на 3 м и дополнительно уменьшает вероятность отвлеченных противников обнаружить вас, снижая эффективный уровень еще на 1."],["Increases the radius of your Distract ability by 5 yds, and further reduces the Stealth detection of distracted enemies as though they were an additional 2 levels lower.","Увеличивает радиус действия способности \"Отвлечение\" на 5 м и дополнительно уменьшает вероятность отвлеченных противников обнаружить вас, снижая эффективный уровень еще на 2."],["Heightened Senses","Обостренные чувства"],["Increases your Stealth detection as if you were 1 level higher and reduces your chance to be hit by spells and ranged attacks by 2%.","Улучшает способность обнаружения замаскированных целей, словно ваш уровень выше на 1. Уменьшает вероятность того, что противники попадут в вас заклинаниями и атаками дальнего боя, на 2%."],["Increases your Stealth detection as if you were 3 levels higher and reduces your chance to be hit by spells and ranged attacks by 4%.","Улучшает способность обнаружения замаскированных целей, словно ваш уровень выше на 3. Уменьшает вероятность того, что противники попадут в вас заклинаниями и атаками дальнего боя, на 4%."],["Premeditation","Умысел"],["Adds 2 Combo Points to your target. You must add to or use those combo points within 20 sec or the combo points are lost.","Подготовительный прием, продлевающий серию на 2. Необходимо продолжить или завершить серию в течение 20 сек., или эффект пропадет."],["Serrated Blades","Зазубренные клинки"],["Causes your attacks to ignore 3% of your target's Armor and increases the damage dealt by your Rupture ability by 10%.","Позволяет вашим атакам игнорировать 3% брони цели. Увеличивает урон от способности \"Рваная рана\" на 10%."],["Causes your attacks to ignore 6% of your target's Armor and increases the damage dealt by your Rupture ability by 20%.","Позволяет вашим атакам игнорировать 6% брони цели. Увеличивает урон от способности \"Рваная рана\" на 20%."],["Causes your attacks to ignore 9% of your target's Armor and increases the damage dealt by your Rupture ability by 30%.","Позволяет вашим атакам игнорировать 9% брони цели. Увеличивает урон от способности \"Рваная рана\" на 30%."],["Dirty Deeds","Грязные делишки"],["Reduces the Energy cost of your Cheap Shot and Garrote abilities by 10, and your Garrote ability no longer requires you to be behind your target.","Уменьшает расход энергии на способности \"Подлый трюк\" и \"Гаррота\" на 10 ед. Для применения \"Гарроты\" больше не обязательно находиться за спиной у цели."],["Reduces the Energy cost of your Cheap Shot and Garrote abilities by 20, and your Garrote ability no longer requires you to be behind your target.","Уменьшает расход энергии на способности \"Подлый трюк\" и \"Гаррота\" на 20 ед. Для применения \"Гарроты\" больше не обязательно находиться за спиной у цели."],["Preparation","Подготовка"],["When activated, this ability immediately finishes the cooldown on your other Rogue abilities.","При активации этой способности немедленно обнуляется время до восстановления остальных способностей разбойника."],["Hemorrhage","Кровоизлияние"],["An instant strike that deals 100% weapon damage (145% if a Dagger is equipped) and causes the target to take 15% increased Rupture damage from the Rogue. Lasts 15 sec. Awards 1 Combo Point.","Резкий удар, наносящий 100% урона от оружия (145%, если вы вооружены кинжалом). Увеличивает урон, который ваша \"Рваная рана\" наносит цели, на 15%. Время действия – 15 сек. Длина серии приемов увеличивается на 1."],["Quietus","Упокоение"],["Your Sinister Strike, Ghostly Strike, and Hemorrhage abilities cause 2% more damage against targets below 35% health.","\"Коварный удар\", \"Призрачный удар\" и \"Кровоизлияние\" наносят на 2% больше урона целям, уровень здоровья которых ниже 35%."],["Your Sinister Strike, Ghostly Strike, and Hemorrhage abilities cause 4% more damage against targets below 35% health.","\"Коварный удар\", \"Призрачный удар\" и \"Кровоизлияние\" наносят на 4% больше урона целям, уровень здоровья которых ниже 35%."],["Your Sinister Strike, Ghostly Strike, and Hemorrhage abilities cause 6% more damage against targets below 35% health.","\"Коварный удар\", \"Призрачный удар\" и \"Кровоизлияние\" наносят на 6% больше урона целям, уровень здоровья которых ниже 35%."],["Your Sinister Strike, Ghostly Strike, and Hemorrhage abilities cause 8% more damage against targets below 35% health.","\"Коварный удар\", \"Призрачный удар\" и \"Кровоизлияние\" наносят на 8% больше урона целям, уровень здоровья которых ниже 35%."],["Your Sinister Strike, Ghostly Strike, and Hemorrhage abilities cause 10% more damage against targets below 35% health.","\"Коварный удар\", \"Призрачный удар\" и \"Кровоизлияние\" наносят на 10% больше урона целям, уровень здоровья которых ниже 35%."],["Cutthroat","Горлорез"],["Your Backstab has a 3% chance to cause your next Ambush within 10 sec to not require Stealth.","\"Удар в спину\" с вероятностью 3% позволяет применить следующий \"Внезапный удар\", не находясь в состоянии незаметности. Время действия – 10 сек."],["Your Backstab has a 6% chance to cause your next Ambush within 10 sec to not require Stealth.","\"Удар в спину\" с вероятностью 6% позволяет применить следующий \"Внезапный удар\", не находясь в состоянии незаметности. Время действия – 10 сек."],["Your Backstab has a 9% chance to cause your next Ambush within 10 sec to not require Stealth.","\"Удар в спину\" с вероятностью 9% позволяет применить следующий \"Внезапный удар\", не находясь в состоянии незаметности. Время действия – 10 сек."],["Your Backstab has a 12% chance to cause your next Ambush within 10 sec to not require Stealth.","\"Удар в спину\" с вероятностью 12% позволяет применить следующий \"Внезапный удар\", не находясь в состоянии незаметности. Время действия – 10 сек."],["Your Backstab has a 15% chance to cause your next Ambush within 10 sec to not require Stealth.","\"Удар в спину\" с вероятностью 15% позволяет применить следующий \"Внезапный удар\", не находясь в состоянии незаметности. Время действия – 10 сек."],["Thousand Cuts","Тысяча порезов"],["When your Rupture ability deals periodic damage, the Energy cost of your next Hemorrhage or Backstab ability within 10 sec is reduced by 3, stacking up to 5 times.","Когда ваша \"Рваная рана\" наносит периодический урон, затраты энергии на следующее применение \"Кровоизлияния\" или \"Удара в спину\" снижаются на 3 ед. на 10 сек. Эффект суммируется до 5 раз."]]},"priest":{"build":"1.60.1.70009","className":"Priest","pairs":[["Priest","Жрец"],["Discipline","Послушание"],["Power in Light","Усиливающий Свет"],["Your Smite and Penance spells deal 2% increased damage to targets afflicted with your Holy Fire.","\"Кара\" и \"Исповедь\" наносят на 2% больше урона целям, на которые действует ваш \"Священный огонь\"."],["Your Smite and Penance spells deal 4% increased damage to targets afflicted with your Holy Fire.","\"Кара\" и \"Исповедь\" наносят на 4% больше урона целям, на которые действует ваш \"Священный огонь\"."],["Your Smite and Penance spells deal 6% increased damage to targets afflicted with your Holy Fire.","\"Кара\" и \"Исповедь\" наносят на 6% больше урона целям, на которые действует ваш \"Священный огонь\"."],["Your Smite and Penance spells deal 8% increased damage to targets afflicted with your Holy Fire.","\"Кара\" и \"Исповедь\" наносят на 8% больше урона целям, на которые действует ваш \"Священный огонь\"."],["Your Smite and Penance spells deal 10% increased damage to targets afflicted with your Holy Fire.","\"Кара\" и \"Исповедь\" наносят на 10% больше урона целям, на которые действует ваш \"Священный огонь\"."],["Wand Specialization","Специализация на жезлах"],["Increases your damage with Wands by 13%.","Увеличение на 13% урона, наносимого при использовании магических жезлов."],["Increases your damage with Wands by 25%.","Увеличение на 25% урона, наносимого при использовании магических жезлов."],["Twin Disciplines","Две дисциплины"],["Increases the damage and healing of your instant cast spells by 1%.","Увеличивает урон и силу исцеления ваших мгновенных заклинаний на 1%."],["Increases the damage and healing of your instant cast spells by 2%.","Увеличивает урон и силу исцеления ваших мгновенных заклинаний на 2%."],["Increases the damage and healing of your instant cast spells by 3%.","Увеличивает урон и силу исцеления ваших мгновенных заклинаний на 3%."],["Increases the damage and healing of your instant cast spells by 4%.","Увеличивает урон и силу исцеления ваших мгновенных заклинаний на 4%."],["Increases the damage and healing of your instant cast spells by 5%.","Увеличивает урон и силу исцеления ваших мгновенных заклинаний на 5%."],["Silent Resolve","Молчаливая решимость"],["Reduces the threat generated by your Holy spells by 10% and reduces the duration of Stun, Fear, and Silence effects inflicted on you by 5%.","Снижает уровень угрозы, создаваемой заклинаниями Света, на 10% и сокращает время действия применяемых к вам эффектов оглушения, страха и немоты на 5%."],["Reduces the threat generated by your Holy spells by 20% and reduces the duration of Stun, Fear, and Silence effects inflicted on you by 10%.","Снижает уровень угрозы, создаваемой заклинаниями Света, на 20% и сокращает время действия применяемых к вам эффектов оглушения, страха и немоты на 10%."],["Reduces the threat generated by your Holy spells by 30% and reduces the duration of Stun, Fear, and Silence effects inflicted on you by 15%.","Снижает уровень угрозы, создаваемой заклинаниями Света, на 30% и сокращает время действия применяемых к вам эффектов оглушения, страха и немоты на 15%."],["Holy Precision","Священная точность"],["Improves your chance to hit with Holy spells by 6%.","Повышает вероятность попадания заклинаниями светлой магии на 6%."],["Improves your chance to hit with Holy spells by 12%.","Повышает вероятность попадания заклинаниями светлой магии на 12%."],["Improves your chance to hit with Holy spells by 18%.","Повышает вероятность попадания заклинаниями светлой магии на 18%."],["Improved Power Word: Shield","Улучшенное Слово силы: Щит"],["Increases the damage absorbed by your Power Word: Shield by 7%.","Увеличение на 7% количества урона, поглощаемого при применении заклинания \"Слово силы: щит\"."],["Increases the damage absorbed by your Power Word: Shield by 14%.","Увеличение на 14% количества урона, поглощаемого при применении заклинания \"Слово силы: щит\"."],["Increases the damage absorbed by your Power Word: Shield by 20%.","Увеличение на 20% количества урона, поглощаемого при применении заклинания \"Слово силы: щит\"."],["Martyrdom","Мученичество"],["Gives you a 50% chance to gain Focused Casting for 6 sec after being the victim of a melee or ranged critical strike. The Focused Casting effect prevents you from losing casting time when taking damage and increases your resistance to Interrupt effects by 20%.","\"С вероятностью 50% при получении критического удара в ближнем или дальнем бою вы получаете эффект \"Средоточие заклинаний\" на 6 сек. Этот эффект предотвращает задержку применения заклинаний при получении урона и повышает сопротивление эффектам прерывания на 20%.\""],["Gives you a 100% chance to gain Focused Casting for 6 sec after being the victim of a melee or ranged critical strike. The Focused Casting effect prevents you from losing casting time when taking damage and increases your resistance to Interrupt effects by 20%.","\"С вероятностью 100% при получении критического удара в ближнем или дальнем бою вы получаете эффект \"Средоточие заклинаний\" на 6 сек. Этот эффект предотвращает задержку применения заклинаний при получении урона и повышает сопротивление эффектам прерывания на 20%.\""],["Mental Agility","Подвижность мысли"],["Reduces the mana cost of your Smite, Holy Fire, and instant cast spells by 3%.","Снижает затраты маны на применение \"Кары\", \"Священного огня\" и мгновенно применяемых заклинаний на 3%."],["Reduces the mana cost of your Smite, Holy Fire, and instant cast spells by 7%.","Снижает затраты маны на применение \"Кары\", \"Священного огня\" и мгновенно применяемых заклинаний на 7%."],["Reduces the mana cost of your Smite, Holy Fire, and instant cast spells by 10%.","Снижает затраты маны на применение \"Кары\", \"Священного огня\" и мгновенно применяемых заклинаний на 10%."],["Inner Focus","Внутреннее сосредоточение"],["When activated, reduces the Mana cost of your next spell by 100% and increases its critical effect chance by 25% if it is capable of a critical effect.","Понижение расхода маны на последующее заклинание на 100%, а также повышение вероятности критического эффекта на 25%, если такой эффект возможен."],["Meditation","Медитация"],["Allows 17% of your Mana regeneration to continue while casting.","В процессе применения заклинаний продолжается 17% от восполнения маны."],["Allows 33% of your Mana regeneration to continue while casting.","В процессе применения заклинаний продолжается 33% от восполнения маны."],["Allows 50% of your Mana regeneration to continue while casting.","В процессе применения заклинаний продолжается 50% от восполнения маны."],["Improved Inner Fire","Улучшенный внутренний огонь"],["Increases the Armor bonus of your Inner Fire spell by 15% and increases its total charges by 4.","\"Внутренний огонь\" укрепляет броню еще на 15% и получает 4 дополнительных заряда."],["Increases the Armor bonus of your Inner Fire spell by 30% and increases its total charges by 8.","\"Внутренний огонь\" укрепляет броню еще на 30% и получает 8 дополнительных зарядов."],["Increases the Armor bonus of your Inner Fire spell by 45% and increases its total charges by 12.","\"Внутренний огонь\" укрепляет броню еще на 45% и получает 12 дополнительных зарядов."],["Mental Strength","Сила мысли"],["Increases your total Intellect by 3%.","Повышает интеллект на 3%."],["Increases your total Intellect by 6%.","Повышает интеллект на 6%."],["Increases your total Intellect by 9%.","Повышает интеллект на 9%."],["Increases your total Intellect by 12%.","Повышает интеллект на 12%."],["Increases your total Intellect by 15%.","Повышает интеллект на 15%."],["Soul Warding","Оберег души"],["Reduces the cooldown on your Power Word: Shield spell by 4 sec and reduces its mana cost by 15%.","Сокращает время восстановления \"Слова силы: Щит\" на 4 сек. и снижает затраты маны на его применение на 15%."],["Improved Mana Burn","Улучшенное сожжение маны"],["Reduces the casting time of your Mana Burn spell by 0.5 sec.","Сокращает время применения \"Сожжения маны\" на 0.5 сек."],["Reduces the casting time of your Mana Burn spell by 1.0 sec.","Сокращает время применения \"Сожжения маны\" на 1.0 сек."],["Penance","Исповедь"],["Launches a volley of holy light at the target, causing 81 Holy damage to an enemy, or 184 healing to an ally, instantly and every 1 sec for 2 sec.","Выпускает в цель заряды священной энергии, наносящие противнику 81 ед. урона от светлой магии или восполняющие союзнику 184 ед. здоровья сразу и затем еще раз в 1 сек. в течение 2 сек."],["Renewed Hope","Новая надежда"],["Your heals from Flash Heal, Binding Heal, Lesser Heal, Heal, Greater Heal, and Penance gain 2% increased critical strike chance when cast on targets with Weakened Soul, and reduce the remaining duration of Weakened Soul on their target by 1 sec.","Вероятность критического эффекта \"Быстрого исцеления\", \"Связующего исцеления\", \"Малого исцеления\", \"Исцеления\", \"Великого исцеления\" и \"Исповеди\" повышается на 2%, когда вы применяете их к целям под действием \"Ослабленной души\". Эти заклинания также сокращают оставшееся время действия \"Ослабленной души\" на цели на 1 сек."],["Your heals from Flash Heal, Binding Heal, Lesser Heal, Heal, Greater Heal, and Penance gain 4% increased critical strike chance when cast on targets with Weakened Soul, and reduce the remaining duration of Weakened Soul on their target by 2 sec.","Вероятность критического эффекта \"Быстрого исцеления\", \"Связующего исцеления\", \"Малого исцеления\", \"Исцеления\", \"Великого исцеления\" и \"Исповеди\" повышается на 4%, когда вы применяете их к целям под действием \"Ослабленной души\". Эти заклинания также сокращают оставшееся время действия \"Ослабленной души\" на цели на 2 сек."],["Your heals from Flash Heal, Binding Heal, Lesser Heal, Heal, Greater Heal, and Penance gain 6% increased critical strike chance when cast on targets with Weakened Soul, and reduce the remaining duration of Weakened Soul on their target by 3 sec.","Вероятность критического эффекта \"Быстрого исцеления\", \"Связующего исцеления\", \"Малого исцеления\", \"Исцеления\", \"Великого исцеления\" и \"Исповеди\" повышается на 6%, когда вы применяете их к целям под действием \"Ослабленной души\". Эти заклинания также сокращают оставшееся время действия \"Ослабленной души\" на цели на 3 сек."],["Your heals from Flash Heal, Binding Heal, Lesser Heal, Heal, Greater Heal, and Penance gain 8% increased critical strike chance when cast on targets with Weakened Soul, and reduce the remaining duration of Weakened Soul on their target by 4 sec.","Вероятность критического эффекта \"Быстрого исцеления\", \"Связующего исцеления\", \"Малого исцеления\", \"Исцеления\", \"Великого исцеления\" и \"Исповеди\" повышается на 8%, когда вы применяете их к целям под действием \"Ослабленной души\". Эти заклинания также сокращают оставшееся время действия \"Ослабленной души\" на цели на 4 сек."],["Your heals from Flash Heal, Binding Heal, Lesser Heal, Heal, Greater Heal, and Penance gain 10% increased critical strike chance when cast on targets with Weakened Soul, and reduce the remaining duration of Weakened Soul on their target by 5 sec.","Вероятность критического эффекта \"Быстрого исцеления\", \"Связующего исцеления\", \"Малого исцеления\", \"Исцеления\", \"Великого исцеления\" и \"Исповеди\" повышается на 10%, когда вы применяете их к целям под действием \"Ослабленной души\". Эти заклинания также сокращают оставшееся время действия \"Ослабленной души\" на цели на 5 сек."],["Divine Aegis","Божественное покровительство"],["Your critical heals create a protective shield on the target, absorbing 5% of the amount healed. Lasts 12 sec.","Критические эффекты ваших исцеляющих заклинаний дают цели щит, поглощающий урон в размере 5% восстановленного здоровья. Время действия – 12 сек."],["Your critical heals create a protective shield on the target, absorbing 10% of the amount healed. Lasts 12 sec.","Критические эффекты ваших исцеляющих заклинаний дают цели щит, поглощающий урон в размере 10% восстановленного здоровья. Время действия – 12 сек."],["Your critical heals create a protective shield on the target, absorbing 15% of the amount healed. Lasts 12 sec.","Критические эффекты ваших исцеляющих заклинаний дают цели щит, поглощающий урон в размере 15% восстановленного здоровья. Время действия – 12 сек."],["Power Infusion","Придание сил"],["Infuses the target with power, increasing their spell damage and healing done by 20% for 15 sec.","Наполняет цель силой, увеличивая урон и силу исцеления заклинаний на 20% на 15 сек."],["Holy","Свет"],["Twilight Focus","Сумеречная концентрация"],["Gives you a 23% chance to avoid interruption caused by damage while casting any spell.","С вероятностью 23% позволяет избежать задержки при применении заклинания, когда вы получаете урон."],["Gives you a 47% chance to avoid interruption caused by damage while casting any spell.","С вероятностью 47% позволяет избежать задержки при применении заклинания, когда вы получаете урон."],["Gives you a 70% chance to avoid interruption caused by damage while casting any spell.","С вероятностью 70% позволяет избежать задержки при применении заклинания, когда вы получаете урон."],["Improved Renew","Улучшенное обновление"],["Increases the amount healed by your Renew spell by 5%.","Увеличение на 5% количества здоровья, восполняемого при действии заклинания \"Обновление\"."],["Increases the amount healed by your Renew spell by 10%.","Увеличение на 10% количества здоровья, восполняемого при действии заклинания \"Обновление\"."],["Increases the amount healed by your Renew spell by 15%.","Увеличение на 15% количества здоровья, восполняемого при действии заклинания \"Обновление\"."],["Holy Specialization","Cпециализация на магии Света"],["Increases the critical effect chance of your Holy spells by 1%.","Повышает вероятность критического эффекта заклинаний светлой магии на 1%."],["Increases the critical effect chance of your Holy spells by 2%.","Повышает вероятность критического эффекта заклинаний светлой магии на 2%."],["Increases the critical effect chance of your Holy spells by 3%.","Повышает вероятность критического эффекта заклинаний светлой магии на 3%."],["Increases the critical effect chance of your Holy spells by 4%.","Повышает вероятность критического эффекта заклинаний светлой магии на 4%."],["Increases the critical effect chance of your Holy spells by 5%.","Повышает вероятность критического эффекта заклинаний светлой магии на 5%."],["Spell Warding","Защита от заклинаний"],["Reduces all spell damage taken by 2%.","Снижение получаемого урона от заклинаний на 2%."],["Reduces all spell damage taken by 4%.","Снижение получаемого урона от заклинаний на 4%."],["Reduces all spell damage taken by 6%.","Снижение получаемого урона от заклинаний на 6%."],["Reduces all spell damage taken by 8%.","Снижение получаемого урона от заклинаний на 8%."],["Reduces all spell damage taken by 10%.","Снижение получаемого урона от заклинаний на 10%."],["Divine Fury","Божественное неистовство"],["Reduces the casting time of your Smite, Holy Fire, Heal, and Greater Heal spells by 0.1 sec.","Сокращает время применения \"Кары\", \"Священного огня\", \"Исцеления\" и \"Большего исцеления\" на 0.1 сек."],["Reduces the casting time of your Smite, Holy Fire, Heal, and Greater Heal spells by 0.2 sec.","Сокращает время применения \"Кары\", \"Священного огня\", \"Исцеления\" и \"Большего исцеления\" на 0.2 сек."],["Reduces the casting time of your Smite, Holy Fire, Heal, and Greater Heal spells by 0.3 sec.","Сокращает время применения \"Кары\", \"Священного огня\", \"Исцеления\" и \"Большего исцеления\" на 0.3 сек."],["Reduces the casting time of your Smite, Holy Fire, Heal, and Greater Heal spells by 0.4 sec.","Сокращает время применения \"Кары\", \"Священного огня\", \"Исцеления\" и \"Большего исцеления\" на 0.4 сек."],["Reduces the casting time of your Smite, Holy Fire, Heal, and Greater Heal spells by 0.5 sec.","Сокращает время применения \"Кары\", \"Священного огня\", \"Исцеления\" и \"Большего исцеления\" на 0.5 сек."],["Holy Nova","Кольцо Света"],["Causes an explosion of holy light around the caster, causing 27 Holy damage to all enemy targets within 10 yards and healing all party members within 10 yards for 47-55. These effects cause no threat.","Вспыхивает священным светом, нанося противникам в радиусе 10 м 27 ед. урона от светлой магии и восстанавливая участникам группы в радиусе 10 м 47-55 ед. здоровья. Не повышает уровень угрозы."],["Blessed Recovery","Благословленное восстановление"],["After being struck by a melee or ranged critical hit, or suffering more than 30% of your maximum Health from a single attack, heal 8% of the damage taken over 6 sec. Refreshing this effect carries over any remaining healing.","После получения критического удара в ближнем или дальнем бою или единовременном получении урона, превышающего 30% максимального запаса здоровья, вы восполняете здоровье в объеме 8% полученного урона за 6 сек. При обновлении эффекта новое исцеление добавляется к оставшемуся."],["After being struck by a melee or ranged critical hit, or suffering more than 30% of your maximum Health from a single attack, heal 17% of the damage taken over 6 sec. Refreshing this effect carries over any remaining healing.","После получения критического удара в ближнем или дальнем бою или единовременном получении урона, превышающего 30% максимального запаса здоровья, вы восполняете здоровье в объеме 17% полученного урона за 6 сек. При обновлении эффекта новое исцеление добавляется к оставшемуся."],["After being struck by a melee or ranged critical hit, or suffering more than 30% of your maximum Health from a single attack, heal 25% of the damage taken over 6 sec. Refreshing this effect carries over any remaining healing.","После получения критического удара в ближнем или дальнем бою или единовременном получении урона, превышающего 30% максимального запаса здоровья, вы восполняете здоровье в объеме 25% полученного урона за 6 сек. При обновлении эффекта новое исцеление добавляется к оставшемуся."],["Inspiration","Вдохновение"],["Your non-periodic critical heals increase your target's Armor by 8% for 15 sec.","Критические эффекты заклинаний прямого исцеления укрепляют броню вашей цели на 8% на 15 сек."],["Your non-periodic critical heals increase your target's Armor by 17% for 15 sec.","Критические эффекты заклинаний прямого исцеления укрепляют броню вашей цели на 17% на 15 сек."],["Your non-periodic critical heals increase your target's Armor by 25% for 15 sec.","Критические эффекты заклинаний прямого исцеления укрепляют броню вашей цели на 25% на 15 сек."],["Holy Reach","Предел сил Света"],["Increases the range of your Smite and Holy Fire spells and the radius of your Prayer of Healing and Holy Nova spells by 10%.","Увеличивает дальность действия \"Кары\" и \"Священного огня\", а также радиус действия \"Молитвы об исцелении\" и \"Кольца Света\" на 10%."],["Increases the range of your Smite and Holy Fire spells and the radius of your Prayer of Healing and Holy Nova spells by 20%.","Увеличивает дальность действия \"Кары\" и \"Священного огня\", а также радиус действия \"Молитвы об исцелении\" и \"Кольца Света\" на 20%."],["Improved Healing","Улучшенное исцеление"],["Reduces the Mana cost of your Lesser Heal, Heal, Greater Heal, Penance, and Prayer of Mending spells by 5%.","Снижает затраты маны на \"Малое исцеление\", \"Исцеление\", \"Большее исцеление\", \"Исповедь\" и \"Молитву восстановления\" на 5%."],["Reduces the Mana cost of your Lesser Heal, Heal, Greater Heal, Penance, and Prayer of Mending spells by 10%.","Снижает затраты маны на \"Малое исцеление\", \"Исцеление\", \"Большее исцеление\", \"Исповедь\" и \"Молитву восстановления\" на 10%."],["Reduces the Mana cost of your Lesser Heal, Heal, Greater Heal, Penance, and Prayer of Mending spells by 15%.","Снижает затраты маны на \"Малое исцеление\", \"Исцеление\", \"Большее исцеление\", \"Исповедь\" и \"Молитву восстановления\" на 15%."],["Searing Light","Опаляющий свет"],["Increases your Holy damage done by 2%, and gives a 5% chance each time your Holy Fire spell deals periodic damage for your next Holy Nova to cost no Mana.","Увеличивает наносимый урон от светлой магии на 2%. Каждый раз, когда \"Священный огонь\" наносит периодический урон, следующее применение \"Кольца Света\" с вероятностью 5% не требует затрат маны."],["Increases your Holy damage done by 5%, and gives a 10% chance each time your Holy Fire spell deals periodic damage for your next Holy Nova to cost no Mana.","Увеличивает наносимый урон от светлой магии на 5%. Каждый раз, когда \"Священный огонь\" наносит периодический урон, следующее применение \"Кольца Света\" с вероятностью 10% не требует затрат маны."],["Binding Heal","Связующее исцеление"],["Heals a friendly target and the caster for 247. Low threat.","Восполняет вам и союзнику 247 ед. здоровья. Создает низкий уровень угрозы."],["Litany of Light","Литания Света"],["When you cast a healing spell, gain Mana equal to 5% of the base cost of the spell if your previous heal was a different spell.","Когда вы применяете исцеляющее заклинание, отличающееся от вашего предыдущего исцеляющего заклинания, вы восполняете ману в объеме 5% его базовой стоимости."],["When you cast a healing spell, gain Mana equal to 10% of the base cost of the spell if your previous heal was a different spell.","Когда вы применяете исцеляющее заклинание, отличающееся от вашего предыдущего исцеляющего заклинания, вы восполняете ману в объеме 10% его базовой стоимости."],["Spirit of Redemption","Дух воздаяния"],["Upon death, the priest becomes the Spirit of Redemption for 15 sec. The Spirit of Redemption cannot move, attack, be attacked or targeted by any spells or effects. While in this form the priest can cast any healing spell free of cost. When the effect ends, the priest dies.","После смерти жрец превращается в Дух воздаяния на 15 сек. Дух воздаяния не может двигаться, атаковать, быть атакованным или стать целью любых заклинаний и воздействий. Находясь в этом облике, жрец может бесплатно воспользоваться любым исцеляющим заклинанием. По окончании действия эффекта жрец умирает."],["Spiritual Guidance","Духовное направление"],["Increases your spell healing by up to 5% of your total Spirit and your spell damage by up to 1% of your total Spirit.","Повышает силу исцеления заклинаний максимум на 5% вашего духа, а урон от заклинаний – максимум на 1% вашего духа."],["Increases your spell healing by up to 10% of your total Spirit and your spell damage by up to 3% of your total Spirit.","Повышает силу исцеления заклинаний максимум на 10% вашего духа, а урон от заклинаний – максимум на 3% вашего духа."],["Increases your spell healing by up to 15% of your total Spirit and your spell damage by up to 5% of your total Spirit.","Повышает силу исцеления заклинаний максимум на 15% вашего духа, а урон от заклинаний – максимум на 5% вашего духа."],["Increases your spell healing by up to 20% of your total Spirit and your spell damage by up to 6% of your total Spirit.","Повышает силу исцеления заклинаний максимум на 20% вашего духа, а урон от заклинаний – максимум на 6% вашего духа."],["Increases your spell healing by up to 25% of your total Spirit and your spell damage by up to 8% of your total Spirit.","Повышает силу исцеления заклинаний максимум на 25% вашего духа, а урон от заклинаний – максимум на 8% вашего духа."],["Spiritual Healing","Духовное исцеление"],["Increases the amount healed by your spells by 3%.","Усиливает исцеление от ваших заклинаний на 3%."],["Increases the amount healed by your spells by 7%.","Усиливает исцеление от ваших заклинаний на 7%."],["Increases the amount healed by your spells by 10%.","Усиливает исцеление от ваших заклинаний на 10%."],["Prayer of Mending","Молитва восстановления"],["Places a spell on the target that heals them for a dynamic amount the next time they take damage or receive non-periodic healing. When the heal occurs, Prayer of Mending jumps to a party or raid member within 20 yards. Jumps up to 5 times and lasts 30 sec after each jump. This spell can only be placed on one target at a time per caster.","Применяет к цели заклинание, восполняющее ей динамическое количество ед. здоровья при следующем получении урона или исцеления прямого действия. После срабатывания \"Молитва восстановления\" переходит к другому участнику группы или рейда в радиусе 20 м. Максимум переходов – 5. Действует 30 сек. после каждого перехода. Можно применить только к одной цели одновременно."],["Shadow","Темная магия"],["Shadow Focus","Средоточие Тьмы"],["Improves your chance to hit with Shadow spells by 1%.","Повышает вероятность попадания заклинаниями темной магии на 1%."],["Improves your chance to hit with Shadow spells by 2%.","Повышает вероятность попадания заклинаниями темной магии на 2%."],["Improves your chance to hit with Shadow spells by 3%.","Повышает вероятность попадания заклинаниями темной магии на 3%."],["Improves your chance to hit with Shadow spells by 4%.","Повышает вероятность попадания заклинаниями темной магии на 4%."],["Improves your chance to hit with Shadow spells by 5%.","Повышает вероятность попадания заклинаниями темной магии на 5%."],["Blackout","Затмение"],["Gives your Shadow damage spells a 2% chance to stun the target for 3 sec.","Заклинания темной магии с вероятностью 2% оглушают цель на 3 сек."],["Gives your Shadow damage spells a 4% chance to stun the target for 3 sec.","Заклинания темной магии с вероятностью 4% оглушают цель на 3 сек."],["Gives your Shadow damage spells a 6% chance to stun the target for 3 sec.","Заклинания темной магии с вероятностью 6% оглушают цель на 3 сек."],["Gives your Shadow damage spells a 8% chance to stun the target for 3 sec.","Заклинания темной магии с вероятностью 8% оглушают цель на 3 сек."],["Gives your Shadow damage spells a 10% chance to stun the target for 3 sec.","Заклинания темной магии с вероятностью 10% оглушают цель на 3 сек."],["Spirit Tap","Захват духа"],["Gives you a 20% chance to gain a 100% bonus to your Spirit for 15 sec after killing a non-trivial target. For the duration, your Mana will regenerate at a 50% of normal rate while casting.","С вероятностью 20% после убийства представляющего угрозу противника ваш дух повышается на 100% на 15 сек. При этом вы восполняете ману во время применения заклинаний со скоростью 50%."],["Gives you a 40% chance to gain a 100% bonus to your Spirit for 15 sec after killing a non-trivial target. For the duration, your Mana will regenerate at a 50% of normal rate while casting.","С вероятностью 40% после убийства представляющего угрозу противника ваш дух повышается на 100% на 15 сек. При этом вы восполняете ману во время применения заклинаний со скоростью 50%."],["Gives you a 60% chance to gain a 100% bonus to your Spirit for 15 sec after killing a non-trivial target. For the duration, your Mana will regenerate at a 50% of normal rate while casting.","С вероятностью 60% после убийства представляющего угрозу противника ваш дух повышается на 100% на 15 сек. При этом вы восполняете ману во время применения заклинаний со скоростью 50%."],["Gives you a 80% chance to gain a 100% bonus to your Spirit for 15 sec after killing a non-trivial target. For the duration, your Mana will regenerate at a 50% of normal rate while casting.","С вероятностью 80% после убийства представляющего угрозу противника ваш дух повышается на 100% на 15 сек. При этом вы восполняете ману во время применения заклинаний со скоростью 50%."],["Gives you a 100% chance to gain a 100% bonus to your Spirit for 15 sec after killing a non-trivial target. For the duration, your Mana will regenerate at a 50% of normal rate while casting.","С вероятностью 100% после убийства представляющего угрозу противника ваш дух повышается на 100% на 15 сек. При этом вы восполняете ману во время применения заклинаний со скоростью 50%."],["Shadow Affinity","Единение с Тьмой"],["Reduces the threat generated by your Shadow spells by 10%.","Снижает уровень угрозы, создаваемой вашими заклинаниями категории \"Тьма\", на 10%."],["Reduces the threat generated by your Shadow spells by 20%.","Снижает уровень угрозы, создаваемой вашими заклинаниями категории \"Тьма\", на 20%."],["Reduces the threat generated by your Shadow spells by 30%.","Снижает уровень угрозы, создаваемой вашими заклинаниями категории \"Тьма\", на 30%."],["Improved Shadow Word: Pain","Улучшенное слово Тьмы: Боль"],["Increases the duration of your Shadow Word: Pain spell by 3 sec.","Продлевает время действия заклинания \"Слово Тьмы: Боль\" на 3 сек."],["Increases the duration of your Shadow Word: Pain spell by 6 sec.","Продлевает время действия заклинания \"Слово Тьмы: Боль\" на 6 сек."],["Shadow Reach","Предел Тьмы"],["Increases the range of your offensive Shadow spells by 10%.","Увеличивает дальность действия атакующих заклинаний темной магии на 10%."],["Increases the range of your offensive Shadow spells by 20%.","Увеличивает дальность действия атакующих заклинаний темной магии на 20%."],["Improved Mind Blast","Улучшенный взрыв разума"],["Reduces the cooldown of your Mind Blast spell by 0.5 sec.","Время восстановления заклинания \"Взрыв разума\" сокращено на 0.5 сек."],["Reduces the cooldown of your Mind Blast spell by 1 sec.","Время восстановления заклинания \"Взрыв разума\" сокращено на 1 сек."],["Reduces the cooldown of your Mind Blast spell by 1.5 sec.","Время восстановления заклинания \"Взрыв разума\" сокращено на 1.5 сек."],["Reduces the cooldown of your Mind Blast spell by 2 sec.","Время восстановления заклинания \"Взрыв разума\" сокращено на 2 сек."],["Reduces the cooldown of your Mind Blast spell by 2.5 sec.","Время восстановления заклинания \"Взрыв разума\" сокращено на 2.5 сек."],["Improved Psychic Scream","Улучшенный ментальный крик"],["Reduces the cooldown of your Psychic Scream spell by 2 sec.","Сокращение времени восстановления заклинания \"Ментальный крик\" на 2 сек."],["Reduces the cooldown of your Psychic Scream spell by 4 sec.","Сокращение времени восстановления заклинания \"Ментальный крик\" на 4 сек."],["Mind Flay","Пытка разума"],["Assault the target's mind with Shadow energy, causing 63 Shadow damage over 3 sec and slowing their movement speed by 50%.","Поражает разум противника энергией Тьмы, наносящей 63 ед. урона от темной магии за 3 сек. и снижающей скорость передвижения цели на 50%."],["Improved Mind Flay","Улучшенная пытка разума"],["Your Mind Flay now deals 10% more damage, gains 5 yards increased range, but slows the target's movement speed by 35%.","\"Пытка разума\" теперь наносит на 10% больше урона, а радиус ее действия увеличивается на 5 м. Кроме того, скорость передвижения цели снижается на 35%."],["Your Mind Flay now deals 20% more damage, gains 10 yards increased range, but slows the target's movement speed by 20%.","\"Пытка разума\" теперь наносит на 20% больше урона, а радиус ее действия увеличивается на 10 м. Кроме того, скорость передвижения цели снижается на 20%."],["Improved Fade","Улучшенный \"Уход в тень\""],["Decreases the cooldown of your Fade ability by 3 sec.","Уменьшает время восстановления \"Ухода в тень\" на 3 сек."],["Decreases the cooldown of your Fade ability by 6 sec.","Уменьшает время восстановления \"Ухода в тень\" на 6 сек."],["Vampiric Embrace","Объятия вампира"],["Afflicts your target with Shadow energy that causes all party members to be healed for 20% of any Shadow spell damage you deal for 30 sec. Vampiric Embrace also grants a chance for your Spirit Tap talent to trigger when enemies afflicted by it die.","Поражает цель энергией Тьмы, в результате чего участники группы восстанавливают здоровье в размере 20% урона, наносимого вашими заклинаниями темной магии. Время действия – 30 сек. Когда цель \"Объятий вампира\" погибает, с некоторой вероятностью срабатывает \"Захват духа\"."],["Shadow Weaving","Плетение Тьмы"],["Your Shadow damage spells have a 33% chance to increase the Shadow damage you deal by 2% for 15 sec, stacking up to 5 times.","Наносящие урон заклинания темной магии с вероятностью 33% увеличивают наносимый урон от темной магии на 2%. Эффект длится 15 сек. и суммируется до 5 раз."],["Your Shadow damage spells have a 67% chance to increase the Shadow damage you deal by 2% for 15 sec, stacking up to 5 times.","Наносящие урон заклинания темной магии с вероятностью 67% увеличивают наносимый урон от темной магии на 2%. Эффект длится 15 сек. и суммируется до 5 раз."],["Your Shadow damage spells have a 100% chance to increase the Shadow damage you deal by 2% for 15 sec, stacking up to 5 times.","Наносящие урон заклинания темной магии с вероятностью 100% увеличивают наносимый урон от темной магии на 2%. Эффект длится 15 сек. и суммируется до 5 раз."],["Silence","Молчание"],["Silences the target, preventing them from casting spells for 5 sec and interrupting their spellcasts for 3 sec.","Вызывает у цели немоту, предотвращая применение заклинаний в течение 5 сек. и прерывая применение заклинаний на 3 сек."],["Devouring Contagion","Всепожирающее заражение"],["Early Demise","Ранняя гибель"],["Increases Shadow Word: Death's critical strike chance on targets at or below 20% health by 15%.","Вероятность критического удара \"Слова Тьмы: Смерть\" повышается на 15% против целей с уровнем здоровья ниже 20%."],["Increases Shadow Word: Death's critical strike chance on targets at or below 20% health by 30%.","Вероятность критического удара \"Слова Тьмы: Смерть\" повышается на 30% против целей с уровнем здоровья ниже 20%."],["Darkness","Мрак"],["Increases your Shadow damage done by 2%.","Увеличивает наносимый вами урон от темной магии на 2%."],["Increases your Shadow damage done by 4%.","Увеличивает наносимый вами урон от темной магии на 4%."],["Increases your Shadow damage done by 6%.","Увеличивает наносимый вами урон от темной магии на 6%."],["Increases your Shadow damage done by 8%.","Увеличивает наносимый вами урон от темной магии на 8%."],["Increases your Shadow damage done by 10%.","Увеличивает наносимый вами урон от темной магии на 10%."],["Shadowform","Облик Тьмы"],["Assume Shadowform, increasing your Shadow damage by 10%, reducing the Mana cost of all Shadow spells by 50%, increasing the critical strike damage bonus of your Shadow spells by 100%, and reducing Physical damage taken by you by 15%. However, you may not cast healing spells while in this form.","Вы принимаете облик Тьмы, увеличивающий урон от заклинаний темной магии на 10%, снижающий затраты маны на их применение на 50%, увеличивающий критический урон от темной магии на 100% и уменьшающий получаемый физический урон на 15%. В этом облике нельзя применять исцеляющие заклинания."]]},"shaman":{"build":"1.60.1.70009","className":"Shaman","pairs":[["Shaman","Шаман"],["Elemental","Стихии"],["Convection","Конвекция"],["Reduces the mana cost of your Shock, Lightning Bolt, Lava Burst, and Chain Lightning spells by 2%.","Снижает затраты маны на заклинания категории \"Шок\", \"Молнию\", \"Выброс лавы\" и \"Цепную молнию\" на 2%."],["Reduces the mana cost of your Shock, Lightning Bolt, Lava Burst, and Chain Lightning spells by 4%.","Снижает затраты маны на заклинания категории \"Шок\", \"Молнию\", \"Выброс лавы\" и \"Цепную молнию\" на 4%."],["Reduces the mana cost of your Shock, Lightning Bolt, Lava Burst, and Chain Lightning spells by 6%.","Снижает затраты маны на заклинания категории \"Шок\", \"Молнию\", \"Выброс лавы\" и \"Цепную молнию\" на 6%."],["Reduces the mana cost of your Shock, Lightning Bolt, Lava Burst, and Chain Lightning spells by 8%.","Снижает затраты маны на заклинания категории \"Шок\", \"Молнию\", \"Выброс лавы\" и \"Цепную молнию\" на 8%."],["Reduces the mana cost of your Shock, Lightning Bolt, Lava Burst, and Chain Lightning spells by 10%.","Снижает затраты маны на заклинания категории \"Шок\", \"Молнию\", \"Выброс лавы\" и \"Цепную молнию\" на 10%."],["Concussion","Сотрясение мозга"],["Increases the damage done by your Lightning Bolt, Chain Lightning, and Earth Shock spells by 1%.","Увеличивает урон от \"Молнии\", \"Цепной молнии\" и \"Земного шока\" на 1%."],["Increases the damage done by your Lightning Bolt, Chain Lightning, and Earth Shock spells by 2%.","Увеличивает урон от \"Молнии\", \"Цепной молнии\" и \"Земного шока\" на 2%."],["Increases the damage done by your Lightning Bolt, Chain Lightning, and Earth Shock spells by 3%.","Увеличивает урон от \"Молнии\", \"Цепной молнии\" и \"Земного шока\" на 3%."],["Increases the damage done by your Lightning Bolt, Chain Lightning, and Earth Shock spells by 4%.","Увеличивает урон от \"Молнии\", \"Цепной молнии\" и \"Земного шока\" на 4%."],["Increases the damage done by your Lightning Bolt, Chain Lightning, and Earth Shock spells by 5%.","Увеличивает урон от \"Молнии\", \"Цепной молнии\" и \"Земного шока\" на 5%."],["Elemental Warding","Защита от стихий"],["Reduces damage taken from Fire, Frost, and Nature effects by 3%.","Уменьшает урон, получаемый от огня, магии льда и сил природы, на 3%."],["Reduces damage taken from Fire, Frost, and Nature effects by 7%.","Уменьшает урон, получаемый от огня, магии льда и сил природы, на 7%."],["Reduces damage taken from Fire, Frost, and Nature effects by 10%.","Уменьшает урон, получаемый от огня, магии льда и сил природы, на 10%."],["Reverberation","Отзвук"],["Reduces the cooldown of your Shock spells by 0.2 sec.","Сокращает время восстановления заклинаний категории \"Шок\" на 0.2 сек."],["Reduces the cooldown of your Shock spells by 0.4 sec.","Сокращает время восстановления заклинаний категории \"Шок\" на 0.4 сек."],["Reduces the cooldown of your Shock spells by 0.6 sec.","Сокращает время восстановления заклинаний категории \"Шок\" на 0.6 сек."],["Reduces the cooldown of your Shock spells by 0.8 sec.","Сокращает время восстановления заклинаний категории \"Шок\" на 0.8 сек."],["Reduces the cooldown of your Shock spells by 1.0 sec.","Сокращает время восстановления заклинаний категории \"Шок\" на 1.0 сек."],["Call of Flame","Зов пламени"],["Increases the damage done by your Fire Totems and by your Flame Shock, Fire Nova, and Lava Burst spells by 5%.","Увеличивает урон, наносимый вашими тотемами огня и заклинаниями \"Огненный шок\", \"Кольцо огня\" и \"Выброс лавы\", на 5%."],["Increases the damage done by your Fire Totems and by your Flame Shock, Fire Nova, and Lava Burst spells by 10%.","Увеличивает урон, наносимый вашими тотемами огня и заклинаниями \"Огненный шок\", \"Кольцо огня\" и \"Выброс лавы\", на 10%."],["Increases the damage done by your Fire Totems and by your Flame Shock, Fire Nova, and Lava Burst spells by 15%.","Увеличивает урон, наносимый вашими тотемами огня и заклинаниями \"Огненный шок\", \"Кольцо огня\" и \"Выброс лавы\", на 15%."],["Elemental Devastation","Опустошение Духов стихии"],["Your offensive spell critical strikes will increase your chance to get a critical strike with melee attacks by 3% for 10 sec.","Если ваше атакующее заклинание наносит критический урон, вероятность критического удара в ближнем бою повышается на 3% на 10 сек."],["Your offensive spell critical strikes will increase your chance to get a critical strike with melee attacks by 6% for 10 sec.","Если ваше атакующее заклинание наносит критический урон, вероятность критического удара в ближнем бою повышается на 6% на 10 сек."],["Your offensive spell critical strikes will increase your chance to get a critical strike with melee attacks by 9% for 10 sec.","Если ваше атакующее заклинание наносит критический урон, вероятность критического удара в ближнем бою повышается на 9% на 10 сек."],["Elemental Focus","Концентрация стихий"],["Gives you a 10% chance to enter a Clearcasting state after casting any Fire, Frost, or Nature damage spell. The Clearcasting state reduces the mana cost of your next damage spell by 100%.","При применении заклинания огня, магии льда или сил природы вы с вероятностью 10% переходите в состояние \"Ясность мысли\". \"Ясность мысли\" снижает затраты маны на следующее наносящее урон заклинание на 100%."],["Elemental Alacrity","Стихийная стремительность"],["Reduces the cast time of your Lightning Bolt, Chain Lightning, and Lava Burst spells by 0.17 sec.","Сокращает время применения заклинаний \"Молния\", \"Цепная молния\" и \"Выброс лавы\" на 0.17 сек."],["Reduces the cast time of your Lightning Bolt, Chain Lightning, and Lava Burst spells by 0.33 sec.","Сокращает время применения заклинаний \"Молния\", \"Цепная молния\" и \"Выброс лавы\" на 0.33 сек."],["Reduces the cast time of your Lightning Bolt, Chain Lightning, and Lava Burst spells by 0.50 sec.","Сокращает время применения заклинаний \"Молния\", \"Цепная молния\" и \"Выброс лавы\" на 0.50 сек."],["Improved Fire Nova","Улучшенное кольцо огня"],["Increases the damage done by your Fire Nova spell by 10% and reduces its cooldown by 2 sec.","Увеличивает урон от \"Кольца огня\" на 10% и сокращает время его восстановления на 2 сек."],["Increases the damage done by your Fire Nova spell by 20% and reduces its cooldown by 4 sec.","Увеличивает урон от \"Кольца огня\" на 20% и сокращает время его восстановления на 4 сек."],["Eye of the Storm","Око шторма"],["Reduces the pushback suffered from damaging attacks while casting Lightning Bolt, Chain Lightning, and Lava Burst by 23%.","Сокращает задержку при получении урона во время произнесения заклинаний \"Молния\", \"Цепная молния\" и \"Выброс лавы\" на 23%."],["Reduces the pushback suffered from damaging attacks while casting Lightning Bolt, Chain Lightning, and Lava Burst by 47%.","Сокращает задержку при получении урона во время произнесения заклинаний \"Молния\", \"Цепная молния\" и \"Выброс лавы\" на 47%."],["Reduces the pushback suffered from damaging attacks while casting Lightning Bolt, Chain Lightning, and Lava Burst by 70%.","Сокращает задержку при получении урона во время произнесения заклинаний \"Молния\", \"Цепная молния\" и \"Выброс лавы\" на 70%."],["Call of Thunder","Зов грома"],["Increases the critical strike chance of your Lightning Bolt and Chain Lightning spells by 3%.","Повышает вероятность критического удара \"Молнии\" и \"Цепной молнии\" на 3%."],["Elemental Reach","Предел стихии"],["Increases the range of your Lightning Bolt, Chain Lightning, Fire Nova, and Lava Burst spells by 3 yards, and increases the range of your Flame Shock spell by 8 yards.","Увеличивает дальность действия \"Молнии\", \"Цепной молнии\", \"Кольца огня\" и \"Выброса лавы\" на 3 м, а \"Огненного шока\" – на 8 м."],["Increases the range of your Lightning Bolt, Chain Lightning, Fire Nova, and Lava Burst spells by 6 yards, and increases the range of your Flame Shock spell by 15 yards.","Увеличивает дальность действия \"Молнии\", \"Цепной молнии\", \"Кольца огня\" и \"Выброса лавы\" на 6 м, а \"Огненного шока\" – на 15 м."],["Lightning Overload","Электрическая перегрузка"],["Gives your Lightning Bolt and Chain Lightning spells a 3% chance to cast a second, similar spell on the same target at no additional cost that causes half damage and no threat.","\"Молния\" и \"Цепная молния\" с вероятностью 3% применяют второе такое же заклинание к той же цели без затрат ресурсов. Второе заклинание наносит вдвое меньше урона и не создает угрозы."],["Gives your Lightning Bolt and Chain Lightning spells a 7% chance to cast a second, similar spell on the same target at no additional cost that causes half damage and no threat.","\"Молния\" и \"Цепная молния\" с вероятностью 7% применяют второе такое же заклинание к той же цели без затрат ресурсов. Второе заклинание наносит вдвое меньше урона и не создает угрозы."],["Gives your Lightning Bolt and Chain Lightning spells a 10% chance to cast a second, similar spell on the same target at no additional cost that causes half damage and no threat.","\"Молния\" и \"Цепная молния\" с вероятностью 10% применяют второе такое же заклинание к той же цели без затрат ресурсов. Второе заклинание наносит вдвое меньше урона и не создает угрозы."],["Earthbound","Узы земли"],["Your Earthbind Totem Immobilizes nearby targets for 5 sec when cast.","Тотем оков земли обездвиживает ближайшие цели на 5 сек. при применении."],["Elemental Fury","Неистовство стихий"],["Increases the critical strike damage bonus of your Searing and Magma Totems and your Fire, Frost, and Nature spells by 20%.","Увеличивает критический урон от опаляющего тотема и тотема магмы, а также заклинаний огня, магии льда и сил природы на 20%."],["Increases the critical strike damage bonus of your Searing and Magma Totems and your Fire, Frost, and Nature spells by 40%.","Увеличивает критический урон от опаляющего тотема и тотема магмы, а также заклинаний огня, магии льда и сил природы на 40%."],["Increases the critical strike damage bonus of your Searing and Magma Totems and your Fire, Frost, and Nature spells by 60%.","Увеличивает критический урон от опаляющего тотема и тотема магмы, а также заклинаний огня, магии льда и сил природы на 60%."],["Increases the critical strike damage bonus of your Searing and Magma Totems and your Fire, Frost, and Nature spells by 80%.","Увеличивает критический урон от опаляющего тотема и тотема магмы, а также заклинаний огня, магии льда и сил природы на 80%."],["Increases the critical strike damage bonus of your Searing and Magma Totems and your Fire, Frost, and Nature spells by 100%.","Увеличивает критический урон от опаляющего тотема и тотема магмы, а также заклинаний огня, магии льда и сил природы на 100%."],["Lava Burst","Выброс лавы"],["You hurl molten lava at the target, dealing 164 Fire damage. If your Flame Shock is on the target, Lava Burst deals 20% increased damage.","Вы бросаете в противника раскаленную лаву, нанося 164 ед. урона от огня. Если цель находится под действием эффекта \"Огненный шок\", \"Выброс лавы\" наносит на 20% больше урона."],["Enhancement","Совершенствование"],["Earth's Grasp","Земной захват"],["Increases the health of your Stoneclaw Totem by 25% and the radius of your Earthbind Totem by 10%.","Увеличивает запас прочности тотема каменного когтя на 25%, а радиус действия тотема оков земли – на 10%."],["Increases the health of your Stoneclaw Totem by 50% and the radius of your Earthbind Totem by 20%.","Увеличивает запас прочности тотема каменного когтя на 50%, а радиус действия тотема оков земли – на 20%."],["Thundering Strikes","Грохочущие удары"],["Improves your chance to get a critical strike with all spells and attacks by 1%.","Повышает вероятность критического удара атак и заклинаний на 1%."],["Improves your chance to get a critical strike with all spells and attacks by 2%.","Повышает вероятность критического удара атак и заклинаний на 2%."],["Improves your chance to get a critical strike with all spells and attacks by 3%.","Повышает вероятность критического удара атак и заклинаний на 3%."],["Improves your chance to get a critical strike with all spells and attacks by 4%.","Повышает вероятность критического удара атак и заклинаний на 4%."],["Improves your chance to get a critical strike with all spells and attacks by 5%.","Повышает вероятность критического удара атак и заклинаний на 5%."],["Ancestral Knowledge","Знания предков"],["Increases your Intellect by 2%.","Повышает интеллект на 2%."],["Increases your Intellect by 4%.","Повышает интеллект на 4%."],["Increases your Intellect by 6%.","Повышает интеллект на 6%."],["Increases your Intellect by 8%.","Повышает интеллект на 8%."],["Increases your Intellect by 10%.","Повышает интеллект на 10%."],["Guardian Totems","Сторожевые тотемы"],["Increases the amount of damage reduced by your Stoneskin Totem and Windwall Totem by 10% and reduces the cooldown of your Grounding Totem by 1 sec.","\"Тотем каменной кожи\" и \"Тотем стены ветра\" уменьшают урон еще на 10%, а \"Тотем заземления\" восстанавливается на 1 сек. быстрее."],["Increases the amount of damage reduced by your Stoneskin Totem and Windwall Totem by 20% and reduces the cooldown of your Grounding Totem by 2 sec.","\"Тотем каменной кожи\" и \"Тотем стены ветра\" уменьшают урон еще на 20%, а \"Тотем заземления\" восстанавливается на 2 сек. быстрее."],["Mental Dexterity","Гибкость разума"],["Increases your Attack Power by an amount equal to 33% of your Intellect.","Увеличивает вашу силу атаки на 33% интеллекта."],["Increases your Attack Power by an amount equal to 67% of your Intellect.","Увеличивает вашу силу атаки на 67% интеллекта."],["Increases your Attack Power by an amount equal to 100% of your Intellect.","Увеличивает вашу силу атаки на 100% интеллекта."],["Improved Ghost Wolf","Улучшенный призрачный волк"],["Reduces the cast time of your Ghost Wolf spell by 1.0 sec, and Ghost Wolf may be used indoors.","Сокращает время применения \"Призрачного волка\" на 1.0 сек. и позволяет использовать его в помещениях."],["Reduces the cast time of your Ghost Wolf spell by 3.0 sec, and Ghost Wolf may be used indoors.","Сокращает время применения \"Призрачного волка\" на 3.0 сек. и позволяет использовать его в помещениях."],["Improved Lightning Shield","Улучшенный щит молний"],["Increases the damage done by your Lightning Shield orbs by 5%.","Увеличивает урон от сфер \"Щита молний\" на 5%."],["Increases the damage done by your Lightning Shield orbs by 10%.","Увеличивает урон от сфер \"Щита молний\" на 10%."],["Increases the damage done by your Lightning Shield orbs by 15%.","Увеличивает урон от сфер \"Щита молний\" на 15%."],["Elemental Weapons","Оружие стихий"],["Increases the melee attack power bonus of your Rockbiter Weapon by 7%, your Windfury Weapon effect by 13% and increases the damage caused by your Flametongue Weapon and Frostbrand Weapon by 5%.","Увеличивает бонус к силе атаки ближнего боя от \"Оружия камнедробителя\" на 7%, эффект \"Оружия неистовства ветра\" – на 13%, а урон от \"Оружия языка пламени\" и \"Оружия ледяного клейма\" – на 5%."],["Increases the melee attack power bonus of your Rockbiter Weapon by 13%, your Windfury Weapon effect by 27% and increases the damage caused by your Flametongue Weapon and Frostbrand Weapon by 10%.","Увеличивает бонус к силе атаки ближнего боя от \"Оружия камнедробителя\" на 13%, эффект \"Оружия неистовства ветра\" – на 27%, а урон от \"Оружия языка пламени\" и \"Оружия ледяного клейма\" – на 10%."],["Increases the melee attack power bonus of your Rockbiter Weapon by 20%, your Windfury Weapon effect by 40% and increases the damage caused by your Flametongue Weapon and Frostbrand Weapon by 15%.","Увеличивает бонус к силе атаки ближнего боя от \"Оружия камнедробителя\" на 20%, эффект \"Оружия неистовства ветра\" – на 40%, а урон от \"Оружия языка пламени\" и \"Оружия ледяного клейма\" – на 15%."],["Shamanistic Focus","Концентрация шамана"],["Reduces the mana cost of your Shock and Lightning Shield spells by 45%.","Снижает затраты маны на \"Щит молний\" и заклинания категории \"Шок\" на 45%."],["Anticipation","Предчувствие"],["Increases your chance to dodge by an additional 2%.","Повышает вероятность уклонения еще на 2%."],["Increases your chance to dodge by an additional 4%.","Повышает вероятность уклонения еще на 4%."],["Increases your chance to dodge by an additional 6%.","Повышает вероятность уклонения еще на 6%."],["Toughness","Крепость"],["Increases your Stamina by 2%.","Повышает вашу выносливость на 2%."],["Increases your Stamina by 4%.","Повышает вашу выносливость на 4%."],["Increases your Stamina by 6%.","Повышает вашу выносливость на 6%."],["Increases your Stamina by 8%.","Повышает вашу выносливость на 8%."],["Increases your Stamina by 10%.","Повышает вашу выносливость на 10%."],["Flurry","Шквал"],["Increases your attack speed by 5% for your next 3 swings after dealing a melee critical strike.","После того как вы наносите критический удар в ближнем бою, скорость атаки повышается на 5%. Действует, пока вы не нанесете 3 удара."],["Increases your attack speed by 10% for your next 3 swings after dealing a melee critical strike.","После того как вы наносите критический удар в ближнем бою, скорость атаки повышается на 10%. Действует, пока вы не нанесете 3 удара."],["Increases your attack speed by 15% for your next 3 swings after dealing a melee critical strike.","После того как вы наносите критический удар в ближнем бою, скорость атаки повышается на 15%. Действует, пока вы не нанесете 3 удара."],["Increases your attack speed by 20% for your next 3 swings after dealing a melee critical strike.","После того как вы наносите критический удар в ближнем бою, скорость атаки повышается на 20%. Действует, пока вы не нанесете 3 удара."],["Increases your attack speed by 25% for your next 3 swings after dealing a melee critical strike.","После того как вы наносите критический удар в ближнем бою, скорость атаки повышается на 25%. Действует, пока вы не нанесете 3 удара."],["Stormstrike","Удар бури"],["Instantly strike for normal weapon damage and increase the damage you deal to the target with your next Lightning Bolt, Chain Lightning, or Earth Shock spell by 20% for 12 sec.","Мгновенно наносит цели урон от оружия и увеличивает урон, который ваше следующее заклинание \"Молния\", \"Цепная молния\" или \"Земной шок\" нанесет этой цели, на 20% на 12 сек."],["Spirit Weapons","Духовное оружие"],["Gives a chance to parry enemy melee attacks, reduces all threat generated by your attacks by 30% while Rockbiter Weapon is not active, and increases all threat generated by 30% while Rockbiter Weapon is active.","Когда \"Оружие камнедробителя\" не активно, дает шанс парировать атаки противника в ближнем бою и снижает уровень создаваемой угрозы на 30%. Когда \"Оружие камнедробителя\" активно, повышает уровень создаваемой угрозы на 30%."],["Mental Quickness","Ментальная скорость"],["Increases your spell damage and healing by up to 15% of your Intellect.","Увеличивает урон от заклинаний и силу исцеления максимум на 15% интеллекта."],["Increases your spell damage and healing by up to 30% of your Intellect.","Увеличивает урон от заклинаний и силу исцеления максимум на 30% интеллекта."],["Improved Stormstrike","Улучшенный удар бури"],["When you Stormstrike, you have a 50% chance to gain 50% mana regeneration while casting spells for 15 sec, and Stormstrike's cooldown has a 50% chance to reset each time you Dodge or Parry.","\"Удар бури\" с вероятностью 50% позволяет восстанавливать ману во время применения заклинаний со скоростью 50% от обычной в течение 15 сек. Когда вы уклоняетесь от атаки или парируете ее, \"Удар бури\" с вероятностью 50% мгновенно восстанавливается."],["When you Stormstrike, you have a 100% chance to gain 50% mana regeneration while casting spells for 15 sec, and Stormstrike's cooldown has a 100% chance to reset each time you Dodge or Parry.","\"Удар бури\" с вероятностью 100% позволяет восстанавливать ману во время применения заклинаний со скоростью 50% от обычной в течение 15 сек. Когда вы уклоняетесь от атаки или парируете ее, \"Удар бури\" с вероятностью 100% мгновенно восстанавливается."],["Maelstrom Weapon","Оружие Водоворота"],["When you deal damage with a melee attack, you have a chance to reduce the cast time and Mana cost of your next Lightning Bolt spell by 4%. Stacks up to 5 times. Lasts 30 sec.","Когда вы наносите урон в ближнем бою, с некоторой вероятностью время применения следующей \"Молнии\" и затраты маны на нее сокращаются на 4%. Эффект суммируется до 5 раз. Время действия – 30 сек."],["When you deal damage with a melee attack, you have a chance to reduce the cast time and Mana cost of your next Lightning Bolt spell by 8%. Stacks up to 5 times. Lasts 30 sec.","Когда вы наносите урон в ближнем бою, с некоторой вероятностью время применения следующей \"Молнии\" и затраты маны на нее сокращаются на 8%. Эффект суммируется до 5 раз. Время действия – 30 сек."],["When you deal damage with a melee attack, you have a chance to reduce the cast time and Mana cost of your next Lightning Bolt spell by 12%. Stacks up to 5 times. Lasts 30 sec.","Когда вы наносите урон в ближнем бою, с некоторой вероятностью время применения следующей \"Молнии\" и затраты маны на нее сокращаются на 12%. Эффект суммируется до 5 раз. Время действия – 30 сек."],["When you deal damage with a melee attack, you have a chance to reduce the cast time and Mana cost of your next Lightning Bolt spell by 16%. Stacks up to 5 times. Lasts 30 sec.","Когда вы наносите урон в ближнем бою, с некоторой вероятностью время применения следующей \"Молнии\" и затраты маны на нее сокращаются на 16%. Эффект суммируется до 5 раз. Время действия – 30 сек."],["When you deal damage with a melee attack, you have a chance to reduce the cast time and Mana cost of your next Lightning Bolt spell by 20%. Stacks up to 5 times. Lasts 30 sec.","Когда вы наносите урон в ближнем бою, с некоторой вероятностью время применения следующей \"Молнии\" и затраты маны на нее сокращаются на 20%. Эффект суммируется до 5 раз. Время действия – 30 сек."],["Rage of the Farseer","Ярость предсказателя"],["Increases your attack speed by 30% for 25 sec.","Increases your attack speed by 30% for 25 сек."],["Restoration","Исцеление"],["Improved Healing Wave","Улучшенная волна исцеления"],["Reduces the casting time of your Healing Wave spell by 0.1 sec.","Сокращает время применения \"Волны исцеления\" на 0.1 сек."],["Reduces the casting time of your Healing Wave spell by 0.2 sec.","Сокращает время применения \"Волны исцеления\" на 0.2 сек."],["Reduces the casting time of your Healing Wave spell by 0.3 sec.","Сокращает время применения \"Волны исцеления\" на 0.3 сек."],["Reduces the casting time of your Healing Wave spell by 0.4 sec.","Сокращает время применения \"Волны исцеления\" на 0.4 сек."],["Reduces the casting time of your Healing Wave spell by 0.5 sec.","Сокращает время применения \"Волны исцеления\" на 0.5 сек."],["Totemic Focus","Тотемное средоточие"],["Reduces the Mana cost of your totems and any spells that summon or move them by 5%.","Снижает затраты маны на создание тотемов, а также на заклинания их призыва и перемещения, на 5%."],["Reduces the Mana cost of your totems and any spells that summon or move them by 10%.","Снижает затраты маны на создание тотемов, а также на заклинания их призыва и перемещения, на 10%."],["Reduces the Mana cost of your totems and any spells that summon or move them by 15%.","Снижает затраты маны на создание тотемов, а также на заклинания их призыва и перемещения, на 15%."],["Reduces the Mana cost of your totems and any spells that summon or move them by 20%.","Снижает затраты маны на создание тотемов, а также на заклинания их призыва и перемещения, на 20%."],["Reduces the Mana cost of your totems and any spells that summon or move them by 25%.","Снижает затраты маны на создание тотемов, а также на заклинания их призыва и перемещения, на 25%."],["Mindfulness","Вдумчивость"],["Allows 17% of your Mana regeneration to continue while casting.","Во время применения заклинаний мана продолжает восполняться со скоростью 17%."],["Allows 33% of your Mana regeneration to continue while casting.","Во время применения заклинаний мана продолжает восполняться со скоростью 33%."],["Allows 50% of your Mana regeneration to continue while casting.","Во время применения заклинаний мана продолжает восполняться со скоростью 50%."],["Natural Grace","Природная ловкость"],["Reduces the threat generated by your spells by 5%.","Снижает уровень угрозы, создаваемой вашими заклинаниями, на 5%."],["Reduces the threat generated by your spells by 10%.","Снижает уровень угрозы, создаваемой вашими заклинаниями, на 10%."],["Reduces the threat generated by your spells by 15%.","Снижает уровень угрозы, создаваемой вашими заклинаниями, на 15%."],["Tidal Focus","Приливная концентрация"],["Reduces the Mana cost of your healing spells by 1% and improves your chance to hit by 1%.","Снижает затраты маны на применение исцеляющих заклинаний на 1% и повышает вероятность попадания на 1%."],["Reduces the Mana cost of your healing spells by 2% and improves your chance to hit by 2%.","Снижает затраты маны на применение исцеляющих заклинаний на 2% и повышает вероятность попадания на 2%."],["Reduces the Mana cost of your healing spells by 3% and improves your chance to hit by 3%.","Снижает затраты маны на применение исцеляющих заклинаний на 3% и повышает вероятность попадания на 3%."],["Reduces the Mana cost of your healing spells by 4% and improves your chance to hit by 4%.","Снижает затраты маны на применение исцеляющих заклинаний на 4% и повышает вероятность попадания на 4%."],["Reduces the Mana cost of your healing spells by 5% and improves your chance to hit by 5%.","Снижает затраты маны на применение исцеляющих заклинаний на 5% и повышает вероятность попадания на 5%."],["Improved Reincarnation","Улучшенное восстание из мертвых"],["Reduces the cooldown of your Reincarnation spell by 10 min, increases your maximum health by 2%, and increases the amount of health and Mana you reincarnate with by an additional 10%.","Сокращает время восстановления \"Перерождения\" на 10 мин. и увеличивает максимальный запас здоровья на 2%, а также увеличивает количество здоровья и маны после возрождения еще на 10%."],["Reduces the cooldown of your Reincarnation spell by 20 min, increases your maximum health by 4%, and increases the amount of health and Mana you reincarnate with by an additional 20%.","Сокращает время восстановления \"Перерождения\" на 20 мин. и увеличивает максимальный запас здоровья на 4%, а также увеличивает количество здоровья и маны после возрождения еще на 20%."],["Ancestral Healing","Исцеление предков"],["Increases your target's armor value by 8% for 15 sec after getting a critical effect from one of your healing spells.","Критические эффекты ваших исцеляющих заклинаний усиливают броню цели на 8% на 15 сек."],["Increases your target's armor value by 17% for 15 sec after getting a critical effect from one of your healing spells.","Критические эффекты ваших исцеляющих заклинаний усиливают броню цели на 17% на 15 сек."],["Increases your target's armor value by 25% for 15 sec after getting a critical effect from one of your healing spells.","Критические эффекты ваших исцеляющих заклинаний усиливают броню цели на 25% на 15 сек."],["Healing Focus","Средоточие исцеления"],["Gives you a 23% chance to avoid interruption caused by damage while casting any healing spell.","С вероятностью 23% позволяет избежать задержки при применении исцеляющих заклинаний, когда вы получаете урон."],["Gives you a 47% chance to avoid interruption caused by damage while casting any healing spell.","С вероятностью 47% позволяет избежать задержки при применении исцеляющих заклинаний, когда вы получаете урон."],["Gives you a 70% chance to avoid interruption caused by damage while casting any healing spell.","С вероятностью 70% позволяет избежать задержки при применении исцеляющих заклинаний, когда вы получаете урон."],["Water Shield","Водный щит"],["The caster is surrounded by 3 globes of water. When a spell, melee, or ranged attack hits the caster or when one of the caster's healing spells gets a critical result, 2% of maximum mana is restored to the caster, expending one water globe. Only one globe will activate every few seconds. Lasts 10 min. Only one Elemental Shield can be active on the Shaman at any one time.","Создает щит из 3 водяных сфер. Каждый раз, когда вы получаете удар в ближнем или дальнем бою, когда вас поражает заклинание или срабатывает критический эффект вашего исцеляющего заклинания, щит восполняет 2% максимального запаса маны, теряя одну сферу. Срабатывает не чаще раза в несколько секунд. Время действия – 10 мин. Вас может защищать только одно заклинание категории \"Щит стихий\" одновременно."],["Tidal Mastery","Мастерство владения приливами"],["Increases the critical effect chance of your healing spells by 1%.","Повышает вероятность критического эффекта исцеляющих заклинаний на 1%."],["Increases the critical effect chance of your healing spells by 2%.","Повышает вероятность критического эффекта исцеляющих заклинаний на 2%."],["Increases the critical effect chance of your healing spells by 3%.","Повышает вероятность критического эффекта исцеляющих заклинаний на 3%."],["Increases the critical effect chance of your healing spells by 4%.","Повышает вероятность критического эффекта исцеляющих заклинаний на 4%."],["Increases the critical effect chance of your healing spells by 5%.","Повышает вероятность критического эффекта исцеляющих заклинаний на 5%."],["Restorative Totems","Восстанавливающий тотем"],["Increases the effect of your Mana Spring Totem by 5% and increases the effect of your Healing Stream Totem by 10%.","Повышает эффективность тотема источника маны на 5%, а тотема исцеляющего потока – на 10%."],["Increases the effect of your Mana Spring Totem by 10% and increases the effect of your Healing Stream Totem by 20%.","Повышает эффективность тотема источника маны на 10%, а тотема исцеляющего потока – на 20%."],["Increases the effect of your Mana Spring Totem by 15% and increases the effect of your Healing Stream Totem by 30%.","Повышает эффективность тотема источника маны на 15%, а тотема исцеляющего потока – на 30%."],["Increases the effect of your Mana Spring Totem by 20% and increases the effect of your Healing Stream Totem by 40%.","Повышает эффективность тотема источника маны на 20%, а тотема исцеляющего потока – на 40%."],["Increases the effect of your Mana Spring Totem by 25% and increases the effect of your Healing Stream Totem by 50%.","Повышает эффективность тотема источника маны на 25%, а тотема исцеляющего потока – на 50%."],["Mana Tide Totem","Тотем прилива маны"],["Summons a Mana Tide Totem with 5 health at the feet of the caster for 12 sec that restores 88 mana every 3 seconds to group members within 30 yards.","Создание рядом с заклинателем тотема прилива маны прочностью 5 ед., который в течение 12 сек. раз в 3 сек. восполняет 88 ед. маны всем участникам группы в радиусе 30 м."],["Healing Way","Путь исцеления"],["Increases the amount healed by your Healing Wave spell by 8%.","\"Волна исцеления\" восполняет на 8% больше здоровья."],["Increases the amount healed by your Healing Wave spell by 17%.","\"Волна исцеления\" восполняет на 17% больше здоровья."],["Increases the amount healed by your Healing Wave spell by 25%.","\"Волна исцеления\" восполняет на 25% больше здоровья."],["Nature's Swiftness","Природная стремительность"],["When activated, your next Nature spell with a casting time less than 10 sec. becomes an instant cast spell.","Мгновенное применение следующего заклинания сил природы, обычное время применения которого ниже 10 сек."],["Purification","Чистота"],["Increases the effectiveness of your healing spells by 2%.","Повышает эффективность ваших исцеляющих заклинаний на 2%."],["Increases the effectiveness of your healing spells by 4%.","Повышает эффективность ваших исцеляющих заклинаний на 4%."],["Increases the effectiveness of your healing spells by 6%.","Повышает эффективность ваших исцеляющих заклинаний на 6%."],["Increases the effectiveness of your healing spells by 8%.","Повышает эффективность ваших исцеляющих заклинаний на 8%."],["Increases the effectiveness of your healing spells by 10%.","Повышает эффективность ваших исцеляющих заклинаний на 10%."],["Riptide","Быстрина"],["Heals a friendly target for 480, an additional 445 over 15 sec, and increases the effectiveness of your Chain Heal casts directly on that target by 25%.","Восстанавливает союзнику 480 ед. здоровья сразу и еще 445 ед. здоровья за 15 сек. Повышает эффективность \"Цепного исцеления\", применяемого напрямую к этой цели, на 25%."]]},"mage":{"build":"1.60.1.70009","className":"Mage","pairs":[["Mage","Маг"],["Arcane","Тайная магия"],["Wand Specialization","Специализация на жезлах"],["Increases your damage with Wands by 13%.","Увеличение на 13% урона, наносимого при использовании магических жезлов."],["Increases your damage with Wands by 25%.","Увеличение на 25% урона, наносимого при использовании магических жезлов."],["Arcane Focus","Средоточие чар"],["Improves your chance to hit with Arcane spells by 1%.","Повышает вероятность попадания заклинаниями тайной магии на 1%."],["Improves your chance to hit with Arcane spells by 2%.","Повышает вероятность попадания заклинаниями тайной магии на 2%."],["Improves your chance to hit with Arcane spells by 3%.","Повышает вероятность попадания заклинаниями тайной магии на 3%."],["Improves your chance to hit with Arcane spells by 4%.","Повышает вероятность попадания заклинаниями тайной магии на 4%."],["Improves your chance to hit with Arcane spells by 5%.","Повышает вероятность попадания заклинаниями тайной магии на 5%."],["Improved Channeling","Улучшенное поддержание"],["Gives you a 20% chance to avoid interruption caused by damage while channeling Arcane Missiles and a 14% chance while casting Arcane Blast.","С вероятностью 20% поддержание \"Чародейских стрел\" не прерывается при получении урона. С вероятностью 14% применение \"Чародейской вспышки\" не прерывается при получении урона."],["Gives you a 40% chance to avoid interruption caused by damage while channeling Arcane Missiles and a 28% chance while casting Arcane Blast.","С вероятностью 40% поддержание \"Чародейских стрел\" не прерывается при получении урона. С вероятностью 28% применение \"Чародейской вспышки\" не прерывается при получении урона."],["Gives you a 60% chance to avoid interruption caused by damage while channeling Arcane Missiles and a 42% chance while casting Arcane Blast.","С вероятностью 60% поддержание \"Чародейских стрел\" не прерывается при получении урона. С вероятностью 42% применение \"Чародейской вспышки\" не прерывается при получении урона."],["Gives you a 80% chance to avoid interruption caused by damage while channeling Arcane Missiles and a 56% chance while casting Arcane Blast.","С вероятностью 80% поддержание \"Чародейских стрел\" не прерывается при получении урона. С вероятностью 56% применение \"Чародейской вспышки\" не прерывается при получении урона."],["Gives you a 100% chance to avoid interruption caused by damage while channeling Arcane Missiles and a 70% chance while casting Arcane Blast.","С вероятностью 100% поддержание \"Чародейских стрел\" не прерывается при получении урона. С вероятностью 70% применение \"Чародейской вспышки\" не прерывается при получении урона."],["Arcane Subtlety","Искусные чары"],["Reduces your target's resistance to all your spells by 8 and reduces the threat caused by your Arcane spells by 15%.","Снижение сопротивления цели всем вашим заклинаниям на 8 ед. и снижение угрозы от заклинаний тайной магии на 15%."],["Reduces your target's resistance to all your spells by 15 and reduces the threat caused by your Arcane spells by 30%.","Снижение сопротивления цели всем вашим заклинаниям на 15 ед. и снижение угрозы от заклинаний тайной магии на 30%."],["Magic Absorption","Магическое поглощение"],["Increases all your resistances by 5 and causes all spells you fully resist to restore 1% of your total mana. Cannot trigger more often than 1 time per sec.","Повышает сопротивление всем видам магии на 5. Когда сопротивление полностью предотвращает эффект заклинания, вы восполняете 1% максимального запаса маны. Эффект срабатывает не чаще раза в сек."],["Increases all your resistances by 10 and causes all spells you fully resist to restore 2% of your total mana. Cannot trigger more often than 1 time per sec.","Повышает сопротивление всем видам магии на 10. Когда сопротивление полностью предотвращает эффект заклинания, вы восполняете 2% максимального запаса маны. Эффект срабатывает не чаще раза в сек."],["Arcane Concentration","Чародейская сосредоточенность"],["Gives you a 2% chance of entering a Clearcasting state after any damage spell hits a target. The Clearcasting state reduces the mana cost of your next damage spell by $/10;12536s1%.","Когда ваше заклинание наносит урон противнику, вы с вероятностью 2% переходите в состояние \"Ясность мысли\". \"Ясность мысли\" снижает затраты маны на следующее наносящее урон заклинание на $/10;12536s1%."],["Gives you a 4% chance of entering a Clearcasting state after any damage spell hits a target. The Clearcasting state reduces the mana cost of your next damage spell by $/10;12536s1%.","Когда ваше заклинание наносит урон противнику, вы с вероятностью 4% переходите в состояние \"Ясность мысли\". \"Ясность мысли\" снижает затраты маны на следующее наносящее урон заклинание на $/10;12536s1%."],["Gives you a 6% chance of entering a Clearcasting state after any damage spell hits a target. The Clearcasting state reduces the mana cost of your next damage spell by $/10;12536s1%.","Когда ваше заклинание наносит урон противнику, вы с вероятностью 6% переходите в состояние \"Ясность мысли\". \"Ясность мысли\" снижает затраты маны на следующее наносящее урон заклинание на $/10;12536s1%."],["Gives you a 8% chance of entering a Clearcasting state after any damage spell hits a target. The Clearcasting state reduces the mana cost of your next damage spell by $/10;12536s1%.","Когда ваше заклинание наносит урон противнику, вы с вероятностью 8% переходите в состояние \"Ясность мысли\". \"Ясность мысли\" снижает затраты маны на следующее наносящее урон заклинание на $/10;12536s1%."],["Gives you a 10% chance of entering a Clearcasting state after any damage spell hits a target. The Clearcasting state reduces the mana cost of your next damage spell by $/10;12536s1%.","Когда ваше заклинание наносит урон противнику, вы с вероятностью 10% переходите в состояние \"Ясность мысли\". \"Ясность мысли\" снижает затраты маны на следующее наносящее урон заклинание на $/10;12536s1%."],["Arcane Resilience","Чародейская стойкость"],["Increases your Armor by an amount equal to 25% of your Intellect.","Увеличивает показатель брони на 25% интеллекта."],["Increases your Armor by an amount equal to 50% of your Intellect.","Увеличивает показатель брони на 50% интеллекта."],["Arcane Geometry","Чародейская геометрия"],["Increases the range of your Arcane spells by 3 yards.","Увеличивает дальность действия заклинаний тайной магии на 3 м."],["Increases the range of your Arcane spells by 6 yards.","Увеличивает дальность действия заклинаний тайной магии на 6 м."],["Arcane Impact","Магическое действие"],["Increases the critical strike chance of your Arcane spells by 2%.","Повышает вероятность критического удара заклинаний тайной магии на 2%."],["Increases the critical strike chance of your Arcane spells by 4%.","Повышает вероятность критического удара заклинаний тайной магии на 4%."],["Increases the critical strike chance of your Arcane spells by 6%.","Повышает вероятность критического удара заклинаний тайной магии на 6%."],["Arcane Blast","Чародейская вспышка"],["Blasts the target with energy, dealing 54 Arcane damage. Each time you cast Arcane Blast, the damage of all your other spells is increased by 10% and the mana cost of Arcane Blast is increased by 175%. Effect stacks up to 4 times and lasts 8 sec or until any other damage spell is cast.","Поражает противника зарядом энергии, наносящим 54 ед. урона от тайной магии. Каждый раз, когда вы применяете \"Чародейскую вспышку\", урон от всех остальных заклинаний увеличивается на 10%, но стоимость \"Чародейской вспышки\" повышается на 175%. Суммируется до 4 раз. Время действия – 8 сек. или до тех пор, пока вы не примените другое наносящее урон заклинание."],["Arcane Shielding","Чародейская защита"],["Decreases the Mana lost per point of damage taken when your Mana Shield spell is active by 17% and increases the resistances granted by your Mage Armor spell by 25%.","Снижает потери маны при получении урона под действием \"Щита маны\" на 17% и увеличивает бонус к сопротивлению от \"Магического доспеха\" на 25%."],["Decreases the Mana lost per point of damage taken when your Mana Shield spell is active by 33% and increases the resistances granted by your Mage Armor spell by 50%.","Снижает потери маны при получении урона под действием \"Щита маны\" на 33% и увеличивает бонус к сопротивлению от \"Магического доспеха\" на 50%."],["Improved Counterspell","Улучшенная Антимагия"],["Your Counterspell also Silences the target for 2 sec.","\"Антимагия\" также поражает цель немотой на 2 сек."],["Your Counterspell also Silences the target for 4 sec.","\"Антимагия\" также поражает цель немотой на 4 сек."],["Arcane Meditation","Чародейская медитация"],["Allows 17% of your Mana regeneration to continue while casting.","В процессе применения заклинаний продолжается 17% от восполнения маны."],["Allows 33% of your Mana regeneration to continue while casting.","В процессе применения заклинаний продолжается 33% от восполнения маны."],["Allows 50% of your Mana regeneration to continue while casting.","В процессе применения заклинаний продолжается 50% от восполнения маны."],["Missile Barrage","Заградительные стрелы"],["Gives your Arcane Blast spell a 40% chance, and your Fireball, Frostbolt, and Frostfire Bolt spells a 20% chance to reduce the channeled duration of your next Arcane Missiles spell by 50%, reduce the Mana cost by 100%, and missiles fire every 0.5 sec.","\"Чародейская вспышка\" с вероятностью 40%, а \"Огненный шар\", \"Ледяная стрела\" и \"Стрела ледяного огня\" – с вероятностью 20% усиливают следующие \"Чародейские стрелы\". При этом время поддержания \"Чародейских стрел\" сокращается на 50%, затраты маны снижаются на 100%, и вы выпускаете стрелы раз в 0.5 сек."],["Presence of Mind","Присутствие разума"],["When activated, your next Mage spell with a casting time less than 10 sec becomes an instant cast spell.","Мгновенное применение следующего магического заклинания, обычное время применения которого ниже 10 сек."],["Arcane Mind","Чародейский ум"],["Increases your Intellect by 2% and increases the critical strike damage bonus of your Arcane spells by 20%.","Повышает интеллект на 2% и увеличивает критический урон от заклинаний тайной магии на 20%."],["Increases your Intellect by 4% and increases the critical strike damage bonus of your Arcane spells by 40%.","Повышает интеллект на 4% и увеличивает критический урон от заклинаний тайной магии на 40%."],["Increases your Intellect by 6% and increases the critical strike damage bonus of your Arcane spells by 60%.","Повышает интеллект на 6% и увеличивает критический урон от заклинаний тайной магии на 60%."],["Increases your Intellect by 8% and increases the critical strike damage bonus of your Arcane spells by 80%.","Повышает интеллект на 8% и увеличивает критический урон от заклинаний тайной магии на 80%."],["Increases your Intellect by 10% and increases the critical strike damage bonus of your Arcane spells by 100%.","Повышает интеллект на 10% и увеличивает критический урон от заклинаний тайной магии на 100%."],["Arcane Instability","Магическая нестабильность"],["Increases the damage done by your spells by 1% and your critical strike chance by 1%.","Увеличивает урон от заклинаний на 1% и повышает вероятность критического удара на 1%."],["Increases the damage done by your spells by 2% and your critical strike chance by 2%.","Увеличивает урон от заклинаний на 2% и повышает вероятность критического удара на 2%."],["Increases the damage done by your spells by 3% and your critical strike chance by 3%.","Увеличивает урон от заклинаний на 3% и повышает вероятность критического удара на 3%."],["Arcane Power","Мощь тайной магии"],["For the next 15 sec, your spells deal 30% more damage while costing 30% more mana to cast.","В течение 15 сек. заклинания наносят на 30% больше урона, но расходуют на 30% больше маны."],["Fire","Огонь"],["Wake of Fire","Огненный след"],["Reduces the cooldown of your Fire Blast spell by 1 sec. Killing a non-trivial target increases the critical strike chance of your next Fire Blast cast within 30 sec by 25%.","Сокращает время восстановления \"Огненного взрыва\" на 1 сек. Когда вы убиваете цель, за которую получаете опыт или честь, вероятность критического удара следующего \"Огненного взрыва\" повышается на 25% на 30 сек."],["Reduces the cooldown of your Fire Blast spell by 2 sec. Killing a non-trivial target increases the critical strike chance of your next Fire Blast cast within 30 sec by 50%.","Сокращает время восстановления \"Огненного взрыва\" на 2 сек. Когда вы убиваете цель, за которую получаете опыт или честь, вероятность критического удара следующего \"Огненного взрыва\" повышается на 50% на 30 сек."],["Incineration","Испепеление"],["Increases the critical strike chance of your Fire Blast, Ice Lance, Arcane Blast, and Scorch spells by 2%.","Повышает вероятность критического удара \"Огненного взрыва\", \"Ледяного копья\", \"Чародейской вспышки\" и \"Ожога\" на 2%."],["Increases the critical strike chance of your Fire Blast, Ice Lance, Arcane Blast, and Scorch spells by 4%.","Повышает вероятность критического удара \"Огненного взрыва\", \"Ледяного копья\", \"Чародейской вспышки\" и \"Ожога\" на 4%."],["Increases the critical strike chance of your Fire Blast, Ice Lance, Arcane Blast, and Scorch spells by 6%.","Повышает вероятность критического удара \"Огненного взрыва\", \"Ледяного копья\", \"Чародейской вспышки\" и \"Ожога\" на 6%."],["Improved Fireball","Улучшенный огненный шар"],["Reduces the casting time of your Fireball and Frostfire Bolt spells by 0.1 sec.","Сокращает время применения \"Огненного шара\" и \"Стрелы ледяного огня\" на 0.1 сек."],["Reduces the casting time of your Fireball and Frostfire Bolt spells by 0.2 sec.","Сокращает время применения \"Огненного шара\" и \"Стрелы ледяного огня\" на 0.2 сек."],["Reduces the casting time of your Fireball and Frostfire Bolt spells by 0.3 sec.","Сокращает время применения \"Огненного шара\" и \"Стрелы ледяного огня\" на 0.3 сек."],["Reduces the casting time of your Fireball and Frostfire Bolt spells by 0.4 sec.","Сокращает время применения \"Огненного шара\" и \"Стрелы ледяного огня\" на 0.4 сек."],["Reduces the casting time of your Fireball and Frostfire Bolt spells by 0.5 sec.","Сокращает время применения \"Огненного шара\" и \"Стрелы ледяного огня\" на 0.5 сек."],["Ignite","Воспламенение"],["Your critical strikes from Fire damage spells cause the target to burn for an additional 8% of your spell's damage over 4 sec.","Критические эффекты заклинаний огня поджигают цель, нанося еще 8% урона от примененного заклинания за 4 сек."],["Your critical strikes from Fire damage spells cause the target to burn for an additional 16% of your spell's damage over 4 sec.","Критические эффекты заклинаний огня поджигают цель, нанося еще 16% урона от примененного заклинания за 4 сек."],["Your critical strikes from Fire damage spells cause the target to burn for an additional 24% of your spell's damage over 4 sec.","Критические эффекты заклинаний огня поджигают цель, нанося еще 24% урона от примененного заклинания за 4 сек."],["Your critical strikes from Fire damage spells cause the target to burn for an additional 32% of your spell's damage over 4 sec.","Критические эффекты заклинаний огня поджигают цель, нанося еще 32% урона от примененного заклинания за 4 сек."],["Your critical strikes from Fire damage spells cause the target to burn for an additional 40% of your spell's damage over 4 sec.","Критические эффекты заклинаний огня поджигают цель, нанося еще 40% урона от примененного заклинания за 4 сек."],["Flame Throwing","Метание пламени"],["Increases the range of your Fire spells by 3 yards.","Увеличивает дальность применения ваших заклинаний огня на 3 метра."],["Increases the range of your Fire spells by 6 yards.","Увеличивает дальность применения ваших заклинаний огня на 6 метров."],["Impact","Сотрясение"],["Gives your Fire spells a 3% chance to stun the target for 2 sec.","Заклинания огня с вероятностью 3% оглушают цель на 2 сек."],["Gives your Fire spells a 7% chance to stun the target for 2 sec.","Заклинания огня с вероятностью 7% оглушают цель на 2 сек."],["Gives your Fire spells a 10% chance to stun the target for 2 sec.","Заклинания огня с вероятностью 10% оглушают цель на 2 сек."],["Burning Soul","Пылающая душа"],["Gives your Fire spells a 23% chance to not lose casting time when you take damage and reduces the threat caused by your Fire spells by 10%.","Прочтение заклинаний огня не будет замедлено при получении урона с вероятностью 23%. Угроза от ваших заклинаний огня уменьшается на 10%."],["Gives your Fire spells a 47% chance to not lose casting time when you take damage and reduces the threat caused by your Fire spells by 20%.","Прочтение заклинаний огня не будет замедлено при получении урона с вероятностью 47%. Угроза от ваших заклинаний огня уменьшается на 20%."],["Gives your Fire spells a 70% chance to not lose casting time when you take damage and reduces the threat caused by your Fire spells by 30%.","Прочтение заклинаний огня не будет замедлено при получении урона с вероятностью 70%. Угроза от ваших заклинаний огня уменьшается на 30%."],["Improved Flamestrike","Улучшенный огненный столб"],["Increases the critical strike chance of your Flamestrike spell by 5%.","Повышает вероятность критического удара при применении \"Огненного столба\" на 5%."],["Increases the critical strike chance of your Flamestrike spell by 10%.","Повышает вероятность критического удара при применении \"Огненного столба\" на 10%."],["Increases the critical strike chance of your Flamestrike spell by 15%.","Повышает вероятность критического удара при применении \"Огненного столба\" на 15%."],["Pyroblast","Огненная глыба"],["Hurls an immense fiery boulder that causes 110 Fire damage and an additional 44 Fire damage over 12 sec.","Бросок огромной огненной глыбы, которая наносит 110 ед. урона от огня единовременно и 44 ед. урона от огня в течение 12 сек."],["Improved Scorch","Улучшенный ожог"],["Your Scorch spell has a 33% chance to cause your target to be vulnerable to Fire damage. This vulnerability increases all Fire damage you deal to your target by 3% and lasts 30 sec, stacking up to 5 times.","\"Ожог\" с вероятностью 33% делает цель уязвимой к огню, в результате чего вы наносите этой цели на 3% больше урона от огня. Время действия – 30 сек. Суммируется до 5 раз."],["Your Scorch spell has a 67% chance to cause your target to be vulnerable to Fire damage. This vulnerability increases all Fire damage you deal to your target by 3% and lasts 30 sec, stacking up to 5 times.","\"Ожог\" с вероятностью 67% делает цель уязвимой к огню, в результате чего вы наносите этой цели на 3% больше урона от огня. Время действия – 30 сек. Суммируется до 5 раз."],["Your Scorch spell has a 100% chance to cause your target to be vulnerable to Fire damage. This vulnerability increases all Fire damage you deal to your target by 3% and lasts 30 sec, stacking up to 5 times.","\"Ожог\" с вероятностью 100% делает цель уязвимой к огню, в результате чего вы наносите этой цели на 3% больше урона от огня. Время действия – 30 сек. Суммируется до 5 раз."],["Improved Fire Ward","Улучшенная защита от огня"],["Causes your Fire Ward to have a 10% chance to reflect Fire spells while active.","Защита от огня с вероятностью 10% отражает заклинания школы огня."],["Causes your Fire Ward to have a 20% chance to reflect Fire spells while active.","Защита от огня с вероятностью 20% отражает заклинания школы огня."],["Hot Streak","Полоса везения"],["Your non-periodic critical strikes with Fireball, Frostfire Bolt, Fire Blast, and Scorch grant Hot Streak for 20 sec. Hot Streak reduces the cast time of Pyroblast by 25%, stacking up to 3 times.","Когда \"Огненный шар\", \"Стрела ледяного огня\", \"Огненный взрыв\" и \"Ожог\" наносят прямой критический урон, вы получаете эффект \"Полоса везения\" на 20 сек. \"Полоса везения\" сокращает время применения \"Огненной глыбы\" на 25% и суммируется до 3 раз."],["Master of Elements","Повелитель Стихий"],["Your Fire and Frost critical strikes will refund 10% of their base mana cost.","Критические удары заклинаний огня и магии льда восполняют ману в объеме 10% их базовой стоимости."],["Your Fire and Frost critical strikes will refund 20% of their base mana cost.","Критические удары заклинаний огня и магии льда восполняют ману в объеме 20% их базовой стоимости."],["Your Fire and Frost critical strikes will refund 30% of their base mana cost.","Критические удары заклинаний огня и магии льда восполняют ману в объеме 30% их базовой стоимости."],["Critical Mass","Критическая масса"],["Increases the critical strike chance of your Fire spells by 2%.","Повышает вероятность критического удара при применении заклинаний огня на 2%."],["Increases the critical strike chance of your Fire spells by 4%.","Повышает вероятность критического удара при применении заклинаний огня на 4%."],["Increases the critical strike chance of your Fire spells by 6%.","Повышает вероятность критического удара при применении заклинаний огня на 6%."],["Blast Wave","Взрывная волна"],["A wave of flame radiates outward from the caster, damaging all enemies caught within the blast for 163 Fire damage, and Dazing them for 50% reduced movement speed for 6 sec.","Выпускает волну пламени, наносящую пораженным противникам 163 ед. урона от огня и вызывающую головокружение, которое снижает скорость передвижения на 50% на 6 сек."],["Fire Power","Сила огня"],["Increases the damage done by your Fire spells by 2%.","Увеличивает урон от ваших заклинаний огня на 2%."],["Increases the damage done by your Fire spells by 4%.","Увеличивает урон от ваших заклинаний огня на 4%."],["Increases the damage done by your Fire spells by 6%.","Увеличивает урон от ваших заклинаний огня на 6%."],["Increases the damage done by your Fire spells by 8%.","Увеличивает урон от ваших заклинаний огня на 8%."],["Increases the damage done by your Fire spells by 10%.","Увеличивает урон от ваших заклинаний огня на 10%."],["Combustion","Возгорание"],["When activated, this spell causes each of your Fire damage spell hits to increase your critical strike chance with Fire damage spells by 10%. This effect lasts until you have caused 4 non-periodic critical strikes with Fire spells.","После активации ваши наносящие урон заклинания огня, попавшие в цель, повышают вероятность критического удара заклинаний огня на 10%. Этот эффект длится, пока ваши заклинания огня прямого действия не нанесут критический урон 4 раза."],["Frost","Лед"],["Frost Warding","Защита от льда"],["Increases the Armor and resistance given by your Frost Armor and Ice Armor spells by 15%. In addition, gives your Frost Ward a 10% chance to reflect Frost spells and effects while active.","Бонусы к броне и сопротивлению от \"Морозного доспеха\" и \"Ледяного доспеха\" увеличиваются на 15%. Кроме того, \"Защита от магии льда\" с вероятностью 10% отражает заклинания и эффекты магии льда."],["Increases the Armor and resistance given by your Frost Armor and Ice Armor spells by 30%. In addition, gives your Frost Ward a 20% chance to reflect Frost spells and effects while active.","Бонусы к броне и сопротивлению от \"Морозного доспеха\" и \"Ледяного доспеха\" увеличиваются на 30%. Кроме того, \"Защита от магии льда\" с вероятностью 20% отражает заклинания и эффекты магии льда."],["Improved Frostbolt","Улучшенная ледяная стрела"],["Reduces the casting time of your Frostbolt spell by 0.1 sec.","Сокращает время применения \"Ледяной стрелы\" на 0.1 сек."],["Reduces the casting time of your Frostbolt spell by 0.2 sec.","Сокращает время применения \"Ледяной стрелы\" на 0.2 сек."],["Reduces the casting time of your Frostbolt spell by 0.3 sec.","Сокращает время применения \"Ледяной стрелы\" на 0.3 сек."],["Reduces the casting time of your Frostbolt spell by 0.4 sec.","Сокращает время применения \"Ледяной стрелы\" на 0.4 сек."],["Reduces the casting time of your Frostbolt spell by 0.5 sec.","Сокращает время применения \"Ледяной стрелы\" на 0.5 сек."],["Elemental Precision","Точность стихии"],["Improves your chance to hit with Frost and Fire spells by 1%.","Повышает вероятность критического удара заклинаний магии льда и огня на 1%."],["Improves your chance to hit with Frost and Fire spells by 2%.","Повышает вероятность критического удара заклинаний магии льда и огня на 2%."],["Improves your chance to hit with Frost and Fire spells by 3%.","Повышает вероятность критического удара заклинаний магии льда и огня на 3%."],["Improves your chance to hit with Frost and Fire spells by 4%.","Повышает вероятность критического удара заклинаний магии льда и огня на 4%."],["Improves your chance to hit with Frost and Fire spells by 5%.","Повышает вероятность критического удара заклинаний магии льда и огня на 5%."],["Ice Shards","Ледяные осколки"],["Increases the critical strike damage bonus of your Frost spells by 20%.","Увеличение урона от критического поражения вашими заклинаниями льда на 20%."],["Increases the critical strike damage bonus of your Frost spells by 40%.","Увеличение урона от критического поражения вашими заклинаниями льда на 40%."],["Increases the critical strike damage bonus of your Frost spells by 60%.","Увеличение урона от критического поражения вашими заклинаниями льда на 60%."],["Increases the critical strike damage bonus of your Frost spells by 80%.","Увеличение урона от критического поражения вашими заклинаниями льда на 80%."],["Increases the critical strike damage bonus of your Frost spells by 100%.","Увеличение урона от критического поражения вашими заклинаниями льда на 100%."],["Permafrost","Вечная мерзлота"],["Increases the duration of your Chill effects by 11% and reduces the target's speed by an additional 3%.","Продлевает время действия ваших эффектов окоченения на 11%, и эти эффекты снижают скорость передвижения еще на 3%."],["Increases the duration of your Chill effects by 22% and reduces the target's speed by an additional 7%.","Продлевает время действия ваших эффектов окоченения на 22%, и эти эффекты снижают скорость передвижения еще на 7%."],["Increases the duration of your Chill effects by 33% and reduces the target's speed by an additional 10%.","Продлевает время действия ваших эффектов окоченения на 33%, и эти эффекты снижают скорость передвижения еще на 10%."],["Improved Frost Nova","Улучшенное кольцо льда"],["Reduces the cooldown of your Frost Nova spell by 2 sec.","Уменьшает время восстановления \"Кольца льда\" на 2 сек."],["Reduces the cooldown of your Frost Nova spell by 4 sec.","Уменьшает время восстановления \"Кольца льда\" на 4 сек."],["Frostbite","Обморожение"],["Gives your Chill effects a 5% chance to Freeze the target for 5 sec.","Ваши эффекты окоченения с вероятностью 5% замораживают цель на 5 сек."],["Gives your Chill effects a 10% chance to Freeze the target for 5 sec.","Ваши эффекты окоченения с вероятностью 10% замораживают цель на 5 сек."],["Gives your Chill effects a 15% chance to Freeze the target for 5 sec.","Ваши эффекты окоченения с вероятностью 15% замораживают цель на 5 сек."],["Piercing Ice","Пронзающий лед"],["Increases the damage done by your Frost spells by 2%.","Увеличение урона, наносимого вашими ледяными заклинаниями на 2%."],["Increases the damage done by your Frost spells by 4%.","Увеличение урона, наносимого вашими ледяными заклинаниями на 4%."],["Increases the damage done by your Frost spells by 6%.","Увеличение урона, наносимого вашими ледяными заклинаниями на 6%."],["Frost Channeling","Направленная сила льда"],["Reduces the mana cost of your Frost spells by 5% and reduces the threat caused by your Frost spells by 10%.","Снижение расхода маны на заклинания магии льда на 5% и снижение угрозы от них на 10%."],["Reduces the mana cost of your Frost spells by 10% and reduces the threat caused by your Frost spells by 20%.","Снижение расхода маны на заклинания магии льда на 10% и снижение угрозы от них на 20%."],["Reduces the mana cost of your Frost spells by 15% and reduces the threat caused by your Frost spells by 30%.","Снижение расхода маны на заклинания магии льда на 15% и снижение угрозы от них на 30%."],["Ice Lance","Ледяное копье"],["Deals 28 Frost damage to an enemy target. Deals 300% increased damage to Frozen targets.","Наносит 28 ед. урона от магии льда. Если цель заморожена, урон увеличивается на 300%."],["Improved Blizzard","Улучшенная снежная буря"],["Adds a Chill effect to your Blizzard spell. This effect lowers the target's movement speed by 15% for 1.5 sec.","\"Снежная буря\" также применяет эффект окоченения, снижающий скорость передвижения цели на 15% на 1.5 сек."],["Adds a Chill effect to your Blizzard spell. This effect lowers the target's movement speed by 25% for 1.5 sec.","\"Снежная буря\" также применяет эффект окоченения, снижающий скорость передвижения цели на 25% на 1.5 сек."],["Adds a Chill effect to your Blizzard spell. This effect lowers the target's movement speed by 40% for 1.5 sec.","\"Снежная буря\" также применяет эффект окоченения, снижающий скорость передвижения цели на 40% на 1.5 сек."],["Arctic Reach","Предел льда"],["Increases the range of your Frostbolt and Blizzard spells and the radius of your Frost Nova and Cone of Cold spells by 10%.","Увеличивает дальность действия \"Ледяной стрелы\" и \"Снежной бури\", а также радиус действия \"Кольца льда\" и \"Конуса холода\" на 10%."],["Increases the range of your Frostbolt and Blizzard spells and the radius of your Frost Nova and Cone of Cold spells by 20%.","Увеличивает дальность действия \"Ледяной стрелы\" и \"Снежной бури\", а также радиус действия \"Кольца льда\" и \"Конуса холода\" на 20%."],["Ice Block","Ледяная глыба"],["You become encased in a block of ice, protecting you from all physical attacks and spells for 10 sec, but during that time you cannot attack, move, or cast spells.","Заключает вас в ледяную глыбу, которая защищает от атак и заклинаний в течение 10 сек., но в это время вы не можете атаковать, двигаться и применять заклинания."],["Shatter","Обледенение"],["Increases the critical strike chance of all your spells against Frozen targets by 17%.","Повышает вероятность критического удара заклинаний против замороженных целей на 17%."],["Increases the critical strike chance of all your spells against Frozen targets by 33%.","Повышает вероятность критического удара заклинаний против замороженных целей на 33%."],["Increases the critical strike chance of all your spells against Frozen targets by 50%.","Повышает вероятность критического удара заклинаний против замороженных целей на 50%."],["Improved Cone of Cold","Улучшенный конус холода"],["Increases the damage dealt by your Cone of Cold spell by 12%.","Увеличение урона, нанесенного заклинанием \"Конус холода\", на 12%."],["Increases the damage dealt by your Cone of Cold spell by 23%.","Увеличение урона, нанесенного заклинанием \"Конус холода\", на 23%."],["Increases the damage dealt by your Cone of Cold spell by 35%.","Увеличение урона, нанесенного заклинанием \"Конус холода\", на 35%."],["Cold Snap","Холодная хватка"],["Finishes the remaining cooldown on all your other Frost spells.","Мгновенно восстанавливает все остальные заклинания магии льда."],["Fingers of Frost","Ледяные пальцы"],["Gives your Chill effects a 15% chance to grant you the Fingers of Frost effect, which treats your next 1 spell cast as if the target were Frozen. Lasts 15 sec.","\"Применяя эффекты окоченения, вы с вероятностью 15% получаете эффект \"Ледяные пальцы\", усиливающий 1 ваше следующее заклинание. Заклинания, усиленные \"Ледяными пальцами\", срабатывают так, словно цель заморожена. Время действия – 15 сек.\""],["Gives your Chill effects a 15% chance to grant you the Fingers of Frost effect, which treats your next 2 spells cast as if the target were Frozen. Lasts 15 sec.","\"Применяя эффекты окоченения, вы с вероятностью 15% получаете эффект \"Ледяные пальцы\", усиливающий 2 ваших следующих заклинания. Заклинания, усиленные \"Ледяными пальцами\", срабатывают так, словно цель заморожена. Время действия – 15 сек.\""],["Winter's Chill","Зимняя стужа"],["Gives your Frost damage spells a 20% chance to apply the Winter's Chill effect, which increases the chance your Ice Lance and Frostbolt spells will critically hit the target by 2% for 15 sec. Stacks up to 1 times.","Заклинания магии льда с вероятностью 20% применяют эффект \"Зимняя стужа\", повышающий вероятность критического удара \"Ледяного копья\" и \"Ледяной стрелы\" против пораженной цели на 2%. Время действия – 15 сек. Суммируется до 1 раз."],["Gives your Frost damage spells a 40% chance to apply the Winter's Chill effect, which increases the chance your Ice Lance and Frostbolt spells will critically hit the target by 2% for 15 sec. Stacks up to 2 times.","Заклинания магии льда с вероятностью 40% применяют эффект \"Зимняя стужа\", повышающий вероятность критического удара \"Ледяного копья\" и \"Ледяной стрелы\" против пораженной цели на 2%. Время действия – 15 сек. Суммируется до 2 раз."],["Gives your Frost damage spells a 60% chance to apply the Winter's Chill effect, which increases the chance your Ice Lance and Frostbolt spells will critically hit the target by 2% for 15 sec. Stacks up to 3 times.","Заклинания магии льда с вероятностью 60% применяют эффект \"Зимняя стужа\", повышающий вероятность критического удара \"Ледяного копья\" и \"Ледяной стрелы\" против пораженной цели на 2%. Время действия – 15 сек. Суммируется до 3 раз."],["Gives your Frost damage spells a 80% chance to apply the Winter's Chill effect, which increases the chance your Ice Lance and Frostbolt spells will critically hit the target by 2% for 15 sec. Stacks up to 4 times.","Заклинания магии льда с вероятностью 80% применяют эффект \"Зимняя стужа\", повышающий вероятность критического удара \"Ледяного копья\" и \"Ледяной стрелы\" против пораженной цели на 2%. Время действия – 15 сек. Суммируется до 4 раз."],["Gives your Frost damage spells a 100% chance to apply the Winter's Chill effect, which increases the chance your Ice Lance and Frostbolt spells will critically hit the target by 2% for 15 sec. Stacks up to 5 times.","Заклинания магии льда с вероятностью 100% применяют эффект \"Зимняя стужа\", повышающий вероятность критического удара \"Ледяного копья\" и \"Ледяной стрелы\" против пораженной цели на 2%. Время действия – 15 сек. Суммируется до 5 раз."],["Ice Barrier","Ледяная преграда"],["Instantly shields you, absorbing 431 damage. Lasts 1 min. While the shield holds, your spellcasts will not be interrupted or delayed from taking damage.","Вас мгновенно окружает защитный барьер, поглощающий 431 ед. урона. Время действия – 1 мин. Все время действия щита ваши заклинания невозможно прервать, а получаемый урон не вызывает задержку при применении заклинаний."]]},"warlock":{"build":"1.60.1.70009","className":"Warlock","pairs":[["Warlock","Чернокнижник"],["Affliction","Колдовство"],["Improved Life Tap","Улучшенный жизнеотвод"],["Increases the amount of Mana awarded by your Life Tap spell by 10%.","Увеличение количества маны, полученной при использовании вами заклинания \"Жизнеотвод\" на 10%."],["Increases the amount of Mana awarded by your Life Tap spell by 20%.","Увеличение количества маны, полученной при использовании вами заклинания \"Жизнеотвод\" на 20%."],["Suppression","Подавление"],["Improves your chance to hit by 1% and reduces all threat you generate by 4%.","Повышает вероятность попадания на 1% и снижает уровень создаваемой угрозы на 4%."],["Improves your chance to hit by 2% and reduces all threat you generate by 8%.","Повышает вероятность попадания на 2% и снижает уровень создаваемой угрозы на 8%."],["Improves your chance to hit by 3% and reduces all threat you generate by 12%.","Повышает вероятность попадания на 3% и снижает уровень создаваемой угрозы на 12%."],["Improves your chance to hit by 4% and reduces all threat you generate by 16%.","Повышает вероятность попадания на 4% и снижает уровень создаваемой угрозы на 16%."],["Improves your chance to hit by 5% and reduces all threat you generate by 20%.","Повышает вероятность попадания на 5% и снижает уровень создаваемой угрозы на 20%."],["Improved Corruption","Улучшенная порча"],["Reduces the casting time of your Corruption spell by 0.4 sec and increases the damage it deals by 2%.","Сокращает время применения \"Порчи\" на 0.4 сек. и увеличивает наносимый ею урон на 2%."],["Reduces the casting time of your Corruption spell by 0.8 sec and increases the damage it deals by 4%.","Сокращает время применения \"Порчи\" на 0.8 сек. и увеличивает наносимый ею урон на 4%."],["Reduces the casting time of your Corruption spell by 1.2 sec and increases the damage it deals by 6%.","Сокращает время применения \"Порчи\" на 1.2 сек. и увеличивает наносимый ею урон на 6%."],["Reduces the casting time of your Corruption spell by 1.6 sec and increases the damage it deals by 8%.","Сокращает время применения \"Порчи\" на 1.6 сек. и увеличивает наносимый ею урон на 8%."],["Reduces the casting time of your Corruption spell by 2 sec and increases the damage it deals by 10%.","Сокращает время применения \"Порчи\" на 2 сек. и увеличивает наносимый ею урон на 10%."],["Malediction","Темное проклятие"],["Increases all periodic damage done by your Warlock spells by 1%.","Увеличивает периодический урон от ваших заклинаний чернокнижника на 1%."],["Increases all periodic damage done by your Warlock spells by 2%.","Увеличивает периодический урон от ваших заклинаний чернокнижника на 2%."],["Increases all periodic damage done by your Warlock spells by 3%.","Увеличивает периодический урон от ваших заклинаний чернокнижника на 3%."],["Increases all periodic damage done by your Warlock spells by 4%.","Увеличивает периодический урон от ваших заклинаний чернокнижника на 4%."],["Increases all periodic damage done by your Warlock spells by 5%.","Увеличивает периодический урон от ваших заклинаний чернокнижника на 5%."],["Soul Harvesting","Жатва душ"],["You gain Soul Harvest for 10 sec if a victim is killed while afflicted with your Drain Soul. Soul Harvest allows your Mana to regenerate at 50% of normal speed while you are casting spells, and grants a 50% increase to your Mana regeneration.","Когда противник погибает под действием вашего \"Похищения души\", вы получаете эффект \"Жатва душ\" на 10 сек. \"Жатва душ\" позволяет восстанавливать ману во время применения заклинаний со скоростью 50% обычной и ускоряет восстановление маны на 50%."],["You gain Soul Harvest for 10 sec if a victim is killed while afflicted with your Drain Soul. Soul Harvest allows your Mana to regenerate at 100% of normal speed while you are casting spells, and grants a 100% increase to your Mana regeneration.","Когда противник погибает под действием вашего \"Похищения души\", вы получаете эффект \"Жатва душ\" на 10 сек. \"Жатва душ\" позволяет восстанавливать ману во время применения заклинаний со скоростью 100% обычной и ускоряет восстановление маны на 100%."],["Improved Drains","Улучшенное похищение"],["Increases health drained or damage done by your Drain Life, Drain Soul, and Wrack spells by 7%.","Усиливает \"Похищение жизни\", \"Похищение души\" и \"Судороги\", увеличивая урон или количество похищаемого здоровья на 7%."],["Increases health drained or damage done by your Drain Life, Drain Soul, and Wrack spells by 13%.","Усиливает \"Похищение жизни\", \"Похищение души\" и \"Судороги\", увеличивая урон или количество похищаемого здоровья на 13%."],["Increases health drained or damage done by your Drain Life, Drain Soul, and Wrack spells by 20%.","Усиливает \"Похищение жизни\", \"Похищение души\" и \"Судороги\", увеличивая урон или количество похищаемого здоровья на 20%."],["Improved Bane of Agony","Улучшенный бич агонии"],["Increases the damage done by your Bane of Agony by 5%.","Увеличивает урон от \"Бича агонии\" на 5%."],["Increases the damage done by your Bane of Agony by 10%.","Увеличивает урон от \"Бича агонии\" на 10%."],["Fel Concentration","Сосредоточение Скверны"],["Gives you a 23% chance to avoid interruption caused by damage while channeling or casting your Drain Life, Drain Mana, Drain Soul, or Wrack spells.","С вероятностью 23% позволяет избежать задержки при поддержании или применении \"Похищения жизни\", \"Похищения маны\", \"Похищения души\" и \"Крушение\", когда вы получаете урон."],["Gives you a 47% chance to avoid interruption caused by damage while channeling or casting your Drain Life, Drain Mana, Drain Soul, or Wrack spells.","С вероятностью 47% позволяет избежать задержки при поддержании или применении \"Похищения жизни\", \"Похищения маны\", \"Похищения души\" и \"Крушение\", когда вы получаете урон."],["Gives you a 70% chance to avoid interruption caused by damage while channeling or casting your Drain Life, Drain Mana, Drain Soul, or Wrack spells.","С вероятностью 70% позволяет избежать задержки при поддержании или применении \"Похищения жизни\", \"Похищения маны\", \"Похищения души\" и \"Крушение\", когда вы получаете урон."],["Amplify Curse","Усиление проклятия"],["Increases the effect of your next Curse of Weakness or Bane of Agony by 50%, or your next Curse of Exhaustion by 20%. Lasts 30 sec.","Усиливает эффект следующего \"Проклятия слабости\" или \"Бича агонии\" на 50% или следующего \"Проклятия изнеможения\" – на 20%. Время действия – 30 сек."],["Pandemic","Пандемия"],["Increases the critical strike damage bonus of your Corruption, Bane of Agony, Bane of Doom, Drain Soul, Drain Life, Siphon Life, and Wrack spells by 33%.","Увеличивает критический урон от \"Порчи\", \"Бича агонии\", \"Бича судьбы\", \"Похищения души\", \"Похищения жизни\", \"Вытягивания жизни\" и \"Судорог\" на 33%."],["Increases the critical strike damage bonus of your Corruption, Bane of Agony, Bane of Doom, Drain Soul, Drain Life, Siphon Life, and Wrack spells by 67%.","Увеличивает критический урон от \"Порчи\", \"Бича агонии\", \"Бича судьбы\", \"Похищения души\", \"Похищения жизни\", \"Вытягивания жизни\" и \"Судорог\" на 67%."],["Increases the critical strike damage bonus of your Corruption, Bane of Agony, Bane of Doom, Drain Soul, Drain Life, Siphon Life, and Wrack spells by 100%.","Увеличивает критический урон от \"Порчи\", \"Бича агонии\", \"Бича судьбы\", \"Похищения души\", \"Похищения жизни\", \"Вытягивания жизни\" и \"Судорог\" на 100%."],["Malevolence","Злоба"],["Increases the critical effect chance of your Shadow spells by 1%.","Повышает вероятность критического эффекта заклинаний темной магии на 1%."],["Increases the critical effect chance of your Shadow spells by 2%.","Повышает вероятность критического эффекта заклинаний темной магии на 2%."],["Increases the critical effect chance of your Shadow spells by 3%.","Повышает вероятность критического эффекта заклинаний темной магии на 3%."],["Increases the critical effect chance of your Shadow spells by 4%.","Повышает вероятность критического эффекта заклинаний темной магии на 4%."],["Increases the critical effect chance of your Shadow spells by 5%.","Повышает вероятность критического эффекта заклинаний темной магии на 5%."],["Nightfall","Сумерки"],["Gives your Corruption, Drain Soul, Drain Life, and Wrack spells a 2% chance to cause you to enter a Shadow Trance after damaging the opponent. The Shadow Trance reduces the casting time of your next Shadow Bolt spell by 100%.","Когда \"Порча\", \"Похищение души\", \"Похищение жизни\" и \"Судороги\" наносят урон противнику, вы с вероятностью 2% входите в теневой транс, сокращающий время применения следующей \"Стрелы Тьмы\" на 100%."],["Gives your Corruption, Drain Soul, Drain Life, and Wrack spells a 4% chance to cause you to enter a Shadow Trance after damaging the opponent. The Shadow Trance reduces the casting time of your next Shadow Bolt spell by 100%.","Когда \"Порча\", \"Похищение души\", \"Похищение жизни\" и \"Судороги\" наносят урон противнику, вы с вероятностью 4% входите в теневой транс, сокращающий время применения следующей \"Стрелы Тьмы\" на 100%."],["Curse of Exhaustion","Проклятие изнеможения"],["Reduces the target's movement speed by 30% for 12 sec. Only one Curse per Warlock can be active on any one target.","Снижает скорость передвижения цели на 30% на 12 сек. На цель может одновременно действовать только одно проклятие каждого чернокнижника."],["Siphon Life","Вытягивание жизни"],["Transfers 11 health from the target to the caster every 3 sec. Lasts 30 sec.","Вы похищаете у цели 11 ед. здоровья раз в 3 сек. и восполняете себе здоровье в том же объеме. Время действия – 30 сек."],["Soul Siphon","Вытягивание души"],["Increases the damage done or health drained by your Drain Life, Drain Soul, and Wrack spells by 4% per each of your other Affliction effects active on the target, up to a maximum increase of 12%.","Усиливает \"Похищение жизни\", \"Похищение души\" и \"Судороги\", увеличивая урон или количество похищаемого здоровья на 4% за каждый иной эффект категории \"Колдовство\" на цели. Максимальный бонус – 12%."],["Increases the damage done or health drained by your Drain Life, Drain Soul, and Wrack spells by 8% per each of your other Affliction effects active on the target, up to a maximum increase of 24%.","Усиливает \"Похищение жизни\", \"Похищение души\" и \"Судороги\", увеличивая урон или количество похищаемого здоровья на 8% за каждый иной эффект категории \"Колдовство\" на цели. Максимальный бонус – 24%."],["Increases the damage done or health drained by your Drain Life, Drain Soul, and Wrack spells by 12% per each of your other Affliction effects active on the target, up to a maximum increase of 36%.","Усиливает \"Похищение жизни\", \"Похищение души\" и \"Судороги\", увеличивая урон или количество похищаемого здоровья на 12% за каждый иной эффект категории \"Колдовство\" на цели. Максимальный бонус – 36%."],["Shadow Mastery","Власть над Тенями"],["Increases the damage dealt or life drained by your Shadow spells by 1%.","Увеличение урона, наносимого заклинаниями темной магии на 1%."],["Increases the damage dealt or life drained by your Shadow spells by 2%.","Увеличение урона, наносимого заклинаниями темной магии на 2%."],["Increases the damage dealt or life drained by your Shadow spells by 3%.","Увеличение урона, наносимого заклинаниями темной магии на 3%."],["Increases the damage dealt or life drained by your Shadow spells by 4%.","Увеличение урона, наносимого заклинаниями темной магии на 4%."],["Increases the damage dealt or life drained by your Shadow spells by 5%.","Увеличение урона, наносимого заклинаниями темной магии на 5%."],["Wrack","Судороги"],["Tears the target apart from within, dealing 36 Shadow damage every 1 sec and increasing the damage they take from your other Shadow damage over time effects by 10%. Lasts 6 sec.","Терзает цель изнутри, нанося 36 ед. урона от темной магии раз в 1 сек. и увеличивая периодический урон от темной магии, который цель получает от других ваших эффектов, на 10%. Время действия – 6 сек."],["Demonology","Демонология"],["Improved Health Funnel","Улучшенный канал здоровья"],["Increases the amount of health transferred by your Health Funnel spell by 20%, reduces its health cost by 15%, and reduces all threat your Health Funnel generates by 50%. Allows Health Funnel to be used regardless of your demon's health.","\"Канал здоровья\" передает на 20% больше здоровья, расходует на 15% меньше здоровья и создает на 50% меньше угрозы. \"Канал здоровья\" можно применять вне зависимости от уровня здоровья вашего демона."],["Increases the amount of health transferred by your Health Funnel spell by 40%, reduces its health cost by 30%, and reduces all threat your Health Funnel generates by 100%. Allows Health Funnel to be used regardless of your demon's health.","\"Канал здоровья\" передает на 40% больше здоровья, расходует на 30% меньше здоровья и создает на 100% меньше угрозы. \"Канал здоровья\" можно применять вне зависимости от уровня здоровья вашего демона."],["Improved Imp","Улучшенный бес"],["Increases the damage of your Imp's Firebolt spell by 10% and the effect of its Fire Shield spell by 10%.","Увеличивает урон, наносимый \"Огненной стрелой\" беса, на 10%, а эффективность его \"Огненного щита\" – на 10%."],["Increases the damage of your Imp's Firebolt spell by 20% and the effect of its Fire Shield spell by 20%.","Увеличивает урон, наносимый \"Огненной стрелой\" беса, на 20%, а эффективность его \"Огненного щита\" – на 20%."],["Increases the damage of your Imp's Firebolt spell by 30% and the effect of its Fire Shield spell by 30%.","Увеличивает урон, наносимый \"Огненной стрелой\" беса, на 30%, а эффективность его \"Огненного щита\" – на 30%."],["Demonic Embrace","Демоническое облачение"],["Increases your total Stamina by 3%.","Повышает выносливость на 3%."],["Increases your total Stamina by 6%.","Повышает выносливость на 6%."],["Increases your total Stamina by 9%.","Повышает выносливость на 9%."],["Increases your total Stamina by 12%.","Повышает выносливость на 12%."],["Increases your total Stamina by 15%.","Повышает выносливость на 15%."],["Unholy Power","Нечестивая сила"],["Increases all damage done by your Imp, Voidwalker, Succubus, Incubus, and Felhunter pets by 2%.","Увеличивает урон, наносимый вашим бесом, демоном Бездны, суккубом, инкубом и охотником Скверны, на 2%."],["Increases all damage done by your Imp, Voidwalker, Succubus, Incubus, and Felhunter pets by 4%.","Увеличивает урон, наносимый вашим бесом, демоном Бездны, суккубом, инкубом и охотником Скверны, на 4%."],["Increases all damage done by your Imp, Voidwalker, Succubus, Incubus, and Felhunter pets by 6%.","Увеличивает урон, наносимый вашим бесом, демоном Бездны, суккубом, инкубом и охотником Скверны, на 6%."],["Increases all damage done by your Imp, Voidwalker, Succubus, Incubus, and Felhunter pets by 8%.","Увеличивает урон, наносимый вашим бесом, демоном Бездны, суккубом, инкубом и охотником Скверны, на 8%."],["Increases all damage done by your Imp, Voidwalker, Succubus, Incubus, and Felhunter pets by 10%.","Увеличивает урон, наносимый вашим бесом, демоном Бездны, суккубом, инкубом и охотником Скверны, на 10%."],["Demonic Aegis","Демоническая эгида"],["Increases the effectiveness of your Demon Skin and Demon Armor spells by 15%.","Повышает эффективность \"Шкуры демона\" и \"Демонического доспеха\" на 15%."],["Increases the effectiveness of your Demon Skin and Demon Armor spells by 30%.","Повышает эффективность \"Шкуры демона\" и \"Демонического доспеха\" на 30%."],["Improved Voidwalker","Улучшенный демон Бездны"],["Increases the effectiveness of your Voidwalker's Torment, Consume Shadows, Sacrifice, and Suffering spells by 10%.","Повышает эффективность способностей демона Бездны \"Мучение\", \"Поглощение теней\", \"Жертвоприношение\" и \"Муки\" на 10%."],["Increases the effectiveness of your Voidwalker's Torment, Consume Shadows, Sacrifice, and Suffering spells by 20%.","Повышает эффективность способностей демона Бездны \"Мучение\", \"Поглощение теней\", \"Жертвоприношение\" и \"Муки\" на 20%."],["Increases the effectiveness of your Voidwalker's Torment, Consume Shadows, Sacrifice, and Suffering spells by 30%.","Повышает эффективность способностей демона Бездны \"Мучение\", \"Поглощение теней\", \"Жертвоприношение\" и \"Муки\" на 30%."],["Fel Vitality","Энергия Скверны"],["Increases the maximum health and Mana of your Imp, Voidwalker, Succubus, Incubus, and Felhunter by 5%, and increases your maximum Mana by 5%.","Увеличивает максимальный запас здоровья и маны беса, демона Бездны, суккуба, инкуба и охотника Скверны на 5%, а ваш максимальный запас маны – на 5%."],["Increases the maximum health and Mana of your Imp, Voidwalker, Succubus, Incubus, and Felhunter by 10%, and increases your maximum Mana by 10%.","Увеличивает максимальный запас здоровья и маны беса, демона Бездны, суккуба, инкуба и охотника Скверны на 10%, а ваш максимальный запас маны – на 10%."],["Increases the maximum health and Mana of your Imp, Voidwalker, Succubus, Incubus, and Felhunter by 15%, and increases your maximum Mana by 15%.","Увеличивает максимальный запас здоровья и маны беса, демона Бездны, суккуба, инкуба и охотника Скверны на 15%, а ваш максимальный запас маны – на 15%."],["Demonic Energies","Демоническая энергия"],["You heal your pet for 8% of all spell damage you deal. When you gain Mana from Life Tap, your summoned demon gains 50% of the Mana you gain.","Ваш прислужник восполняет здоровье в объеме 8% наносимого вами урона от заклинаний. Когда вы получаете ману при помощи \"Жизнеотвода\", ваш демон также восполняет ману с эффективностью 50%."],["You heal your pet for 15% of all spell damage you deal. When you gain Mana from Life Tap, your summoned demon gains 100% of the Mana you gain.","Ваш прислужник восполняет здоровье в объеме 15% наносимого вами урона от заклинаний. Когда вы получаете ману при помощи \"Жизнеотвода\", ваш демон также восполняет ману с эффективностью 100%."],["Improved Sayaad","Улучшенный сайаад"],["Increases the effect of your Succubus' and Incubus' Lash of Pain and Soothing Kiss spells by 10%, and increases the duration of your Succubus' and Incubus' Seduction and Lesser Invisibility spells by 10%.","Усиливает эффект от \"Всплеска боли\" и \"Утешительного поцелуя\" суккуба или инкуба на 10% и продлевает действие \"Соблазнения\" и \"Слабой невидимости\" суккуба или инкуба на 10%."],["Increases the effect of your Succubus' and Incubus' Lash of Pain and Soothing Kiss spells by 20%, and increases the duration of your Succubus' and Incubus' Seduction and Lesser Invisibility spells by 20%.","Усиливает эффект от \"Всплеска боли\" и \"Утешительного поцелуя\" суккуба или инкуба на 20% и продлевает действие \"Соблазнения\" и \"Слабой невидимости\" суккуба или инкуба на 20%."],["Increases the effect of your Succubus' and Incubus' Lash of Pain and Soothing Kiss spells by 30%, and increases the duration of your Succubus' and Incubus' Seduction and Lesser Invisibility spells by 30%.","Усиливает эффект от \"Всплеска боли\" и \"Утешительного поцелуя\" суккуба или инкуба на 30% и продлевает действие \"Соблазнения\" и \"Слабой невидимости\" суккуба или инкуба на 30%."],["Demonic Sacrifice","Демоническое жертвоприношение"],["When activated, sacrifices your summoned Demon to enhance the opposing aspect of your power, granting you an effect that lasts 120 min. The effect is canceled if any Demon is summoned. Imp: Increases your Shadow damage by 15%. Voidwalker: Restores 2% of your total Mana every 4 sec. Succubus/Incubus: Increases your Fire damage by 15%. Felhunter: Restores 3% of your total Health every 4 sec.","При активации приносит в жертву призванного демона и дает вам эффект, противоположный его сущности. Действует 120 мин. или до вызова нового демона. Бес: увеличивает урон от темной магии на 15%. Демон Бездны: восполняет 2% общего запаса маны раз в 4 сек. Суккуб/инкуб: увеличивает урон от огня на 15%. Охотник Скверны: восполняет 3% общего запаса здоровья раз в 4 сек."],["Master Summoner","Мастер призыва"],["Reduces the casting time of your Imp, Voidwalker, Succubus, Incubus, and Felhunter Summoning spells by 2 sec and the Mana cost by 20%.","Сокращает время призыва беса, демона Бездны, суккуба, инкуба и охотника Скверны на 2 сек. и снижает его стоимость на 20%."],["Reduces the casting time of your Imp, Voidwalker, Succubus, Incubus, and Felhunter Summoning spells by 4 sec and the Mana cost by 40%.","Сокращает время призыва беса, демона Бездны, суккуба, инкуба и охотника Скверны на 4 сек. и снижает его стоимость на 40%."],["Decimation","Истребление"],["Reduces the cooldown of your Soul Fire spell by 45%. When you cast Shadow Bolt or Searing Pain on an enemy below 35% health, they deal 3% increased damage, and for the next 10 sec your Soul Fire spell has its cast time reduced by 20% and costs no Soul Shards.","Сокращает время восстановления \"Ожога души\" на 45%. Когда вы применяете \"Стрелу тьмы\" или \"Жгучую боль\" к противнику с уровнем здоровья ниже 35%, эти заклинания наносят на 3% больше урона. Кроме того, в течение следующих 10 сек. \"Ожог души\" не расходует осколки души, а время его применения сокращается на 20%."],["Reduces the cooldown of your Soul Fire spell by 90%. When you cast Shadow Bolt or Searing Pain on an enemy below 35% health, they deal 6% increased damage, and for the next 10 sec your Soul Fire spell has its cast time reduced by 40% and costs no Soul Shards.","Сокращает время восстановления \"Ожога души\" на 90%. Когда вы применяете \"Стрелу тьмы\" или \"Жгучую боль\" к противнику с уровнем здоровья ниже 35%, эти заклинания наносят на 6% больше урона. Кроме того, в течение следующих 10 сек. \"Ожог души\" не расходует осколки души, а время его применения сокращается на 40%."],["Fel Domination","Господство Скверны"],["Your next Imp, Voidwalker, Succubus, Incubus, or Felhunter Summon spell has its casting time reduced by 5.5 sec and its Mana cost reduced by 50%.","Сокращает время призыва следующего беса, демона Бездны, суккуба, инкуба или охотника Скверны на 5.5 сек. и снижает его стоимость на 50%."],["Demonic Brand","Демоническое клеймо"],["Your Searing Pain generates 17% less threat and brands the target for 10 sec. Your pet's next 2 attacks against the target generate high threat and deal additional Fire or Shadow damage based on the pet.","\"Жгучая боль\" создает на 17% меньше угрозы и отмечает цель клеймом на 10 сек. 2 следующие атаки вашего прислужника против этой цели создают высокий уровень угрозы и наносят дополнительный урон от огня или темной магии в зависимости от типа прислужника."],["Your Searing Pain generates 33% less threat and brands the target for 10 sec. Your pet's next 4 attacks against the target generate high threat and deal additional Fire or Shadow damage based on the pet.","\"Жгучая боль\" создает на 33% меньше угрозы и отмечает цель клеймом на 10 сек. 4 следующие атаки вашего прислужника против этой цели создают высокий уровень угрозы и наносят дополнительный урон от огня или темной магии в зависимости от типа прислужника."],["Your Searing Pain generates 50% less threat and brands the target for 10 sec. Your pet's next 6 attacks against the target generate high threat and deal additional Fire or Shadow damage based on the pet.","\"Жгучая боль\" создает на 50% меньше угрозы и отмечает цель клеймом на 10 сек. 6 следующих атак вашего прислужника против этой цели создают высокий уровень угрозы и наносят дополнительный урон от огня или темной магии в зависимости от типа прислужника."],["Improved Felhunter","Улучшенный охотник Скверны"],["Increases the Attack Power reduction of your Felhunter's Tainted Blood, the healing of its Devour Magic, and the detection level of its Paranoia by 10%, and reduces the cooldown of its Spell Lock by 2 sec.","Увеличивает эффективность, с которой \"Испорченная кровь\" Охотника Скверны уменьшает силу атаки противника, повышает эффективность исцеления \"Пожиранием магии\", а также увеличивает уровень обнаружения \"Паранойи\" на 10%. Сокращает время восстановления \"Запрета чар\" на 2 сек."],["Increases the Attack Power reduction of your Felhunter's Tainted Blood, the healing of its Devour Magic, and the detection level of its Paranoia by 20%, and reduces the cooldown of its Spell Lock by 4 sec.","Увеличивает эффективность, с которой \"Испорченная кровь\" Охотника Скверны уменьшает силу атаки противника, повышает эффективность исцеления \"Пожиранием магии\", а также увеличивает уровень обнаружения \"Паранойи\" на 20%. Сокращает время восстановления \"Запрета чар\" на 4 сек."],["Increases the Attack Power reduction of your Felhunter's Tainted Blood, the healing of its Devour Magic, and the detection level of its Paranoia by 30%, and reduces the cooldown of its Spell Lock by 6 sec.","Увеличивает эффективность, с которой \"Испорченная кровь\" Охотника Скверны уменьшает силу атаки противника, повышает эффективность исцеления \"Пожиранием магии\", а также увеличивает уровень обнаружения \"Паранойи\" на 30%. Сокращает время восстановления \"Запрета чар\" на 6 сек."],["Soul Link","Связка души"],["When active, 30% of all damage taken by the caster is taken by your Imp, Voidwalker, Succubus, Incubus, or Felhunter Demon instead. In addition, both the Demon and the master will inflict 3% more damage. Lasts as long as the Demon is active.","Пока действует этот эффект, 30% получаемого вами урона перенаправляется на вашего беса, демона Бездны, суккуба, инкуба или охотника Скверны. Кроме того, вы и ваш демон наносите на 3% больше урона. Эффект действует, пока демон активен."],["Demonic Knowledge","Демоническое знание"],["Increases your spell damage and your Demon pet's spell damage by up to 33% of your level while you have a summoned Demon pet active.","Увеличивает ваш урон от заклинаний и урон от заклинаний вашего демона максимум на 33% вашего уровня, пока жив ваш демон-прислужник."],["Increases your spell damage and your Demon pet's spell damage by up to 67% of your level while you have a summoned Demon pet active.","Увеличивает ваш урон от заклинаний и урон от заклинаний вашего демона максимум на 67% вашего уровня, пока жив ваш демон-прислужник."],["Increases your spell damage and your Demon pet's spell damage by up to 100% of your level while you have a summoned Demon pet active.","Увеличивает ваш урон от заклинаний и урон от заклинаний вашего демона максимум на 100% вашего уровня, пока жив ваш демон-прислужник."],["Master Demonologist","Мастер-демонолог"],["Grants both the Warlock and the summoned demon an effect as long as that demon is active. Imp - Increases Fire damage done by 2%. Voidwalker - Reduces Physical damage taken by 2%. Succubus/Incubus - Increases Shadow damage done by 2%. Felhunter - Reduces Magic damage taken by 2%.","Дает вам и призванному демону эффект, действующий, пока жив демон. Бес: увеличивает наносимый урон от огня на 2%. Демон Бездны: уменьшает получаемый физический урон на 2%. Суккуб/инкуб: увеличивает наносимый урон от темной магии на 2%. Охотник Скверны: уменьшает получаемый магический урон на 2%."],["Grants both the Warlock and the summoned demon an effect as long as that demon is active. Imp - Increases Fire damage done by 4%. Voidwalker - Reduces Physical damage taken by 4%. Succubus/Incubus - Increases Shadow damage done by 4%. Felhunter - Reduces Magic damage taken by 4%.","Дает вам и призванному демону эффект, действующий, пока жив демон. Бес: увеличивает наносимый урон от огня на 4%. Демон Бездны: уменьшает получаемый физический урон на 4%. Суккуб/инкуб: увеличивает наносимый урон от темной магии на 4%. Охотник Скверны: уменьшает получаемый магический урон на 4%."],["Grants both the Warlock and the summoned demon an effect as long as that demon is active. Imp - Increases Fire damage done by 6%. Voidwalker - Reduces Physical damage taken by 6%. Succubus/Incubus - Increases Shadow damage done by 6%. Felhunter - Reduces Magic damage taken by 6%.","Дает вам и призванному демону эффект, действующий, пока жив демон. Бес: увеличивает наносимый урон от огня на 6%. Демон Бездны: уменьшает получаемый физический урон на 6%. Суккуб/инкуб: увеличивает наносимый урон от темной магии на 6%. Охотник Скверны: уменьшает получаемый магический урон на 6%."],["Grants both the Warlock and the summoned demon an effect as long as that demon is active. Imp - Increases Fire damage done by 8%. Voidwalker - Reduces Physical damage taken by 8%. Succubus/Incubus - Increases Shadow damage done by 8%. Felhunter - Reduces Magic damage taken by 8%.","Дает вам и призванному демону эффект, действующий, пока жив демон. Бес: увеличивает наносимый урон от огня на 8%. Демон Бездны: уменьшает получаемый физический урон на 8%. Суккуб/инкуб: увеличивает наносимый урон от темной магии на 8%. Охотник Скверны: уменьшает получаемый магический урон на 8%."],["Grants both the Warlock and the summoned demon an effect as long as that demon is active. Imp - Increases Fire damage done by 10%. Voidwalker - Reduces Physical damage taken by 10%. Succubus/Incubus - Increases Shadow damage done by 10%. Felhunter - Reduces Magic damage taken by 10%.","Дает вам и призванному демону эффект, действующий, пока жив демон. Бес: увеличивает наносимый урон от огня на 10%. Демон Бездны: уменьшает получаемый физический урон на 10%. Суккуб/инкуб: увеличивает наносимый урон от темной магии на 10%. Охотник Скверны: уменьшает получаемый магический урон на 10%."],["Demonic Pact","Демонический союз"],["Your Demonic Sacrifice effect is no longer cancelled by summoning a different Demon pet. Resummoning the sacrificed pet will still cancel the effect.","Эффект \"Демонического жертвоприношения\" больше не прерывается при призыве другого прислужника-демона. Эффект прервется, если снова призвать прислужника, которого вы только что принесли в жертву."],["Destruction","Разрушение"],["Destructive Reach","Предел разрушения"],["Increases the range of your damaging spells by 10%.","Увеличивает дальность действия наносящих урон заклинаний на 10%."],["Increases the range of your damaging spells by 20%.","Увеличивает дальность действия наносящих урон заклинаний на 20%."],["Improved Shadow Bolt","Улучшенная стрела Тьмы"],["Your Shadow Bolt critical strikes increase Shadow damage taken by the target from your attacks by 4% for 12 sec.","Критические удары \"Стрелы Тьмы\" увеличивают урон от темной магии, получаемый целью от ваших атак, на 4% на 12 сек."],["Your Shadow Bolt critical strikes increase Shadow damage taken by the target from your attacks by 8% for 12 sec.","Критические удары \"Стрелы Тьмы\" увеличивают урон от темной магии, получаемый целью от ваших атак, на 8% на 12 сек."],["Your Shadow Bolt critical strikes increase Shadow damage taken by the target from your attacks by 12% for 12 sec.","Критические удары \"Стрелы Тьмы\" увеличивают урон от темной магии, получаемый целью от ваших атак, на 12% на 12 сек."],["Your Shadow Bolt critical strikes increase Shadow damage taken by the target from your attacks by 16% for 12 sec.","Критические удары \"Стрелы Тьмы\" увеличивают урон от темной магии, получаемый целью от ваших атак, на 16% на 12 сек."],["Your Shadow Bolt critical strikes increase Shadow damage taken by the target from your attacks by 20% for 12 sec.","Критические удары \"Стрелы Тьмы\" увеличивают урон от темной магии, получаемый целью от ваших атак, на 20% на 12 сек."],["Bane","Погибель"],["Reduces the casting time of your Shadow Bolt, Immolate, and Incinerate spells by 0.1 sec and your Soul Fire spell by 0.4 sec.","Сокращает время применения \"Стрелы Тьмы\", \"Жертвенного огня\" и \"Испепеления\" на 0.1 сек., а время применения \"Ожога души\" – на 0.4 сек."],["Reduces the casting time of your Shadow Bolt, Immolate, and Incinerate spells by 0.2 sec and your Soul Fire spell by 0.8 sec.","Сокращает время применения \"Стрелы Тьмы\", \"Жертвенного огня\" и \"Испепеления\" на 0.2 сек., а время применения \"Ожога души\" – на 0.8 сек."],["Reduces the casting time of your Shadow Bolt, Immolate, and Incinerate spells by 0.3 sec and your Soul Fire spell by 1.2 sec.","Сокращает время применения \"Стрелы Тьмы\", \"Жертвенного огня\" и \"Испепеления\" на 0.3 сек., а время применения \"Ожога души\" – на 1.2 сек."],["Reduces the casting time of your Shadow Bolt, Immolate, and Incinerate spells by 0.4 sec and your Soul Fire spell by 1.6 sec.","Сокращает время применения \"Стрелы Тьмы\", \"Жертвенного огня\" и \"Испепеления\" на 0.4 сек., а время применения \"Ожога души\" – на 1.6 сек."],["Reduces the casting time of your Shadow Bolt, Immolate, and Incinerate spells by 0.5 sec and your Soul Fire spell by 2 sec.","Сокращает время применения \"Стрелы Тьмы\", \"Жертвенного огня\" и \"Испепеления\" на 0.5 сек., а время применения \"Ожога души\" – на 2 сек."],["Molten Skin","Раскаленная кожа"],["Reduces all damage taken by 2%.","Уменьшает получаемый урон на 2%."],["Reduces all damage taken by 4%.","Уменьшает получаемый урон на 4%."],["Reduces all damage taken by 6%.","Уменьшает получаемый урон на 6%."],["Reduces all damage taken by 8%.","Уменьшает получаемый урон на 8%."],["Reduces all damage taken by 10%.","Уменьшает получаемый урон на 10%."],["Cataclysm","Катаклизм"],["Reduces the Mana cost of your Destruction spells by 3%.","Снижение расхода маны на ваши заклинания категории \"Разрушение\" на 3%."],["Reduces the Mana cost of your Destruction spells by 6%.","Снижение расхода маны на ваши заклинания категории \"Разрушение\" на 6%."],["Reduces the Mana cost of your Destruction spells by 10%.","Снижение расхода маны на ваши заклинания категории \"Разрушение\" на 10%."],["Aftermath","Последствия"],["Increases the initial damage of your Immolate spell by 10% and your Conflagrate spell has a 20% chance to Daze the target, reducing the target's movement speed by 50% for 5 sec.","Увеличивает мгновенный урон от \"Жертвенного огня\" на 10%. \"Поджигание\" с вероятностью 20% вызывает у цели головокружение, снижая ее скорость передвижения на 50% на 5 сек."],["Increases the initial damage of your Immolate spell by 20% and your Conflagrate spell has a 40% chance to Daze the target, reducing the target's movement speed by 50% for 5 sec.","Увеличивает мгновенный урон от \"Жертвенного огня\" на 20%. \"Поджигание\" с вероятностью 40% вызывает у цели головокружение, снижая ее скорость передвижения на 50% на 5 сек."],["Increases the initial damage of your Immolate spell by 30% and your Conflagrate spell has a 60% chance to Daze the target, reducing the target's movement speed by 50% for 5 sec.","Увеличивает мгновенный урон от \"Жертвенного огня\" на 30%. \"Поджигание\" с вероятностью 60% вызывает у цели головокружение, снижая ее скорость передвижения на 50% на 5 сек."],["Increases the initial damage of your Immolate spell by 40% and your Conflagrate spell has a 80% chance to Daze the target, reducing the target's movement speed by 50% for 5 sec.","Увеличивает мгновенный урон от \"Жертвенного огня\" на 40%. \"Поджигание\" с вероятностью 80% вызывает у цели головокружение, снижая ее скорость передвижения на 50% на 5 сек."],["Increases the initial damage of your Immolate spell by 50% and your Conflagrate spell has a 100% chance to Daze the target, reducing the target's movement speed by 50% for 5 sec.","Увеличивает мгновенный урон от \"Жертвенного огня\" на 50%. \"Поджигание\" с вероятностью 100% вызывает у цели головокружение, снижая ее скорость передвижения на 50% на 5 сек."],["Ruin","Разгром"],["Increases the critical strike damage bonus of your Destruction spells by 20%.","Увеличивает бонус к критическому урону от заклинаний категории \"Разрушение\" на 20%."],["Increases the critical strike damage bonus of your Destruction spells by 40%.","Увеличивает бонус к критическому урону от заклинаний категории \"Разрушение\" на 40%."],["Increases the critical strike damage bonus of your Destruction spells by 60%.","Увеличивает бонус к критическому урону от заклинаний категории \"Разрушение\" на 60%."],["Increases the critical strike damage bonus of your Destruction spells by 80%.","Увеличивает бонус к критическому урону от заклинаний категории \"Разрушение\" на 80%."],["Increases the critical strike damage bonus of your Destruction spells by 100%.","Увеличивает бонус к критическому урону от заклинаний категории \"Разрушение\" на 100%."],["Shadowburn","Ожог Тьмы"],["Instantly blasts the target for 66 Shadow damage. If a non-trivial target dies within 8 sec of being hit with Shadowburn, the caster gains a Soul Shard.","Мгновенно наносит цели 66 ед. урона от темной магии. Если представляющий угрозу противник, пораженный \"Ожогом Тьмы\", погибает в течение 8 сек., вы также получаете осколок души."],["Intensity","Напряжение"],["Gives you a 23% chance to resist interruption caused by damage while casting or channeling any Destruction spell.","Дает вам 23% шанс сопротивления прерыванию наложения заклинаний вследствие получения урона при наложении заклинаний \"Огненный ливень\", \"Адское Пламя\" и \"Ожог души\"."],["Gives you a 47% chance to resist interruption caused by damage while casting or channeling any Destruction spell.","Дает вам 47% шанс сопротивления прерыванию наложения заклинаний вследствие получения урона при наложении заклинаний \"Огненный ливень\", \"Адское Пламя\" и \"Ожог души\"."],["Gives you a 70% chance to resist interruption caused by damage while casting or channeling any Destruction spell.","Дает вам 70% шанс сопротивления прерыванию наложения заклинаний вследствие получения урона при наложении заклинаний \"Огненный ливень\", \"Адское Пламя\" и \"Ожог души\"."],["Agonizing Flames","Пламенная боль"],["Increases the critical strike chance of your Searing Pain spell by 3% and the damage done by all your Destruction spells by 3%.","Повышает вероятность критического эффекта \"Жгучей боли\" на 3%, а урон, наносимый другими заклинаниями категории \"Разрушение\", – на 3%."],["Increases the critical strike chance of your Searing Pain spell by 7% and the damage done by all your Destruction spells by 7%.","Повышает вероятность критического эффекта \"Жгучей боли\" на 7%, а урон, наносимый другими заклинаниями категории \"Разрушение\", – на 7%."],["Increases the critical strike chance of your Searing Pain spell by 10% and the damage done by all your Destruction spells by 10%.","Повышает вероятность критического эффекта \"Жгучей боли\" на 10%, а урон, наносимый другими заклинаниями категории \"Разрушение\", – на 10%."],["Conflagrate","Поджигание"],["Ignites a target that is already afflicted by your Immolate spell, dealing 95 Fire damage and consuming your Immolate effect.","Поджигает цель, на которую уже действует ваш \"Жертвенный огонь\", нанося 95 ед. урона от огня и поглощая \"Жертвенный огонь\"."],["Pyroclasm","Пироклазм"],["Gives your Soul Fire spell a 13% chance to Stun the target for 3 sec, and your Rain of Fire and Hellfire spells a 13% chance over their duration to Stun targets they damage for 3 sec.","\"Огонь души\" с вероятностью 13% оглушает цель на 3 сек., а \"Огненный ливень\" и \"Адское пламя\" с вероятностью 13% за все время действия оглушают цели, которым нанесли урон, на 3 сек."],["Gives your Soul Fire spell a 26% chance to Stun the target for 3 sec, and your Rain of Fire and Hellfire spells a 26% chance over their duration to Stun targets they damage for 3 sec.","\"Огонь души\" с вероятностью 26% оглушает цель на 3 сек., а \"Огненный ливень\" и \"Адское пламя\" с вероятностью 26% за все время действия оглушают цели, которым нанесли урон, на 3 сек."],["Bane of Havoc","Бич сокрушения"],["Afflicts the target for 5 min, causing 15% of all damage done by the Warlock to other targets to also be dealt to the cursed target. Bane of Havoc is limited to 1 target, and only one Bane per Warlock can be active on any one target.","Проклинает противника, после чего 15% урона, который вы наносите другим целям, также наносится этой цели. Время действия – 5 мин. Одновременно можно применить \"Бич сокрушения\" только к одной цели. На каждую цель может действовать только одно заклинание категории \"Бич\" каждого чернокнижника."],["Fire and Brimstone","Огонь и сера"],["Increases the critical strike chance of your Conflagrate spell by 8%.","Повышает вероятность критического эффекта \"Поджигания\" на 8%."],["Increases the critical strike chance of your Conflagrate spell by 17%.","Повышает вероятность критического эффекта \"Поджигания\" на 17%."],["Increases the critical strike chance of your Conflagrate spell by 25%.","Повышает вероятность критического эффекта \"Поджигания\" на 25%."],["Shadow and Flame","Тьма и пламя"],["Hitting an enemy with Conflagrate increases all Shadow damage you deal by 2% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 2% for 20 sec. In addition, Conflagrate has a 20% chance not to consume Immolate, and Shadowburn has a 20% chance to instantly refund a Soul Shard.","\"Когда вы поражаете противника \"Поджиганием\", наносимый урон от темной магии увеличивается на 2% на 20 сек. Когда вы поражаете противника \"Ожогом Тьмы\", наносимый урон от огня увеличивается на 2% на 20 сек. Кроме того, \"Поджигание\" с вероятностью 20% не поглощает \"Жертвенный огонь\", а \"Ожог Тьмы\" с вероятностью 20% мгновенно восстанавливает осколок души.\""],["Hitting an enemy with Conflagrate increases all Shadow damage you deal by 4% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 4% for 20 sec. In addition, Conflagrate has a 40% chance not to consume Immolate, and Shadowburn has a 40% chance to instantly refund a Soul Shard.","\"Когда вы поражаете противника \"Поджиганием\", наносимый урон от темной магии увеличивается на 4% на 20 сек. Когда вы поражаете противника \"Ожогом Тьмы\", наносимый урон от огня увеличивается на 4% на 20 сек. Кроме того, \"Поджигание\" с вероятностью 40% не поглощает \"Жертвенный огонь\", а \"Ожог Тьмы\" с вероятностью 40% мгновенно восстанавливает осколок души.\""],["Hitting an enemy with Conflagrate increases all Shadow damage you deal by 6% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 6% for 20 sec. In addition, Conflagrate has a 60% chance not to consume Immolate, and Shadowburn has a 60% chance to instantly refund a Soul Shard.","\"Когда вы поражаете противника \"Поджиганием\", наносимый урон от темной магии увеличивается на 6% на 20 сек. Когда вы поражаете противника \"Ожогом Тьмы\", наносимый урон от огня увеличивается на 6% на 20 сек. Кроме того, \"Поджигание\" с вероятностью 60% не поглощает \"Жертвенный огонь\", а \"Ожог Тьмы\" с вероятностью 60% мгновенно восстанавливает осколок души.\""],["Hitting an enemy with Conflagrate increases all Shadow damage you deal by 8% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 8% for 20 sec. In addition, Conflagrate has a 80% chance not to consume Immolate, and Shadowburn has a 80% chance to instantly refund a Soul Shard.","\"Когда вы поражаете противника \"Поджиганием\", наносимый урон от темной магии увеличивается на 8% на 20 сек. Когда вы поражаете противника \"Ожогом Тьмы\", наносимый урон от огня увеличивается на 8% на 20 сек. Кроме того, \"Поджигание\" с вероятностью 80% не поглощает \"Жертвенный огонь\", а \"Ожог Тьмы\" с вероятностью 80% мгновенно восстанавливает осколок души.\""],["Hitting an enemy with Conflagrate increases all Shadow damage you deal by 10% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 10% for 20 sec. In addition, Conflagrate has a 100% chance not to consume Immolate, and Shadowburn has a 100% chance to instantly refund a Soul Shard.","\"Когда вы поражаете противника \"Поджиганием\", наносимый урон от темной магии увеличивается на 10% на 20 сек. Когда вы поражаете противника \"Ожогом Тьмы\", наносимый урон от огня увеличивается на 10% на 20 сек. Кроме того, \"Поджигание\" с вероятностью 100% не поглощает \"Жертвенный огонь\", а \"Ожог Тьмы\" с вероятностью 100% мгновенно восстанавливает осколок души.\""],["Incinerate","Испепеление"],["Deals 97 Fire damage to your target and an additional 25% damage if the target is afflicted by Immolate.","Наносит цели 97 ед. урона от огня. Урон увеличивается на 25%, если на цель действует \"Жертвенный огонь\"."]]},"druid":{"build":"1.60.1.70009","className":"Druid","pairs":[["Druid","Друид"],["Balance","Баланс"],["Improved Wrath","Улучшенный гнев"],["Reduces the cast time of your Wrath spell by 0.1 sec and its Mana cost by 10%.","Сокращает время применения \"Гнева\" на 0.1 сек. и снижает затраты маны на его применение на 10%."],["Reduces the cast time of your Wrath spell by 0.2 sec and its Mana cost by 20%.","Сокращает время применения \"Гнева\" на 0.2 сек. и снижает затраты маны на его применение на 20%."],["Reduces the cast time of your Wrath spell by 0.3 sec and its Mana cost by 30%.","Сокращает время применения \"Гнева\" на 0.3 сек. и снижает затраты маны на его применение на 30%."],["Reduces the cast time of your Wrath spell by 0.4 sec and its Mana cost by 40%.","Сокращает время применения \"Гнева\" на 0.4 сек. и снижает затраты маны на его применение на 40%."],["Reduces the cast time of your Wrath spell by 0.5 sec and its Mana cost by 50%.","Сокращает время применения \"Гнева\" на 0.5 сек. и снижает затраты маны на его применение на 50%."],["Genesis","Сотворение"],["Increases the periodic damage and healing done by your spells and abilities by 1%.","Увеличивает периодический урон и силу исцеления ваших заклинаний и способностей на 1%."],["Increases the periodic damage and healing done by your spells and abilities by 2%.","Увеличивает периодический урон и силу исцеления ваших заклинаний и способностей на 2%."],["Increases the periodic damage and healing done by your spells and abilities by 3%.","Увеличивает периодический урон и силу исцеления ваших заклинаний и способностей на 3%."],["Increases the periodic damage and healing done by your spells and abilities by 4%.","Увеличивает периодический урон и силу исцеления ваших заклинаний и способностей на 4%."],["Increases the periodic damage and healing done by your spells and abilities by 5%.","Увеличивает периодический урон и силу исцеления ваших заклинаний и способностей на 5%."],["Moonglow","Лунное сияние"],["Reduces the Mana cost of your damaging spells by 8%.","Снижает затраты маны на наносящие урон заклинания на 8%."],["Reduces the Mana cost of your damaging spells by 17%.","Снижает затраты маны на наносящие урон заклинания на 17%."],["Reduces the Mana cost of your damaging spells by 25%.","Снижает затраты маны на наносящие урон заклинания на 25%."],["Improved Moonfire","Улучшенный лунный огонь"],["Increases the damage and critical strike chance of your Moonfire spell by 5%.","Увеличение урона и шанса на критический удар от вашего заклинания \"Лунный огонь\" на 5%."],["Increases the damage and critical strike chance of your Moonfire spell by 10%.","Увеличение урона и шанса на критический удар от вашего заклинания \"Лунный огонь\" на 10%."],["Nature's Majesty","Величие природы"],["Increases your critical strike chance with spells and melee attacks by 2%.","Повышает вероятность критического удара заклинаний и атак ближнего боя на 2%."],["Increases your critical strike chance with spells and melee attacks by 4%.","Повышает вероятность критического удара заклинаний и атак ближнего боя на 4%."],["Nature's Reach","Предел сил Природы"],["Increases the range of your offensive Balance spells by 10% and improves your chance to hit by 2%.","Увеличивает дальность действия наносящих урон заклинаний специализации \"Баланс\" на 10% и повышает вероятностью попадания на 2%."],["Increases the range of your offensive Balance spells by 20% and improves your chance to hit by 4%.","Увеличивает дальность действия наносящих урон заклинаний специализации \"Баланс\" на 20% и повышает вероятностью попадания на 4%."],["Improved Entangling Roots","Улучшенный гнев деревьев"],["Increases the damage done by your Entangling Roots spell by 25%, and its victims can take up to 25% more damage without interrupting the effect.","Увеличивает урон от \"Гнева деревьев\" на 25%. Обездвиженные цели могут получить на 25% больше урона, прежде чем эффект будет снят."],["Increases the damage done by your Entangling Roots spell by 50%, and its victims can take up to 50% more damage without interrupting the effect.","Увеличивает урон от \"Гнева деревьев\" на 50%. Обездвиженные цели могут получить на 50% больше урона, прежде чем эффект будет снят."],["Increases the damage done by your Entangling Roots spell by 75%, and its victims can take up to 75% more damage without interrupting the effect.","Увеличивает урон от \"Гнева деревьев\" на 75%. Обездвиженные цели могут получить на 75% больше урона, прежде чем эффект будет снят."],["Nature's Splendor","Великолепие природы"],["Increases the duration of your Moonfire and Rejuvenation spells by 3 sec, your Regrowth spell by 6 sec, and your Insect Swarm spell by 2 sec.","Увеличивает время действия заклинаний \"Лунный огонь\" и \"Омоложение\" на 3 сек., \"Восстановления\" – на 6 сек. и \"Роя насекомых\" – на 2 сек."],["Insect Swarm","Рой насекомых"],["The enemy target is swarmed by insects, decreasing their chance to hit with attacks by 2% and causing 48 Nature damage over 12 sec.","Противника атакует рой насекомых, снижающий его вероятность попадания атаками на 2% и наносящий 48 ед. урона от сил природы за 12 сек."],["Vengeance","Отмщение"],["Increases the critical strike damage bonus of your Arcane and Nature spells by 20%.","Увеличивает критический урон от заклинаний тайной магии и сил природы на 20%."],["Increases the critical strike damage bonus of your Arcane and Nature spells by 40%.","Увеличивает критический урон от заклинаний тайной магии и сил природы на 40%."],["Increases the critical strike damage bonus of your Arcane and Nature spells by 60%.","Увеличивает критический урон от заклинаний тайной магии и сил природы на 60%."],["Increases the critical strike damage bonus of your Arcane and Nature spells by 80%.","Увеличивает критический урон от заклинаний тайной магии и сил природы на 80%."],["Increases the critical strike damage bonus of your Arcane and Nature spells by 100%.","Увеличивает критический урон от заклинаний тайной магии и сил природы на 100%."],["Improved Starfire","Улучшенный звездный огонь"],["Reduces the cast time of Starfire by 0.1 sec and Starfire has a 3% chance to stun its target for 3 sec.","Сокращает время применения \"Звездного огня\" на 0.1 сек. \"Звездный огонь\" с вероятностью 3% оглушает цель на 3 сек."],["Reduces the cast time of Starfire by 0.2 sec and Starfire has a 6% chance to stun its target for 3 sec.","Сокращает время применения \"Звездного огня\" на 0.2 сек. \"Звездный огонь\" с вероятностью 6% оглушает цель на 3 сек."],["Reduces the cast time of Starfire by 0.3 sec and Starfire has a 9% chance to stun its target for 3 sec.","Сокращает время применения \"Звездного огня\" на 0.3 сек. \"Звездный огонь\" с вероятностью 9% оглушает цель на 3 сек."],["Reduces the cast time of Starfire by 0.4 sec and Starfire has a 12% chance to stun its target for 3 sec.","Сокращает время применения \"Звездного огня\" на 0.4 сек. \"Звездный огонь\" с вероятностью 12% оглушает цель на 3 сек."],["Reduces the cast time of Starfire by 0.5 sec and Starfire has a 15% chance to stun its target for 3 sec.","Сокращает время применения \"Звездного огня\" на 0.5 сек. \"Звездный огонь\" с вероятностью 15% оглушает цель на 3 сек."],["Overgrowth","Разрастание"],["Increases the maximum number of targets you may have affected by Entangling Roots by 1.","Увеличивает максимальное количество целей, к которым вы можете применить \"Гнев деревьев\", на 1."],["Increases the maximum number of targets you may have affected by Entangling Roots by 2.","Увеличивает максимальное количество целей, к которым вы можете применить \"Гнев деревьев\", на 2."],["Nature's Grace","Благоволение природы"],["All non-periodic spell criticals grace you with a blessing of nature, increasing your spellcasting speed and reducing your global cooldown by 10% for 3 sec.","Когда ваше заклинание прямого действия наносит критический урон, вы получаете благословение природы, повышающее скорость применения заклинаний и сокращающее общее время восстановления на 10% на 3 сек."],["Eclipse","Затмение"],["Your Wrath spell reduces the cast time of your next 2 Starfire spells by 0.17 sec. Stores up to 4 charges. Lasts 15 sec.","\"Гнев\" сокращает время применения 2 следующих заклинаний \"Звездный огонь\" на 0.17 сек. Можно накопить до 4 зарядов. Время действия – 15 сек."],["Your Wrath spell reduces the cast time of your next 2 Starfire spells by 0.33 sec. Stores up to 4 charges. Lasts 15 sec.","\"Гнев\" сокращает время применения 2 следующих заклинаний \"Звездный огонь\" на 0.33 сек. Можно накопить до 4 зарядов. Время действия – 15 сек."],["Your Wrath spell reduces the cast time of your next 2 Starfire spells by 0.50 sec. Stores up to 4 charges. Lasts 15 sec.","\"Гнев\" сокращает время применения 2 следующих заклинаний \"Звездный огонь\" на 0.50 сек. Можно накопить до 4 зарядов. Время действия – 15 сек."],["Moonfury","Лунное неистовство"],["Increases the damage done by your Arcane and Nature spells by 2%.","Увеличивает урон от заклинаний тайной магии и сил природы на 2%."],["Increases the damage done by your Arcane and Nature spells by 4%.","Увеличивает урон от заклинаний тайной магии и сил природы на 4%."],["Increases the damage done by your Arcane and Nature spells by 6%.","Увеличивает урон от заклинаний тайной магии и сил природы на 6%."],["Increases the damage done by your Arcane and Nature spells by 8%.","Увеличивает урон от заклинаний тайной магии и сил природы на 8%."],["Increases the damage done by your Arcane and Nature spells by 10%.","Увеличивает урон от заклинаний тайной магии и сил природы на 10%."],["Moonkin Form","Облик лунного совуха"],["Transforms the Druid into Moonkin Form. While in this form, the armor contribution from items is increased by 360%, Omen of Clarity gains 100% increased chance to trigger, and all party members within 45 yards have their critical strike chance increased by 3%, exclusive with Leader of the Pack. The Moonkin cannot cast healing spells while shapeshifted. The act of shapeshifting frees the caster of Polymorph and Movement Impairing effects.","Вы принимаете облик лунного совуха. В этом облике бонус к броне от снаряжения увеличивается на 360%, вероятность срабатывания \"Знамения ясности\" повышается на 100%, а вероятность критического удара участников группы в радиусе 45 м повышается на 3%. Не суммируется с эффектом \"Вожак стаи\". В облике лунного совуха нельзя применять исцеляющие заклинания. Когда вы меняете облик, вы освобождаетесь от эффектов превращения и затруднения передвижения."],["Feral Combat","Сила зверя"],["Ferocity","Свирепость"],["Heart of the Wild","Сердце дикой природы"],["Increases your Intellect by 2%. In addition, while in Bear Form or Dire Bear Form your Stamina is increased by 4% and while in Cat Form your Strength is increased by 2%.","Повышает интеллект на 2%. Также повышает выносливость в облике медведя и лютого медведя на 4% и повышает силу в облике кошки на 2%."],["Increases your Intellect by 4%. In addition, while in Bear Form or Dire Bear Form your Stamina is increased by 8% and while in Cat Form your Strength is increased by 4%.","Повышает интеллект на 4%. Также повышает выносливость в облике медведя и лютого медведя на 8% и повышает силу в облике кошки на 4%."],["Increases your Intellect by 6%. In addition, while in Bear Form or Dire Bear Form your Stamina is increased by 12% and while in Cat Form your Strength is increased by 6%.","Повышает интеллект на 6%. Также повышает выносливость в облике медведя и лютого медведя на 12% и повышает силу в облике кошки на 6%."],["Increases your Intellect by 8%. In addition, while in Bear Form or Dire Bear Form your Stamina is increased by 16% and while in Cat Form your Strength is increased by 8%.","Повышает интеллект на 8%. Также повышает выносливость в облике медведя и лютого медведя на 16% и повышает силу в облике кошки на 8%."],["Increases your Intellect by 10%. In addition, while in Bear Form or Dire Bear Form your Stamina is increased by 20% and while in Cat Form your Strength is increased by 10%.","Повышает интеллект на 10%. Также повышает выносливость в облике медведя и лютого медведя на 20% и повышает силу в облике кошки на 10%."],["Feral Swiftness","Звериная скорость"],["Increases your movement speed while in Cat Form by 15%, and increases your chance to Dodge by 2%.","Повышает скорость передвижения в облике кошки на 15% и увеличивает вероятность уклонения на 2%."],["Increases your movement speed while in Cat Form by 30%, and increases your chance to Dodge by 4%.","Повышает скорость передвижения в облике кошки на 30% и увеличивает вероятность уклонения на 4%."],["Feral Instinct","Животный инстинкт"],["Increases damage done by your Swipe ability by 10% and reduces the chance enemies have to detect you while Prowling as if you were 1 level higher.","Увеличивает урон от \"Размаха\" на 10% и снижает вероятность того, что противники обнаружат вас во время действия \"Крадущегося зверя\", как если бы ваш уровень был выше на 1."],["Increases damage done by your Swipe ability by 20% and reduces the chance enemies have to detect you while Prowling as if you were 2 levels higher.","Увеличивает урон от \"Размаха\" на 20% и снижает вероятность того, что противники обнаружат вас во время действия \"Крадущегося зверя\", как если бы ваш уровень был выше на 2."],["Increases damage done by your Swipe ability by 30% and reduces the chance enemies have to detect you while Prowling as if you were 3 levels higher.","Увеличивает урон от \"Размаха\" на 30% и снижает вероятность того, что противники обнаружат вас во время действия \"Крадущегося зверя\", как если бы ваш уровень был выше на 3."],["Brutal Impact","Жестокий удар"],["Increases the stun duration of your Bash and Pounce abilities by 0.5 sec and reduces the cooldown of Bash by 15 sec.","Увеличивает длительность оглушения от ваших способностей \"Оглушить\" и \"Наскок\" на 0.5 сек. и сокращает время восстановления способности \"Оглушить\" на 15 сек."],["Increases the stun duration of your Bash and Pounce abilities by 1 sec and reduces the cooldown of Bash by 30 sec.","Увеличивает длительность оглушения от ваших способностей \"Оглушить\" и \"Наскок\" на 1 сек. и сокращает время восстановления способности \"Оглушить\" на 30 сек."],["Thick Hide","Плотная шкура"],["While in Bear Form, Cat Form, Dire Bear Form, or Moonkin Form, you gain 1 additional base Armor per level and another 0.67 base Armor for each point of defense skill beyond five times your level. This amount can be further increased by multipliers from those forms.","В облике медведя, кошки, лютого медведя или лунного совуха ваша базовая броня повышается еще на 1 за каждый уровень, а также еще на 0.67 за каждый уровень навыка защиты, превышающий пятикратный уровень вашего персонажа. Бонусы к броне в данных обликах также действуют на этот эффект."],["While in Bear Form, Cat Form, Dire Bear Form, or Moonkin Form, you gain 2 additional base Armor per level and another 1.33 base Armor for each point of defense skill beyond five times your level. This amount can be further increased by multipliers from those forms.","В облике медведя, кошки, лютого медведя или лунного совуха ваша базовая броня повышается еще на 2 за каждый уровень, а также еще на 1.33 за каждый уровень навыка защиты, превышающий пятикратный уровень вашего персонажа. Бонусы к броне в данных обликах также действуют на этот эффект."],["While in Bear Form, Cat Form, Dire Bear Form, or Moonkin Form, you gain 3 additional base Armor per level and another 2.00 base Armor for each point of defense skill beyond five times your level. This amount can be further increased by multipliers from those forms.","В облике медведя, кошки, лютого медведя или лунного совуха ваша базовая броня повышается еще на 3 за каждый уровень, а также еще на 2.00 за каждый уровень навыка защиты, превышающий пятикратный уровень вашего персонажа. Бонусы к броне в данных обликах также действуют на этот эффект."],["Savage Fury","Бешеное неистовство"],["Increases the damage caused by your Claw, Rake, Shred, Maul, and Swipe abilities by 5%.","Увеличивает урон от способностей \"Когти\", \"Глубокая рана\", \"Полоснуть\", \"Трепка\" и \"Размах\" на 5%."],["Increases the damage caused by your Claw, Rake, Shred, Maul, and Swipe abilities by 10%.","Увеличивает урон от способностей \"Когти\", \"Глубокая рана\", \"Полоснуть\", \"Трепка\" и \"Размах\" на 10%."],["Feral Charge","Звериный рывок"],["$?a5487|a9634[|CFFFFFFFFRequires Bear Form, Dire Bear Form][|CFFFF2020Requires Bear Form, Dire Bear Form] Charge an enemy, immobilizing them and interrupting any spell they are casting for 4 sec. $@spelltooltip414924","$?a5487|a9634[|CFFFFFFFFТребуется облик медведя или лютого медведя][|CFFFF2020Требуется облик медведя или лютого медведя] Вы совершаете рывок к противнику, обездвиживая его и прерывая применение заклинаний на 4 сек. $@spelltooltip414924"],["Sharpened Claws","Острые когти"],["Increases your critical strike chance while in Bear Form, Dire Bear Form, or Cat Form by 3%.","Повышает вероятность критического удара в облике медведя, лютого медведя и кошки на 3%."],["Increases your critical strike chance while in Bear Form, Dire Bear Form, or Cat Form by 6%.","Повышает вероятность критического удара в облике медведя, лютого медведя и кошки на 6%."],["Shredding Attacks","Растерзать противника"],["Reduces the Energy cost of your Shred ability by 6 and reduces the Rage cost of your Lacerate ability by 1.","Снижает затраты энергии на способность \"Полоснуть\" на 6 ед. и снижает затраты ярости на способность \"Растерзать\" на 1 ед."],["Reduces the Energy cost of your Shred ability by 12 and reduces the Rage cost of your Lacerate ability by 2.","Снижает затраты энергии на способность \"Полоснуть\" на 12 ед. и снижает затраты ярости на способность \"Растерзать\" на 2 ед."],["Reduces the Energy cost of your Shred ability by 18 and reduces the Rage cost of your Lacerate ability by 3.","Снижает затраты энергии на способность \"Полоснуть\" на 18 ед. и снижает затраты ярости на способность \"Растерзать\" на 3 ед."],["Predatory Strikes","Удары хищника"],["Increases your melee Attack Power in Cat Form, Bear Form, and Dire Bear Form by 50% of your level.","Повышает силу атаки ближнего боя в облике кошки, медведя и лютого медведя на 50% вашего уровня."],["Increases your melee Attack Power in Cat Form, Bear Form, and Dire Bear Form by 100% of your level.","Повышает силу атаки ближнего боя в облике кошки, медведя и лютого медведя на 100% вашего уровня."],["Increases your melee Attack Power in Cat Form, Bear Form, and Dire Bear Form by 150% of your level.","Повышает силу атаки ближнего боя в облике кошки, медведя и лютого медведя на 150% вашего уровня."],["Gives you a 50% chance to gain an additional $/10;16959s1 Rage any time you get a critical strike while in Bear Form or Dire Bear Form. In addition, your non-periodic critical strikes from Cat Form abilities that generate Combo Points have a 50% chance to add an additional Combo Point.","Когда вы наносите критический удар в облике медведя или лютого медведя, вы с вероятностью 50% накапливаете еще $/10;16959s1 ед. ярости. Кроме того, критические удары способностей прямого действия в облике кошки, увеличивающие длину серии, с вероятностью 50% увеличивают длину серии еще на 1."],["Gives you a 100% chance to gain an additional $/10;16959s1 Rage any time you get a critical strike while in Bear Form or Dire Bear Form. In addition, your non-periodic critical strikes from Cat Form abilities that generate Combo Points have a 100% chance to add an additional Combo Point.","Когда вы наносите критический удар в облике медведя или лютого медведя, вы с вероятностью 100% накапливаете еще $/10;16959s1 ед. ярости. Кроме того, критические удары способностей прямого действия в облике кошки, увеличивающие длину серии, с вероятностью 100% увеличивают длину серии еще на 1."],["Predatory Instincts","Хищный инстинкт"],["Increases the critical strike damage bonus of your melee abilities by 10%.","Увеличивает дополнительный урон от критических ударов ближнего боя на 10%."],["Increases the critical strike damage bonus of your melee abilities by 20%.","Увеличивает дополнительный урон от критических ударов ближнего боя на 20%."],["Leader of the Pack","Вожак стаи"],["While in Cat Form, Bear Form, or Dire Bear Form, the Leader of the Pack increases the critical strike chance of all party members within 45 yards by 3%, exclusive with Moonkin Aura.","В облике кошки, медведя или лютого медведя \"Вожак стаи\" повышает вероятность критического удара участников группы в радиусе 45 м на 3%. Не суммируется с \"Аурой лунного совуха\"."],["King of the Jungle","Король джунглей"],["Tiger's Fury now instantly grants you 20 Energy.","\"Тигриное неистовство\" теперь мгновенно восстанавливает 20 ед. энергии."],["Tiger's Fury now instantly grants you 40 Energy.","\"Тигриное неистовство\" теперь мгновенно восстанавливает 40 ед. энергии."],["Tiger's Fury now instantly grants you 60 Energy.","\"Тигриное неистовство\" теперь мгновенно восстанавливает 60 ед. энергии."],["Natural Reaction","Безусловный рефлекс"],["Increases your dodge chance by 1%, and gives you a 20% chance to gain 5 Rage each time you dodge.","Повышает вероятность уклонения на 1%. Когда вы уклоняетесь от атаки, вы с вероятностью 20% накапливаете 5 ед. ярости."],["Increases your dodge chance by 2%, and gives you a 40% chance to gain 5 Rage each time you dodge.","Повышает вероятность уклонения на 2%. Когда вы уклоняетесь от атаки, вы с вероятностью 40% накапливаете 5 ед. ярости."],["Increases your dodge chance by 3%, and gives you a 60% chance to gain 5 Rage each time you dodge.","Повышает вероятность уклонения на 3%. Когда вы уклоняетесь от атаки, вы с вероятностью 60% накапливаете 5 ед. ярости."],["Increases your dodge chance by 4%, and gives you a 80% chance to gain 5 Rage each time you dodge.","Повышает вероятность уклонения на 4%. Когда вы уклоняетесь от атаки, вы с вероятностью 80% накапливаете 5 ед. ярости."],["Increases your dodge chance by 5%, and gives you a 100% chance to gain 5 Rage each time you dodge.","Повышает вероятность уклонения на 5%. Когда вы уклоняетесь от атаки, вы с вероятностью 100% накапливаете 5 ед. ярости."],["Rend and Tear","Рви и терзай"],["Increases damage done by your melee abilities on Bleeding targets by 2%.","Увеличивает урон от способностей ближнего боя, применяемых к кровоточащим целям, на 2%."],["Increases damage done by your melee abilities on Bleeding targets by 4%.","Увеличивает урон от способностей ближнего боя, применяемых к кровоточащим целям, на 4%."],["Increases damage done by your melee abilities on Bleeding targets by 6%.","Увеличивает урон от способностей ближнего боя, применяемых к кровоточащим целям, на 6%."],["Increases damage done by your melee abilities on Bleeding targets by 8%.","Увеличивает урон от способностей ближнего боя, применяемых к кровоточащим целям, на 8%."],["Increases damage done by your melee abilities on Bleeding targets by 10%.","Увеличивает урон от способностей ближнего боя, применяемых к кровоточащим целям, на 10%."],["Berserk","Берсерк"],["$?a5487|a9634|a3025[|CFFFFFFFFReuires Cat Form, Bear Form, Dire Bear Form][|CFFFF2020Requires Cat Form, Bear Form, Dire Bear Form] Causes your Primal Bite ability to strike up to 3 targets, removes its cooldown, and increases the critical strike chance of your Combo Point-generating abilities by 100%. Clears and grants immunity to Fear effects for the duration. Lasts 15 sec.","$?a5487|a9634|a3025[|CFFFFFFFFReuires Cat Form, Bear Form, Dire Bear Form][|CFFFF2020Requires Cat Form, Bear Form, Dire Bear Form] Causes your Primal Bite ability to strike up to 3 targets, removes its cooldown, and increases the critical strike chance of your Combo Point-generating abilities by 100%. Clears and grants immunity to Fear effects for the duration. Lasts 15 сек."],["Restoration","Исцеление"],["Nature's Focus","Средоточие Природы"],["Gives you a 14% chance to avoid interruption caused by damage while casting Arcane and Nature spells.","С вероятностью 14% применение заклинаний тайной магии и сил природы не прерывается при получении урона."],["Gives you a 28% chance to avoid interruption caused by damage while casting Arcane and Nature spells.","С вероятностью 28% применение заклинаний тайной магии и сил природы не прерывается при получении урона."],["Gives you a 42% chance to avoid interruption caused by damage while casting Arcane and Nature spells.","С вероятностью 42% применение заклинаний тайной магии и сил природы не прерывается при получении урона."],["Gives you a 56% chance to avoid interruption caused by damage while casting Arcane and Nature spells.","С вероятностью 56% применение заклинаний тайной магии и сил природы не прерывается при получении урона."],["Gives you a 70% chance to avoid interruption caused by damage while casting Arcane and Nature spells.","С вероятностью 70% применение заклинаний тайной магии и сил природы не прерывается при получении урона."],["Furor","Гнев"],["Gives you a 20% chance to gain $/10;17057s1 Rage when you shapeshift into Bear Form or Dire Bear Form. When you shift into Cat Form, you will regain 20% of the Energy you had when you were last in Cat Form, plus 2 Energy for each second you spent not in Bear Form, Cat Form, or Dire Bear Form, up to a maximum of 20 Energy.","Когда вы принимаете облик медведя или лютого медведя, вы с вероятностью 20% накапливаете $/10;17057s1 ед. ярости. Когда вы принимаете облик кошки, вы восстанавливаете 20% энергии, остававшейся у вас, когда вы покинули этот облик в прошлый раз, а также еще 2 ед. энергии за каждую секунду, проведенную не в облике медведя, кошки и лютого медведя. Максимум 20 ед. энергии."],["Gives you a 40% chance to gain $/10;17057s1 Rage when you shapeshift into Bear Form or Dire Bear Form. When you shift into Cat Form, you will regain 40% of the Energy you had when you were last in Cat Form, plus 4 Energy for each second you spent not in Bear Form, Cat Form, or Dire Bear Form, up to a maximum of 40 Energy.","Когда вы принимаете облик медведя или лютого медведя, вы с вероятностью 40% накапливаете $/10;17057s1 ед. ярости. Когда вы принимаете облик кошки, вы восстанавливаете 40% энергии, остававшейся у вас, когда вы покинули этот облик в прошлый раз, а также еще 4 ед. энергии за каждую секунду, проведенную не в облике медведя, кошки и лютого медведя. Максимум 40 ед. энергии."],["Gives you a 60% chance to gain $/10;17057s1 Rage when you shapeshift into Bear Form or Dire Bear Form. When you shift into Cat Form, you will regain 60% of the Energy you had when you were last in Cat Form, plus 6 Energy for each second you spent not in Bear Form, Cat Form, or Dire Bear Form, up to a maximum of 60 Energy.","Когда вы принимаете облик медведя или лютого медведя, вы с вероятностью 60% накапливаете $/10;17057s1 ед. ярости. Когда вы принимаете облик кошки, вы восстанавливаете 60% энергии, остававшейся у вас, когда вы покинули этот облик в прошлый раз, а также еще 6 ед. энергии за каждую секунду, проведенную не в облике медведя, кошки и лютого медведя. Максимум 60 ед. энергии."],["Gives you a 80% chance to gain $/10;17057s1 Rage when you shapeshift into Bear Form or Dire Bear Form. When you shift into Cat Form, you will regain 80% of the Energy you had when you were last in Cat Form, plus 8 Energy for each second you spent not in Bear Form, Cat Form, or Dire Bear Form, up to a maximum of 80 Energy.","Когда вы принимаете облик медведя или лютого медведя, вы с вероятностью 80% накапливаете $/10;17057s1 ед. ярости. Когда вы принимаете облик кошки, вы восстанавливаете 80% энергии, остававшейся у вас, когда вы покинули этот облик в прошлый раз, а также еще 8 ед. энергии за каждую секунду, проведенную не в облике медведя, кошки и лютого медведя. Максимум 80 ед. энергии."],["Gives you a 100% chance to gain $/10;17057s1 Rage when you shapeshift into Bear Form or Dire Bear Form. When you shift into Cat Form, you will regain 100% of the Energy you had when you were last in Cat Form, plus 10 Energy for each second you spent not in Bear Form, Cat Form, or Dire Bear Form, up to a maximum of 100 Energy.","Когда вы принимаете облик медведя или лютого медведя, вы с вероятностью 100% накапливаете $/10;17057s1 ед. ярости. Когда вы принимаете облик кошки, вы восстанавливаете 100% энергии, остававшейся у вас, когда вы покинули этот облик в прошлый раз, а также еще 10 ед. энергии за каждую секунду, проведенную не в облике медведя, кошки и лютого медведя. Максимум 100 ед. энергии."],["Naturalist","Натуралист"],["Reduces the cast time of your Healing Touch spell by 0.1 sec and increases all damage you deal by 1%.","Сокращает время применения \"Целительного прикосновения\" на 0.1 сек. и увеличивает наносимый вами урон на 1%."],["Reduces the cast time of your Healing Touch spell by 0.2 sec and increases all damage you deal by 2%.","Сокращает время применения \"Целительного прикосновения\" на 0.2 сек. и увеличивает наносимый вами урон на 2%."],["Reduces the cast time of your Healing Touch spell by 0.3 sec and increases all damage you deal by 3%.","Сокращает время применения \"Целительного прикосновения\" на 0.3 сек. и увеличивает наносимый вами урон на 3%."],["Reduces the cast time of your Healing Touch spell by 0.4 sec and increases all damage you deal by 4%.","Сокращает время применения \"Целительного прикосновения\" на 0.4 сек. и увеличивает наносимый вами урон на 4%."],["Reduces the cast time of your Healing Touch spell by 0.5 sec and increases all damage you deal by 5%.","Сокращает время применения \"Целительного прикосновения\" на 0.5 сек. и увеличивает наносимый вами урон на 5%."],["Subtlety","Скрытность"],["Reduces the threat generated by your Nature and Arcane spells by 10%.","Снижает уровень угрозы, создаваемой заклинаниями сил природы и тайной магии, на 10%."],["Reduces the threat generated by your Nature and Arcane spells by 20%.","Снижает уровень угрозы, создаваемой заклинаниями сил природы и тайной магии, на 20%."],["Reduces the threat generated by your Nature and Arcane spells by 30%.","Снижает уровень угрозы, создаваемой заклинаниями сил природы и тайной магии, на 30%."],["Natural Shapeshifter","Прирожденный оборотень"],["Reduces the mana cost of all shapeshifting by 10%.","Снижение расхода маны на оборотничество на 10%."],["Reduces the mana cost of all shapeshifting by 20%.","Снижение расхода маны на оборотничество на 20%."],["Reduces the mana cost of all shapeshifting by 30%.","Снижение расхода маны на оборотничество на 30%."],["Reflection","Отражение"],["Allows 17% of your Mana regeneration to continue while casting.","В процессе применения заклинаний продолжается 17% от восполнения маны."],["Allows 33% of your Mana regeneration to continue while casting.","В процессе применения заклинаний продолжается 33% от восполнения маны."],["Allows 50% of your Mana regeneration to continue while casting.","В процессе применения заклинаний продолжается 50% от восполнения маны."],["Gift of Nature","Дар природы"],["Increases the effect of all your healing spells by 2%.","Повышает эффективность исцеляющих заклинаний на 2%."],["Increases the effect of all your healing spells by 4%.","Повышает эффективность исцеляющих заклинаний на 4%."],["Increases the effect of all your healing spells by 6%.","Повышает эффективность исцеляющих заклинаний на 6%."],["Increases the effect of all your healing spells by 8%.","Повышает эффективность исцеляющих заклинаний на 8%."],["Increases the effect of all your healing spells by 10%.","Повышает эффективность исцеляющих заклинаний на 10%."],["Gift of the Earthmother","Дар Матери-Земли"],["Reduces the global cooldown by 0.5 seconds on your Rejuvenation, Swiftmend, and Wild Growth spells.","Сокращает общее время восстановления для \"Омоложения\", \"Быстрого восстановления\" и \"Буйного роста\" на 0.5 сек."],["Tranquil Spirit","Мирный дух"],["Reduces the mana cost of your Healing Touch and Tranquility spells by 2%.","Снижение затрат маны на ваши заклинания \"Целительное прикосновение\" и \"Спокойствие\" на 2%."],["Reduces the mana cost of your Healing Touch and Tranquility spells by 4%.","Снижение затрат маны на ваши заклинания \"Целительное прикосновение\" и \"Спокойствие\" на 4%."],["Reduces the mana cost of your Healing Touch and Tranquility spells by 6%.","Снижение затрат маны на ваши заклинания \"Целительное прикосновение\" и \"Спокойствие\" на 6%."],["Reduces the mana cost of your Healing Touch and Tranquility spells by 8%.","Снижение затрат маны на ваши заклинания \"Целительное прикосновение\" и \"Спокойствие\" на 8%."],["Reduces the mana cost of your Healing Touch and Tranquility spells by 10%.","Снижение затрат маны на ваши заклинания \"Целительное прикосновение\" и \"Спокойствие\" на 10%."],["Improved Rejuvenation","Улучшенное омоложение"],["Increases the effect of your Rejuvenation spell by 5%.","Увеличение эффекта от заклинания \"Омоложение\" на 5%."],["Increases the effect of your Rejuvenation spell by 10%.","Увеличение эффекта от заклинания \"Омоложение\" на 10%."],["Increases the effect of your Rejuvenation spell by 15%.","Увеличение эффекта от заклинания \"Омоложение\" на 15%."],["Swiftmend","Быстрое восстановление"],["Instantly heals a target with an active Rejuvenation or Regrowth effect for an amount equal to the full duration of the periodic effect of one of those spells.","Мгновенно восполняет здоровье цели с активным эффектом \"Омоложение\" или \"Восстановление\" в объеме, равном исцелению от периодического эффекта одного из этих заклинаний за все время действия."],["Nature's Swiftness","Природная стремительность"],["When activated, your next Nature spell becomes an instant cast spell.","Мгновенное применение следующего заклинания сил природы."],["Living Spirit","Живой дух"],["Increases your Spirit by 5%.","Повышает дух на 5%."],["Increases your Spirit by 10%.","Повышает дух на 10%."],["Increases your Spirit by 15%.","Повышает дух на 15%."],["Improved Tranquility","Улучшенное спокойствие"],["Reduces threat caused by Tranquility by 50% and its cooldown by 30%.","Снижает уровень угрозы, создаваемой \"Спокойствием\", на 50% и сокращает время восстановления \"Спокойствия\" на 30%."],["Reduces threat caused by Tranquility by 100% and its cooldown by 60%.","Снижает уровень угрозы, создаваемой \"Спокойствием\", на 100% и сокращает время восстановления \"Спокойствия\" на 60%."],["Improved Regrowth","Улучшенное восстановление"],["Increases the critical effect chance of your Regrowth spell by 10%.","Повышает вероятность критического эффекта \"Восстановления\" на 10%."],["Increases the critical effect chance of your Regrowth spell by 20%.","Повышает вероятность критического эффекта \"Восстановления\" на 20%."],["Increases the critical effect chance of your Regrowth spell by 30%.","Повышает вероятность критического эффекта \"Восстановления\" на 30%."],["Increases the critical effect chance of your Regrowth spell by 40%.","Повышает вероятность критического эффекта \"Восстановления\" на 40%."],["Increases the critical effect chance of your Regrowth spell by 50%.","Повышает вероятность критического эффекта \"Восстановления\" на 50%."],["Wild Growth","Буйный рост"],["Heals the target and their party for 280 over 7 sec. Party members must be within 43.5 yards of target. The amount healed is applied quickly at first, and slows down as Wild Growth reaches its full duration.","Восполняет цели и участникам ее группы в радиусе 43.5 м 280 ед. здоровья за 7 сек. Объем исцеления постепенно уменьшается на протяжении действия \"Буйного роста\"."]]}};

  const UI_PAIRS = [
    ['Level', 'Уровень'],
    ['Reset', 'Сбросить'],
    ['Copy link', 'Скопировать ссылку'],
    ['Stream layout', 'Компактный вид'],
    ['Compare to Classic', 'Сравнить с Classic'],
    ['Talents', 'Таланты'],
    ['Reset build', 'Сбросить билд'],
    ['Leveling order', 'Порядок прокачки'],
    ['Your points, level by level.', 'Ваши очки по уровням.'],
    ['Show', 'Показать'],
    ['Hide', 'Скрыть'],
    ['My builds', 'Мои билды'],
    ['Save this build', 'Сохранить билд'],
    ['Name this build', 'Название билда'],
    ['Save', 'Сохранить'],
    ['Cancel', 'Отмена'],
    ['Back up', 'Резервная копия'],
    ['Restore', 'Восстановить'],
    ['Add builds', 'Добавить билды'],
    ['Share', 'Поделиться'],
    ['Send to a friend', 'Отправить другу'],
    ['Theorycraft', 'Теорикрафт'],
    ['Copy build for AI', 'Скопировать билд для ИИ'],
    ['Raw data', 'Исходные данные'],
    ['Racials', 'Расовые способности'],
    ['Legacy perks', 'Наследие'],
    ['How it works', 'Как это работает'],
    ['From the beta client', 'Из beta-клиента'],
    ['Readers catch the rest', 'Остальное находят игроки'],
    ['Calculators:', 'Калькуляторы:'],
    ['On this site:', 'На сайте:'],
    ['Warrior', 'Воин'],
    ['Paladin', 'Паладин'],
    ['Hunter', 'Охотник'],
    ['Rogue', 'Разбойник'],
    ['Priest', 'Жрец'],
    ['Shaman', 'Шаман'],
    ['Mage', 'Маг'],
    ['Warlock', 'Чернокнижник'],
    ['Druid', 'Друид'],
    ['New in Forever', 'Новое в Forever'],
    ['Changed (text, ranks or position)', 'Изменено (текст, ранги или позиция)'],
    ['Moved, same effect', 'Перемещено, эффект тот же'],
    ['Dimmed = unchanged from Classic', 'Затемнено = без изменений относительно Classic'],
    ['Unlearn', 'Убрать'],
    ['Learn', 'Изучить']
  ];

  const translations = new Map(UI_PAIRS);
  const originalText = new Map();
  const originalAttributes = new Map();

  let enabled = localStorage.getItem('tfru-enabled') !== '0';
  let observer = null;

  function normalize(value) {
    return String(value ?? '').replace(/\s+/g, ' ').trim();
  }

  function currentClassSlug() {
    const slug = location.pathname.split('/').filter(Boolean)[0]?.toLowerCase() || '';
    return DB[slug] ? slug : null;
  }

  const classSlug = currentClassSlug();
  const classDb = classSlug ? DB[classSlug] : null;

  if (classDb) {
    for (const [en, ru] of classDb.pairs) {
      if (en && ru && en !== ru && !translations.has(en)) translations.set(en, ru);
    }
  }

  function isOurUi(node) {
    const element =
      node?.nodeType === Node.ELEMENT_NODE
        ? node
        : node?.parentElement;
    return Boolean(element?.closest?.('#' + STATUS_ID));
  }

  function translateDynamic(core) {
    let match;
    if ((match = core.match(/^Points left:\s*(\d+)$/i))) return `Осталось очков: ${match[1]}`;
    if ((match = core.match(/^Level needed:\s*(\d+)$/i))) return `Нужный уровень: ${match[1]}`;
    if ((match = core.match(/^Rank\s+(\d+)(?:\/(\d+))?$/i))) {
      return match[2] ? `Ранг ${match[1]}/${match[2]}` : `Ранг ${match[1]}`;
    }
    if ((match = core.match(/^(\d+)\s+Points?$/i))) return `${match[1]} очк.`;
    if ((match = core.match(/^Requires\s+(\d+)\s+points?\s+in\s+(.+)$/i))) {
      const tree = translations.get(normalize(match[2])) || match[2];
      return `Требуется ${match[1]} очк. в ветке «${tree}»`;
    }
    if ((match = core.match(/^Requires\s+(.+)$/i))) {
      const name = translations.get(normalize(match[1])) || match[1];
      return `Требуется: ${name}`;
    }
    return null;
  }

  function translatedValue(raw) {
    const value = String(raw ?? '');
    const leading = value.match(/^\s*/)?.[0] || '';
    const trailing = value.match(/\s*$/)?.[0] || '';
    const core = normalize(value);
    if (!core) return value;

    const exact = translations.get(core);
    const dynamic = exact ? null : translateDynamic(core);
    const translated = exact || dynamic;
    if (!translated || translated === core) return value;

    return leading + translated + trailing;
  }

  function shouldSkipTextNode(node) {
    if (!node?.parentElement || isOurUi(node)) return true;
    return ['SCRIPT', 'STYLE', 'NOSCRIPT', 'TEXTAREA', 'CODE', 'PRE'].includes(node.parentElement.tagName);
  }

  function translateTextNode(node) {
    if (!enabled || shouldSkipTextNode(node)) return;
    const before = node.nodeValue || '';
    const after = translatedValue(before);
    if (after === before) return;

    if (!originalText.has(node)) originalText.set(node, before);
    node.nodeValue = after;
  }

  function translateAttributes(element) {
    if (!enabled || !(element instanceof Element) || isOurUi(element)) return;

    for (const name of ['placeholder', 'title', 'aria-label', 'value']) {
      if (!element.hasAttribute(name)) continue;
      if (name === 'value' && !['INPUT', 'BUTTON'].includes(element.tagName)) continue;

      const before = element.getAttribute(name);
      if (before == null) continue;
      const after = translatedValue(before);
      if (after === before) continue;

      let attrs = originalAttributes.get(element);
      if (!attrs) {
        attrs = new Map();
        originalAttributes.set(element, attrs);
      }
      if (!attrs.has(name)) attrs.set(name, before);
      element.setAttribute(name, after);
    }
  }

  function translateSubtree(root) {
    if (!enabled || !root || isOurUi(root)) return;

    if (root.nodeType === Node.TEXT_NODE) {
      translateTextNode(root);
      return;
    }

    if (!(root instanceof Element) && root !== document) return;

    if (root instanceof Element) translateAttributes(root);

    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
    let node = walker.currentNode;
    while (node) {
      if (node.nodeType === Node.TEXT_NODE) translateTextNode(node);
      else if (node.nodeType === Node.ELEMENT_NODE) translateAttributes(node);
      node = walker.nextNode();
    }
  }

  function restoreOriginals() {
    for (const [node, value] of originalText) {
      if (node.isConnected) node.nodeValue = value;
    }
    originalText.clear();

    for (const [element, attrs] of originalAttributes) {
      if (!element.isConnected) continue;
      for (const [name, value] of attrs) element.setAttribute(name, value);
    }
    originalAttributes.clear();
  }

  function ensureStatus() {
    let button = document.getElementById(STATUS_ID);
    if (button) return button;

    button = document.createElement('button');
    button.id = STATUS_ID;
    button.type = 'button';

    Object.assign(button.style, {
      position: 'fixed',
      right: '12px',
      bottom: '12px',
      zIndex: '2147483647',
      border: '1px solid rgba(80,220,120,.55)',
      borderRadius: '8px',
      padding: '7px 10px',
      background: 'rgba(12,12,14,.94)',
      color: '#e8e8ea',
      font: '12px/1.25 system-ui, sans-serif',
      cursor: 'pointer',
      boxShadow: '0 4px 16px rgba(0,0,0,.35)'
    });

    button.addEventListener('click', () => {
      enabled = !enabled;
      localStorage.setItem('tfru-enabled', enabled ? '1' : '0');

      if (enabled) translateSubtree(document);
      else restoreOriginals();

      updateStatus();
    });

    document.documentElement.appendChild(button);
    return button;
  }

  function updateStatus() {
    const button = ensureStatus();
    const state = enabled ? 'RU ON' : 'RU OFF';
    const build = classDb?.build ? ' · DB ' + classDb.build : '';
    button.textContent = state + build;
    button.title =
      `Talents Forever RU v${VERSION}` +
      (classDb?.build ? `\nruRU DB build: ${classDb.build}` : '') +
      '\nНажмите, чтобы включить/выключить перевод';
  }

  function observeDom() {
    observer?.disconnect();

    observer = new MutationObserver((mutations) => {
      if (!enabled) return;

      for (const mutation of mutations) {
        if (isOurUi(mutation.target)) continue;

        if (mutation.type === 'characterData') {
          translateTextNode(mutation.target);
          continue;
        }

        for (const node of mutation.addedNodes) {
          if (!isOurUi(node)) translateSubtree(node);
        }
      }
    });

    observer.observe(document.documentElement, {
      childList: true,
      subtree: true,
      characterData: true
    });
  }

  ensureStatus();
  translateSubtree(document);
  observeDom();
  updateStatus();

  console.info(
    '[Talents Forever RU]',
    `v${VERSION}`,
    classSlug ? `${classSlug} / DB ${classDb.build}` : 'UI-only page',
    `${translations.size} translations loaded`
  );
})();
